(window.GIM_TS=window.GIM_TS||{})["Shabbat.2"]={"from":48,"a":[["\u0003לימא מר\u0004 \u0005[יאמר אדוני]\u0006 נימוק אחר: \u0003מפני שהוא,\u0004 הצרי \u0003עף,\u0004 כלומר, שהוא עשוי להתאדות במהירות רבה ולגרום לדליקה. ומשיבים: \u0003חדא\u0004 \u0005[\u0006סיבה \u0005אחת]\u0006 \u0003ועוד\u0004 אחת \u0003קאמר\u0004 \u0005[אמר]:\u0006 \u0003חדא\u0004 \u0005[אחת]\u0006 — \u0003מפני שהוא עף,\u0004 ויש בכך סכנה. \u0003ועוד\u0004 — \u0003גזירה שמא יסתפק ממנו.\u0004","ומסופר: \u0003ההיא חמתא דהות סניאה לה\u0004 \u0005[חמות אחת שהיתה שונאת אותה\u0006\u0003]\u0004 את \u0003כלתה, אמרה לה: זיל איקשיט במשחא דאפרסמא\u0004 \u0005[לכי התקשטי בשמן אפרסמון].\u0006 \u0003אזלא איקשיט\u0004 \u0005[הלכה\u0006 ו\u0005התקשטה].\u0006 \u0003כי אתת\u0004 \u0005[כאשר באה]\u0006 \u0003אמרה לה\u0004 חמותה: \u0003זיל איתלי שרגא\u0004 \u0005[לכי הדליקי נר].\u0006 \u0003אזלא אתלא שרגא\u0004 \u0005[הלכה\u0006 ו\u0005הדליקה נר].\u0006 \u0003אינפח\u0004 \u0005[אחזה]\u0006 \u0003בה נורא ואכלתה\u0004 \u0005[האש ושרפתה].\u0006","וכיון שהוזכר אפרסמון, מביאים את הנאמר בכתוב: \u0003\"ומדלת הארץ השאיר נבוזראדן רב טבחים לכרמים וליגבים\"\u0004 (ירמיה נב, טז). ומבארים את דברי הכתוב: על מה שנאמר \u0003\"כורמים\" תני\u0004 \u0005[שנה]\u0006 \u0003רב יוסף\u0004 שבני דלת הארץ \u0003אלו\u0004 היו \u0003מלקטי\u0004 ה\u0003אפרסמון\u0004 בשטח \u0003מעין גדי ועד רמתא.\u0004 וה\u0003\"יוגבים\"\u0004 — \u0003אלו ציידי חלזון מסולמות של צור ועד חיפה.\u0004 שמלאכות אלה של ליקוט בלבד, מלאכות עניות הן, שרק מעטים יכלו להתפרנס מהן ובדוחק.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אין מדליקין בטבל\u0004 (תבואה שלא הופרשה ממנה תרומה כלל) \u0003טמא בחול,\u0004 לפי שהוא אסור בהנאה. \u0003ואין צריך לומר\u0004 שאין מדליקים בו \u0003בשבת. כיוצא בו, אין מדליקין בנפט לבן בחול, ואין צריך לומר\u0004 שאין מדליקים בו \u0003בשבת. בשלמא\u0004 \u0005[נניח]\u0006 לגבי \u0003נפט לבן\u0004 מובן הדבר שהוא אסור — \u0003מפני שהוא עף\u0004 ויש בכך חשש סכנה, \u0003אבל טבל טמא מאי טעמא\u0004 \u0005[מה טעם]\u0006 אסרו חכמים להשתמש בו?","ומשיבים: מקור הדבר הוא במה ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"ואני הנה נתתי לך את משמרת תרומתי\"\u0004 (במדבר יח, ח), ולמדו מכאן ש\u0003בשתי תרומות הכתוב מדבר: אחת תרומה טהורה ואחת תרומה טמאה.\u0004 ולומדים מכאן: \u0003מה תרומה טהורה אין לך\u0004 (לכהן) \u0003בה\u0004 היתר ליהנות ממנה \u0003אלא משעת הרמה ואילך, אף תרומה טמאה אין לך\u0004 היתר להשתמש \u0003בה אלא משעת הרמה ואילך.\u0004 והטבל, מאחר שיש בתוכו חלק של תרומה (שעדיין לא הופרש) אסור אף הכהן להשתמש בו.","עתה באים לדון \u0003גופא\u0004 \u0005[לגופה]\u0006 של אותה תוספתא שהובאה מקודם בענין הדלקת נר שבת בצרי במלואה. \u0003ר' שמעון בן אלעזר אומר: אין מדליקין בצרי בשבת. וכן היה ר' שמעון בן אלעזר אומר:\u0004 ה\u0003צרי,\u0004 אשר שימש אחד מן הסממנים שהיו מרכיבים את הקטורת, \u0003אינו אלא שרף\u0004 היוצא \u0003מעצי הקטף\u0004 ולא עץ הקטף עצמו. \u0003ר' ישמעאל אומר: כל היוצא מן העץ אין מדליקין בו,\u0004 אלא בשאר דברים שאינם עץ. ואילו \u0003ר' ישמעאל בן ברוקא אומר: אין מדליקין אלא ביוצא מן הפרי. ר' טרפון אומר: אין מדליקין אלא בשמן זית בלבד.\u0004","ומסופר ש\u0003עמד ר' יוחנן בן נורי על רגליו ואמר\u0004 כנגד דברים אלה: \u0003ומה יעשו אנשי בבל שאין להם אלא שמן שומשמין, ומה יעשו אנשי מדי שאין להם אלא שמן אגוזים, ומה יעשו אנשי אלכסנדריא שאין להם אלא שמן צנונות, ומה יעשו אנשי קפוטקיא שאין להם לא כך ולא כך אלא נפט? אלא אין לך אלא מה שאמרו חכמים\u0004 ש\u0003אין מדליקין\u0004 בו ואין להוסיף חומרות יתירות.","\u0003ומדליקין בשמן דגים ובעטרן. ר' שמעון שזורי אומר: מדליקין בשמן פקועות ובנפט. סומכוס אומר: כל היוצא מן הבשר\u0004 (מבעל חיים) \u0003אין מדליקין בו, אלא בשמן דגים\u0004 בלבד. ושואלים: והלא שיטת \u0003סומכוס היינו\u0004 \u0005[זוהי]\u0006 בדיוק שיטת ה\u0003תנא קמא\u0004 \u0005[הראשון],\u0006 שגם הוא מתיר להדליק בשמן דגים? ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם,\u0006 הבדל למעשה\u0005]\u0006 ביחס למה ש\u0003רב ברונא אמר\u0004 בשם \u0003רב\u0004 שחלב מותך שהוסיפו לו שמן, מותר להדליק בו, שבכך דעותיהם חלוקות, \u0003ו\u0004אולם \u0003לא מסיימי\u0004 \u0005[אין\u0006 הם \u0005מוגדרים]\u0006 שאיננו יודעים מי מהם האוסר ומי מהם המתיר בנושא זה.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' שמעון בן אלעזר אומר: כל היוצא מן העץ אין בו משום שלש על שלש,\u0004 שאף אם יש בשטחו שלוש על שלוש אצבעות אינו נחשב גדול למדי כדי לקבל טומאה. \u0003ו\u0004משום כך \u0003מסככין בו\u0004 את הסוכה, שיש להקפיד שלא יהא הסכך מדבר המקבל טומאה. כל זה \u0003חוץ מפשתן,\u0004 שיש בו דינים מיוחדים. \u0003אמר אביי:\u0004"],["\u0003ר' שמעון בן אלעזר ו\u0004כן ה\u0003תנא דבי\u0004 \u0005[מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל אמרו דבר אחד\u0004 ביסודו אף כי לא באותה צורה. ומפרטים: שיטת \u0003ר' שמעון בן אלעזר\u0004 היא \u0003הא דאמרן\u0004 \u0005[זה שאמרנו]\u0006 עתה שבאריגים מן הצומח נחשב לאריג ממש רק העשוי מפשתן בלבד. ושיטת ה\u0003תנא דבי\u0004 \u0005[מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל מאי\u0004 \u0005[מה]\u0006 \u0003היא?\u0004 — \u0003דתני דבי\u0004 \u0005[ששנה\u0006 התנא \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל: הואיל ונאמרו \"בגדים \" בתורה סתם\u0004 ולא פורש מאלו חמרים עשויים בגדים אלה, \u0003ופרט לך הכתוב באחד מהן,\u0004 בדיני טומאת נגעים, \u0003צמר ופשתים\u0004 (\"והבגד כי יהיה בו נגע צרעת בבגד צמר או בבגד פשתים\". ויקרא יג, מז), יש לומר כי \u0003מה להלן\u0004 בנושא זה \"בגד\" משמעו העשוי מ\u0003צמר\u0004 או מ\u0003פשתים, אף כל\u0004 בגדים האמורים בתורה אינם אלא \u0003צמר ופשתים,\u0004 ואריגים אחרים אינם נכללים במובן \"בגד\".","בניגוד לאביי שראה בשיטות ר' שמעון בן אלעזר ותנא כהן רעיון אחד, \u0003רבא אמר\u0004 כי שתי השיטות אינן זהות וביחס לפיסת אריג גדולה בהרבה שיש בה \u0003שלשה על שלשה\u0004 טפחים \u0003בשאר בגדים\u0004 שאינם צמר ופשתים \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל\u0005].\u0006 ש\u0003ר' שמעון בן אלעזר\u0004 האומר במפורש \"אין בו שלוש על שלש (אצבעות)\", משמע כי במטלית בת שלושה טפחים על שלושה הראויה אף לעשירים \u0003אית ליה\u0004 \u0005[יש לו,\u0006 סבור\u0005]\u0006 שהיא מקבלת טומאה, כי בגד הפשתים אינו מיוחד בעצם העובדה שהוא מקבל טומאה אלא בכך שאף מטלית קטנה ממנו מקבלת טומאה. ואילו \u0003ל\u0004דעת ה\u0003תנא דבי\u0004 \u0005[מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל לית ליה\u0004 \u0005[אין לו,\u0006 אינו סבור\u0005]\u0006 שבגדים אחרים מקבלים בכלל טומאה.","ממה ששנינו מקודם משמע \u0003דכולי עלמא מיהת\u0004 \u0005[לדעת הכל בכל אופן]\u0006 ברור כי \u0003שלש על שלש\u0004 אצבעות \u0003ב\u0004בגד \u0003צמר ופשתים מיטמא ב\u0004טומאת \u0003נגעים\u0004 ושואלים: \u0003מנא לן\u0004 \u0005[מנין לנו]\u0006 שכך הוא? ומשיבים: \u0003דתניא\u0004 \u0005ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 העוסקת בענין זה: מן האמור בתורה \u0003\"בגד\"\u0004 סתם \u0003אין לי אלא\u0004 לחשוב ביחס ל\u0003בגד\u0004 שלם ממש שהוא מיטמא, ואולם מטלית בת \u0003שלש על שלש\u0004 אצבעות \u0003מנין\u0004 שאף היא בכלל זה? — \u0003תלמוד לומר: \"והבגד\u0004 כי יהיה בו נגע צרעת\u0003\"\u0004 (ויקרא יג, יז), שמתוספת הלשון \"והבגד\" למדים אנו שכל דבר ארוג נכנס, לענין זה, בכלל בגד. ושואלים: \u0003ואימא\u0004 \u0005[ו\u0006שמא \u0005אמור]\u0006 כי הכוונה היא \u0003לרבות\u0004 אריג של \u0003שלשה על שלשה\u0004 טפחים? ומשיבים: דבר זה לא יתכן, שכן \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003קל וחומר הוא?\u0004 שכן \u0003השתא\u0004 \u0005[עכשיו],\u0006 הרי יודעים אנו שאפילו חוטי \u0003שתי\u0004 או חוטי \u0003ערב מיטמא,\u0004 ואם כן מטלית בת \u0003שלשה על שלשה\u0004 טפחים \u0003מיבעיא\u0004 \u0005[צריך לומר]?!\u0006 והרי בבגד שיש בו שלושה על שלושה טפחים כבר יש כמות מספיקה של חוטי ערב ושתי הנטמאים מכוח עצמם!","ודוחים: \u0003אי הכי, שלש על שלש\u0004 אצבעות \u0003נמי ליתי\u0004 \u0005[גם כן נביא,\u0006 נלמד\u0005]\u0006 \u0003בקל וחומר\u0004 משתי וערב! \u0003אלא\u0004 צריך לומר כי קל וחומר זה אינו מושלם, שכיון שנעשו החוטים אריג, שוב אינם נמצאים בדרגה שהיו בה קודם, ואינם ראויים עוד לשימוש בשתי ובערב. ולכך יש לומר כי אריג של \u0003שלשה על שלשה\u0004 טפחים \u0003דחזו\u0004 \u0005[שראויים]\u0006 לשימוש \u0003בין לעשירים בין לעניים,\u0004 שכן זו פיסת אריג שמשתמשים בה לצרכים שונים, אכן \u0003אתי\u0004 \u0005[באה\u0006 נלמדת\u0005]\u0006 \u0003בקל וחומר,\u0004 שודאי רבה חשיבותה משתי וערב, ומקבלת טומאה. ואולם אריג של \u0003שלש על שלש\u0004 אצבעות ש\u0003לעניים הוא דחזיין\u0004 \u0005[שראויים]\u0006 ואילו \u0003לעשירים לא חזיין\u0004 \u0005[אינם ראויים]\u0006 — \u0003לא אתי\u0004 \u0005[אינו בא,\u0006 נלמד\u0005]\u0006 \u0003בקל וחומר.\u0004 ועל כן \u0003טעמא\u0004 \u0005[הטעם]\u0006 דווקא משום \u0003דכתביה קרא\u0004 \u0005[שכתבו המקרא],\u0006 \u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003לא כתביה קרא\u0004 \u0005[כתבו המקרא]\u0006 — \u0003לא גמרינן\u0004 \u0005[אין אנו לומדים]\u0006 \u0003בקל וחומר.\u0004 אלא כיון שיש לשון ריבוי בכתוב, וגם קל וחומר, למדים כך. ועוד שואלים: אכן יש בתורה לשון ריבוי, \"והבגד\", שהוא כלל המרחיב את הפרטים הבאים לאחר מכן.","\u0003ו\u0004אולם שמא \u0003אימא\u0004 \u0005[אמור]\u0006 כי בא דבר זה \u0003לרבות\u0004 מטלית בת \u0003שלשה על שלשה\u0004 טפחים \u0003בשאר בגדים\u0004 שאינם צמר ופשתים שהיא מיטמאה? ומשיבים: דבר זה לא יתכן, שהרי \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"בגד צמר ופשתים\",\u0004 ומזה משמע כי \u0003בגד צמר ופשתים\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 ואולם \u0003מידי אחריני\u0004 — \u0003לא.\u0004 ושואלים: \u0003ואימא כי אימעוט\u0004 \u0005[ו\u0006שמא \u0005תאמר,\u0006 כי \u0005כאשר מיעט\u0006 הכתוב\u0005]\u0006 הרי זה דווקא בבגד של \u0003שלש על שלש\u0004 אצבעות, \u0003אבל\u0004 בגד של \u0003שלשה על שלשה\u0004 טפחים — \u0003מיטמא!\u0004 ומשיבים: \u0003תרי מיעוטי כתיבי\u0004 \u0005[שני מיעוטים כתובים],\u0006 שנאמר פעם אחת \"בגד צמר או הפשתים\" (ויקרא יג, נט), ונאמר \u0003\"\u0004ב\u0003בגד צמר או בבגד פשתים\"\u0004 (ויקרא יג, מז), ובא \u0003חד למעוטי\u0004 \u0005[\u0006כתוב \u0005אחד למעט]\u0006 \u0003משלש על שלש\u0004 אצבעות, \u0003וחד למעוטי\u0004 \u0005[ו\u0006כתוב \u0005אחד למעט]\u0006 \u0003משלשה על שלשה\u0004 טפחים, ולהדגיש שבגד שאינו של צמר ופשתים אינו מקבל טומאה כלל. וכל זה נאמר לפי שיטת אביי שבגדים שאינם צמר או פשתן אינם מקבלים טומאה.","ושואלים: \u0003ו\u0004אולם \u0003ל\u0004שיטת \u0003רבא\u0004 ש\u0003אמר\u0004 כי נחלקו הדעות, ו\u0003שלשה על שלשה\u0004 טפחים \u0003בשאר בגדים ל\u0004דעת \u0003ר' שמעון בן אלעזר אית ליה\u0004 \u0005[יש לו,\u0006 סבור\u0005]\u0006 כי הם מקבלים טומאה, ואילו \u0003לתנא דבי\u0004 \u0005[מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל לית ליה\u0004 \u0005[אין לו,\u0006 אינו סבור\u0005]\u0006 שהם מקבלים טומאה, אם כן מטלית בת \u0003שלשה על שלשה\u0004 טפחים \u0003בשאר בגדים\u0004"],["\u0003מנא ליה\u0004 \u0005[מנין לו]\u0006 שהיא מקבלת טומאה? ומשיבים: לדעתו \u0003נפקא\u0004 \u0005[יוצא,\u0006 נלמד\u0005]\u0006 דבר זה \u0003מ\u0004הכתוב בטומאת שרצים \u0003\"או בגד\u0004 או עור או שק\u0003\"\u0004 (ויקרא יא, לב), שהתוספת \"או\" באה לכלול בתוכה גם פריטים שאינם מוגדרים בעצם המלה \"בגד\". \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 ממה שנאמר \u0003\"בגד\" אין לי\u0004 להבין \u0003אלא\u0004 כפשטו \u0003בגד\u0004 שלם ממש, ואולם אריג של \u0003שלשה על שלשה\u0004 טפחים \u0003בשאר בגדים מניין\u0004 שהוא מקבל טומאה? \u0003תלמוד לומר: \"או בגד\".\u0004","ושואלים: \u0003ואביי\u0004 האומר שלדעת הכל שאר בגדים אינם מקבלים טומאה כלל, אם כן המילים \u0003\"או בגד \" מאי עביד ליה\u0004 \u0005[מה הוא עושה בו],\u0006 ומה בא ביטוי זה להוסיף? ומשיבים: \u0003מיבעי ליה\u0004 \u0005[צריך הוא לו]\u0006 \u0003לרבות\u0004 פיסת אריג קטנה בת \u0003שלש על שלש\u0004 אצבעות \u0003בצמר ופשתים\u0004 שלמרות היותה קטנה כל כך הריהי \u0003מטמא ב\u0004טומאת \u0003שרצים.\u0004","\u0003ורבא\u0004 סבור שאין צורך שידון המקרא במפורש בנושא זה, שכן \u0003גלי רחמנא גבי\u0004 \u0005[גילה הכתוב אצל]\u0006 \u0003נגעים\u0004 שדבר זה נחשב לבגד, \u0003והוא הדין ל\u0004טומאת \u0003שרצים.\u0004","\u0003ואביי\u0004 סבור שאין ללמוד מדיני נגעים על דיני שרצים, שכן \u0003איכא למיפרך\u0004 \u0005[אפשר לפרוך,\u0006 לשבור\u0005]\u0006 את ההשוואה בדרך זו: שכן \u0003מה ל\u0004השוואה עם ה\u0003נגעים\u0004 שחמורים דיני טומאת נגעים, \u0003שכן\u0004 אפילו \u0003שתי וערב\u0004 בלבד \u0003מטמא בהם,\u0004 מה שאין כן בטומאת שרצים, ולכן אף פיסות קטנות מיטמאות בנגעים.","\u0003ואידך\u0004 \u0005[האחר,\u0006 רבא\u0005]\u0006 אומר: \u0003אי סלקא דעתך\u0004 \u0005[אם יעלה על דעתך]\u0006 לומר כי ה\u0003נגעים חמירי\u0004 \u0005[חמורים],\u0006 אם כן \u0003לכתוב רחמנא גבי\u0004 \u0005[תכתוב התורה אצל]\u0006 \u0003שרצים וליתו\u0004 \u0005[ויבואו,\u0006 יילמדו\u0005]\u0006 ה\u0003נגעים מינייהו\u0004 \u0005[מהם],\u0006 שהרי סוף סוף מושווים שני הדינים בתורה ופשוט היה יותר לכתוב במפורש בדיני שרצים וללמוד מהם. ומאחר שאין הדבר כך הרי זו הוכחה שאפשר ללמוד דיני שרצים מנגעים.","\u0003ואידך\u0004 \u0005[והאחר,\u0006 אביי\u0005]\u0006 אומר כי טענה זו אינה מבוססת מעיקרה כי \u0003נגעים משרצים לא אתו\u0004 \u0005[אינם באים,\u0006 נלמדים\u0005]\u0006 \u0003דאיכא למיפרך\u0004 \u0005[ש\u0006כן \u0005יש\u0006 אפשרות \u0005לפרוך,\u0006 לשבור\u0005]\u0006 לימוד ולהקשות: \u0003מה ל\u0004טומאת \u0003שרצים\u0004 שחמורה היא מטומאת נגעים, \u0003שכן\u0004 השרץ \u0003מטמא\u0004 אפילו בגודל \u0003עדשה,\u0004 מה שאין כן בשאר טומאות. ולכן הוצרכו הכתובים גם בשרצים וגם בנגעים.","\u0003אמר אביי: האי\u0004 \u0005[זה]\u0006 ה\u0003תנא דבי\u0004 \u0005[מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל מפיק מאידך תנא דבי\u0004 \u0005[מוציא,\u0006 חולק, \u0005על תנא אחר מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל. דתני\u0004 \u0005[ש\u0006כן \u0005שנה]\u0006 ה\u0003תנא דבי\u0004 \u0005[מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל:\u0004 ממה שנאמר \u0003\"בגד\" אין לי\u0004 להבין \u0003אלא\u0004 כפשטו \u0003בגד צמר ופשתים\u0004 שהוא המקבל טומאה, ואולם \u0003מניין לרבות\u0004 בגד \u0003העשוי מצמר גמלים\u0004 או מ\u0003צמר ארנבים,\u0004 או \u0003נוצה\u0004 (שיער) \u0003של עזים ו\u0004כן \u0003השירין והכלך והסריקין\u0004 (מיני משי) שכולם מקבלים טומאה? — \u0003תלמוד לומר: \"או בגד\"\u0004 שבאה המלה \"או\" לרבות ולכלול את כל מיני האריגים.","ואילו \u0003רבא אמר:\u0004 אין צורך לומר שיש פה מחלוקת בין תנאים מבית מדרש אחד, אלא: \u0003כי לית ליה להך\u0004 \u0005[כאשר אין לו\u0006 \u0003לזה]\u0004 ה\u0003תנא דבי\u0004 \u0005[מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל\u0004 שהוזכרה דעתו קודם, טומאה \u0003בשאר בגדים,\u0004 הרי זה רק כאשר מדובר בפיסת אריג של \u0003שלש על שלש\u0004 אצבעות, אבל אריג של \u0003שלשה על שלשה\u0004 טפחים \u0003אית ליה\u0004 \u0005[יש לו]\u0006 אף הוא סבור כי הוא מקבל טומאה. והדברים הקודמים היו למעט בגד קטן מקבלת טומאה, וכאן המדובר בבגד גדול יותר של שלושה על שלושה טפחים.","ושואלים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רבא הוא\u0004 ש\u0003אמר\u0004 מקודם ב\u0003שלשה על שלשה\u0004 טפחים \u0003בשאר בגדים לר' שמעון בן אלעזר אית ליה\u0004 \u0005[יש לו,\u0006 הוא סבור\u0005]\u0006 שהוא מקבל טומאה, ואילו \u0003לתנא דבי\u0004 \u0005[מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל לית ליה\u0004 \u0005[אין לו,\u0006 אינו סבור\u0005]\u0006 שהם מקבלים טומאה! ומשיבים: \u0003הדר ביה\u0004 \u0005[חזר בו]\u0006 \u0003רבא מ\u0004הדעה \u0003ההיא\u0004 כדי להשוות שיטות תנא דבי ר' ישמעאל. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 תירוץ אחר, כי \u0003הא\u0004 \u0005[\u0006אימרה \u0005זו]\u0006 \u0003רב פפא אמרה,\u0004 ולא רבא, אלא כיון שהיה רב פפא תלמיד מובהק של רבא, ייחסו את דבריו אלה לרבו.","\u0003רב פפא\u0004 עצמו הבין את דברי תנא דבי ר' ישמעאל הראשונים ו\u0003אמר\u0004 באופן שונה לגמרי, שלדעתו אותו לימוד מדיני נגעים שאמר ש\u0003אף כל\u0004 הבגדים האמורים בתורה סתם הם צמר ופשתים, הוא לענין דיני \u0003כלאים\u0004 (שעטנז), שאסרה התורה ללבוש בגדים שיש בהם שני סוגי חוטים. ורצה להוכיח שאין דין שעטנז אלא בצמר ופשתים בלבד. ושואלים: לשם מה צריך הוא ללימוד זה על איסור \u0003כלאים\u0004 והלא זה שהאיסור הוא בצמר ופשתים \u0003בהדיא כתיבי ביה\u0004 \u0005[במפורש כתובים בו],\u0006 כאמור: \u0003\"לא תלבש שעטנז צמר ופשתים יחדו\"\u0004 (דברים כב, יא). ומשיבים: בכל זאת דרוש היה לימוד נוסף כי \u0003סלקא דעתך אמינא\u0004 \u0005[היה עולה על דעתך לומר]\u0006 כי \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 שאיסור שעטנז הוא רק בצמר ופשתים, הרי זה דווקא כאשר משתמש הוא בהם יחד ב\u0003דרך לבישה, אבל בהעלאה\u0004 (כשמניח עליו בגדים כאלה, ואינו לובשם) \u0003כל תרי מיני\u0004 \u0005[שני מינים]\u0006 \u0003אסור,\u0004 והיה צורך להוכיח ש\"בגד\" האמור כאן הוא רק מצמר ופשתים.","טענה זו נדחית: \u0003ולאו\u0004 \u0005[והאם לא]\u0006 \u0003קל וחומר הוא?\u0004 שכן יכול אתה לומר: \u0003מה לבישה דקא מיתהני כולי גופיה\u0004 \u0005[שנהנה כל גופו]\u0006 \u0003מ\u0004ה\u0003כלאים, אמרת\u0004 ש\u0003צמר ופשתים\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 נכלל באיסור, אבל \u0003מידי אחרינא\u0004 \u0005[דבר אחר]\u0006 \u0003לא\u0004 נכלל באיסור. \u0003העלאה\u0004 של הבגד בלבד \u0003לא כל שכן\u0004 שלא נחמיר בה יותר? \u0003אלא\u0004 ודאי שההלכה שיוחסה ל\u0003רב פפא בדותא היא,\u0004 והוא לא אמרה.","\u0003רב נחמן בר יצחק אמר\u0004 אף הוא כי אותם דברי תנא דבי ר' ישמעאל לא נאמרו לענין דיני טומאה אלא בנושא אחר! שלדעתו בא התנא דבי ר' ישמעאל לומר כי כשם שבדיני נגעים בגדים הם צמר ופשתים בלבד \u0003אף כל\u0004"],["\u0003לאתויי\u0004 \u0005[להביא]\u0006 דין \u0003ציצית,\u0004 שאין חובת ציצית אלא בחומרים אלה. ושואלים: לשם מה יש צורך בלימוד זה, והרי \u0003ציצית בהדיא\u0004 \u0005[במפורש]\u0006 כך \u0003כתיב\u0004 \u0005[נאמר]\u0006 בה \u0003\"לא תלבש שעטנז צמר ופשתים יחדו\"\u0004 (דברים כב, יא), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 בפסוק הסמוך \u0003\"גדילים תעשה לך\u0004 על ארבע כנפות כסותך אשר תכסה בה \u0003\"\u0004ומסמיכות זו למדנו שמצות גדילי הציצית היא רק בדברים שיש בהם דין שעטנז. על כך משיב רב נחמן בר יצחק שאין הדבר ברור כל כך, כי \u0003סלקא דעתך אמינא\u0004 \u0005[היה עולה על דעתך לומר]\u0006 \u0003כ\u0004דברי \u0003רבא,\u0004 ש\u0003רבא רמי\u0004 \u0005[השליך\u0006 הראה סתירה בין דברים\u0005]:\u0006 שכן מצד אחד \u0003כתיב\u0004 \u0005[נאמר]\u0006 \"ונתנו על ציצית \u0003הכנף\u0004 פתיל תכלת\" (במדבר טו, לט), ונראה מכאן שהציצית צריכה להיות מ\u0003מין\u0004 ה\u0003כנף,\u0004 שמאותו אריג שממנו נעשה הבגד יש לעשות את חוטי הציצית. \u0003ו\u0004אילו בספר דברים \u0003כתיב\u0004 \u0005[נאמר]\u0006 בהיקש לדיני שעטנז \u0003\"צמר ופשתים יחדו\",\u0004 הרי שהציצית נעשית רק מחמרים אלה, ואם כן \u0003הא\u0004 \u0005[הרי]\u0006 \u0003כיצד\u0004 אתה מיישב בין הכתובים? אלא אומר רבא: פתילים העשויים מ\u0003צמר ופשתים פוטרין\u0004 את הבגד ומקיימים בו חובת ציצית \u0003בין במינן\u0004 (בבגד העשוי מצמר או פשתים), \u0003בין שלא במינן.\u0004 ואילו \u0003שאר מינין במינן פוטרין\u0004 הם ואילו \u0003שלא במינן\u0004 אין הם \u0003פוטרין.\u0004 ואם כן, \u0003סלקא דעתך\u0004 \u0005[היה עולה על\u0006 \u0003דעתך]\u0004 לפרש \u0003כ\u0004שיטת \u0003רבא,\u0004 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 תנא זה שרק בצמר ופשתים יש חיוב ציצית ולא בחמרים אחרים.","\u0003אמר רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא\u0004 את \u0003רב אשי: ל\u0004דעת ה\u0003תנא דבי\u0004 \u0005[מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל, מאי שנא\u0004 \u0005[מה שונה],\u0006 משום מה \u0003לענין טומאה דמרבי\u0004 \u0005[שהוא מרבה]\u0006 גם \u0003שאר בגדים\u0004 מחוץ לצמר ופשתים — \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 \u0003\"או בגד\"\u0004 שהוא לשון ריבוי ותוספת, \u0003הכא נמי לימא\u0004 \u0005[כאן,\u0006 בענין ציצית, \u0005גם כן יאמר]\u0006 \u0003לרבות שאר בגדים מ\u0004הכתוב \u0003\"\u0004כסותך \u0003אשר תכסה בה \"\u0004הכולל כל מיני בגדים. ענה לו רב אשי: הריבוי \u0003ההוא\u0004 נצרך למטרה אחרת — \u0003לאתויי\u0004 \u0005[להביא,\u0006 לרבות\u0005]\u0006 \u0003כסות סומא\u0004 (עיוור) \u0003הוא דאתא\u0004 \u0005[שבא]\u0006 מקרא זה שאף היא חייבת בציצית. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 נאמר בציצית: \"והיה לכם לציצית \u0003וראיתם אתו\u0004 וזכרתם את כל מצוות ה'\" (במדבר טו, לט), ומן האמור \"וראיתם\" למדנו שבא הכתוב למעט ולומר: \u0003פרט לכסות לילה\u0004 שאינה נראית, ולכך אינה חייבת בציצית. וממשיך התנא: \u0003אתה אומר\u0004 שבא הכתוב ללמד \u0003פרט לכסות לילה, או אינו אלא פרט לכסות סומא\u0004 שאף הוא אינו יכול לקיים \"וראיתם אותו\"? על כן בא הנימוק: \u0003כשהוא אומר\u0004 בספר דברים \u0003\"\u0004כסותך \u0003אשר תכסה בה \" הרי\u0004 אף \u0003כסות סומא אמור,\u0004 שהרי אף הוא מתכסה בכסות, \u0003הא\u0004 \u0005[הרי]\u0006 אם כן \u0003מה אני מקיים\u0004 את המיעוט \u0003\"וראיתם אתו\"\u0004 — הרי זה בא למעט ולומר \u0003פרט לכסות לילה.\u0004","ושואלים: מאחר שיש פסוק אחד הבא לרבות, ופסוק אחר הבא למעט, אם כן \u0003מה ראית לרבות סומא\u0004 בחיוב ציצית \u0003ולהוציא כסות לילה?\u0004 ומשיבים: \u0003מרבה אני\u0004 את \u0003כסות\u0004 ה\u0003סומא שישנה בראייה\u0004 לפחות \u0003אצל אחרים, ומוציא אני כסות לילה שאינה בראייה\u0004 אף \u0003אצל אחרים.\u0004","ושואלים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 שריבוי זה לא לענין סומא אלא \u0003לרבות שאר בגדים\u0004 שאינם צמר ופשתים, ולחייבם בציצית הוא בא, כדברי רבא? ומשיבים: \u0003מסתברא\u0004 \u0005[מסתבר]\u0006 לומר כי כאשר הוא \u0003קאי\u0004 \u0005[עומד]\u0006 ודן \u0003ב\u0004בגד \u0003צמר ופשתים\u0004 הרי הוא ודאי \u0003מרבה\u0004 בגד אחר שאף הוא \u0003צמר ופשתים,\u0004 ולכן יש ללמוד מכאן ריבוי לענין כסות סומא, העשויה מצמר ופשתים. ואולם \u0003כאשר הוא קאי\u0004 \u0005[עומד]\u0006 ודן \u0003ב\u0004ענין \u0003צמר ופשתים\u0004 שיהיה \u0003מרבה שאר בגדים\u0004 בו?! אלא ודאי אין הלימוד לענין זה.","וחוזרים שוב לשיטת ר' שמעון בן אלעזר שפסל אפילו מטליות קטנות מלשמש כסכך מטעם שהן מקבלות טומאה. \u0003אמר אביי: ר' שמעון בן אלעזר וסומכוס אמרו דבר אחד.\u0004 ומפרטים: \u0003ר' שמעון בן אלעזר הא דאמרן\u0004 \u0005[זה שאמרנו].\u0006 ו\u0003סומכוס\u0004 — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003סומכוס אומר\u0004 הסוכה ש\u0003סיככה ב\u0004סכך העשוי מחוט \u0003טווי — פסולה מפני ש\u0004החוט הטווי \u0003מטמאה בנגעים.\u0004","\u0003כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי]\u0006 היא דעת סומכוס זו — \u0003כי האי\u0004 \u0005[כמו\u0006 שיטת \u0005זה]\u0006 ה\u0003תנא, דתנן\u0004 \u0005[ששנוייה\u0006 משנה\u0005]:\u0006 \u0003שתי וערב מטמא בנגעים מיד\u0004 לאחר טוייתם, אלו \u0003דברי ר' מאיר. ר' יהודה אומר: השתי\u0004 מיטמא רק \u0003משישלה\u0004 מן היורה שבה מבשלים אותו, \u0003ו\u0004רק \u0003הערב\u0004 מיטמא \u0003מיד. ו\u0004אילו \u0003האונין של פשתן\u0004 (פשתן בלתי מעובד) מקבלים טומאה \u0003משיתלבנו\u0004 בתנור, ויהיו לפחות מוגמרים למחצה. וסומכוס תלמידו של ר' מאיר מחזיק בשיטתו.","\u0003כל\u0004 דבר \u0003היוצא מן\u0004 גוף \u0003העץ\u0004 עצמו \u0003אין מדליקין בו\u0004 בשבת (תוספות), לפי שאין בעירתו יפה, \u0003אלא פשתן.\u0004 והוסיפו אגב כך: \u0003וכל היוצא מן העץ אינו מטמא טומאת אהלים,\u0004 שאם היה מת מצוי בתוך בית או אהל העשויים מכל דבר הבא מן העץ, אף על פי שכל אשר בבית נטמא, האהל עצמו לא נטמא, \u0003אלא\u0004 רק אם היה עשוי מ\u0003פשתן,\u0004 שרק הוא מקבל בעצמו טומאה עם היותו אהל המת.","במשנה הוזכר הפשתן כאחד החומרים היוצאים מן העץ. ושואלים: \u0003מנלן\u0004 \u0005מנין לנו\u0006 ש\u0003פשתן איקרי\u0004 \u0005[נקרא]\u0006 \u0003\"עץ\"?\u0004 שהרי לפי צורתו החיצונית אינו דומה כלל לעץ! \u0003אמר מר זוטרא:\u0004 דבר זה ממה ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"והיא העלתם הגגה ותטמנם בפשתי העץ\"\u0004 (יהושע ב, ו).","שנינו במשנה כי כל \u0003היוצא מן העץ אינו מטמא\u0004 ב\u0003טומאת אהלים, אלא\u0004 ה\u0003פשתן\u0004 לבדו. ושואלים: \u0003מנלן\u0004 \u0005[מנין לנו]\u0006 דבר זה? \u0003אמר ר' אלעזר: גמר\u0004 \u0005[למד]\u0006 גזירה שווה מזהות המילים \u0003\"אהל\" \"אהל\"\u0004 שבענין טומאה"],["\u0003משכן.\u0004 שכן \u0003כתיב הכא\u0004 \u0005[נאמר כאן],\u0006 בדיני טומאה \u0003\"זאת התורה אדם כי ימות באהל\u0004 כל הבא אל האהל וכל אשר באהל יטמא שבעת ימים\u0003\"\u0004 (במדבר יט, יד), \u0003וכתיב התם\u0004 \u0005[ונאמר שם]\u0006 \u0003\"ויפרוש את האהל על המשכן\u0004 וישם את מכסה האהל עליו מלמעלה\u0003\"\u0004 (שמות מ, יט), \u0003מה להלן\u0004 במשכן היה האהל \u0003של פשתן,\u0004 והוא ה\u0003קרוי \"אהל\"\u0004 — \u0003אף כאן\u0004 בדיני טומאת מת רק אהל \u0003של פשתן קרוי \"אהל\".\u0004 ושואלים: \u0003אי\u0004 \u0005[אם\u0006 כן\u0005]\u0006 אמור גם כי \u0003מה להלן\u0004 חוטי הפשתן שבמשכן היו דווקא חוטים \u0003שזורין וחוטן\u0004 היה \u0003כפול ששה, אף כאן\u0004 בכל דין אהל המת יהיה צורך שיהיו \u0003שזורין, וחוטן\u0004 צריך להיות \u0003כפול ששה?\u0004 — \u0003תלמוד לומר:\u0004 במלה \u0003\"אהל\" \"אהל\"\u0004 החוזרת פעמים אחדות \u0003ריבה\u0004 הכתוב שאף אהל פשתן שאינו דומה בכל למשכן — אף הוא נקרא אהל. ושואלים: \u0003אי\u0004 \u0005[אם]\u0006 בחזרה של המלה \u0003\"אהל\" \"אהל\"\u0004 כמה פעמים \u0003ריבה\u0004 הכתוב, אם \u0003כן אפילו כל מילי נמי\u0004 \u0005[דבר גם כן]\u0006 ייחשב בין הדברים המקבלים טומאת אוהל! ומשיבים: אין להרחיב עד כדי כך את הריבוי, ש\u0003אם כן\u0004 ה\u0003גזירה\u0004 ה\u0003שוה\u0004 \"אהל\" \"אהל\" ללמד \u0003מהמשכן לאהל המת מאי אהני ליה\u0004 \u0005[מה הועילה לו]\u0006 אם הכל בכלל?! אלא ודאי שאין להרחיב, ועל ידי הגזירה השווה והריבוי נלמד שדין זה דווקא בפשתן.","ועוד שואלים: \u0003ואימא\u0004 \u0005[ו\u0006שמא \u0005אמור]:\u0006 \u0003מה להלן\u0004 במשכן בבסיס האהל היו \u0003קרשים, אף כאן\u0004 בדיני טומאה ייחשבו אף \u0003קרשים\u0004 כאהל! ומשיבים: \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"ועשית\u0004 את ה\u0003קרשים למשכן\u0004 עצי שטים עומדים\u0003\"\u0004 (שמות כו, טו), ומלשון הכתוב למדנו שה\u0003משכן\u0004 (היריעות בלבד) הוא ה\u0003קרוי משכן, ואין\u0004 ה\u0003קרשים\u0004 עצמם \u0003קרויין משכן,\u0004 אלא אך מכשירים למשכן. ודוחים: \u0003אלא מעתה\u0004 אם נדקדק בלשון הכתוב, הרי נאמר שם \u0003\"ועשית מכסה לאהל\u0004 עורות אילים מאדמים ומכסה עורות תחשים מלמעלה\u0003\"\u0004 (במדבר כו, יד), \u0003והאם הכי נמי\u0004 \u0005[כך גם כן]\u0006 תאמר ש\u0003מכסה לא איקרי\u0004 \u0005[אינו נקרא]\u0006 \u0003\"אהל\"?\u0004 ואם אתה אומר כן, \u0003אלא הא דבעי\u0004 \u0005[\u0006שאלה \u0005זו ששאל]\u0006 \u0003ר' אלעזר: עור בהמה טמאה\u0004 ששימש ככיסוי על המת \u0003מהו שיטמא\u0004 הוא עצמו \u0003באהל המת?\u0004 ואם תאמר שמכסה האהל אינו נחשב אהל, \u0003השתא\u0004 \u0005[עכשיו]\u0006 לפי זה \u0003עור בהמה טהורה\u0004 אשר כיסה את המשכן \u0003לא\u0004 \u0005[אינו]\u0006 \u0003מטמא,\u0004 אם כן \u0003עור בהמה טמאה\u0004 המשמש ככיסוי \u0003מיבעיא\u0004 \u0005[צריך לומר]\u0006 שאינו מטמא? ומשיבים: אין להשוות את הדברים כי \u0003שאני התם דהדר אהדריה קרא\u0004 \u0005[שונה שם שחזר והחזירו הכתוב]\u0006 לצרף את האהל והמכסה יחד, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ונשאו את יריעת המשכן ואת אהל מועד מכסהו ומכסה התחש אשר עליו\u0004 מלמעלה\u0003\"\u0004 (במדבר ד, כה), ופסוק זה \u0003מקיש\u0004 (משווה) כיסוי \u0003עליון לתחתון\u0004 — \u0003מה\u0004 הכיסוי ה\u0003תחתון קרוי \"אהל\", אף\u0004 הכיסוי \u0003העליון קרוי \"אהל\".\u0004","קודם הוזכרה שאלת ר' אלעזר, ועתה דנים בנושא זה \u0003גופא\u0004 \u0005[לגופו].\u0006 ש\u0003ר' אלעזר\u0004 שאל: \u0003עור בהמה טמאה מהו שיטמא\u0004 הוא עצמו ב\u0003טומאת אהלין?\u0004 ומבררים: \u0003מאי קמיבעיא ליה\u0004 \u0005[מה,\u0006 בעצם, \u0005נשאל לו]?\u0006 מה היא הבעיה היסודית שעליה מתבססת שאלה זו? \u0003אמר רב אדא בר אהבה: תחש שהיה בימי משה קמיבעיא ליה\u0004 \u0005[נשאל לו,\u0006 הסתפק בו\u0005]\u0006 ר' אלעזר האם \u0003טמא היה או טהור היה? אמר רב יוסף: מאי תיבעי ליה\u0004 \u0005[מה נשאל לו]\u0006 והלא בפירוש \u0003תנינא\u0004 \u0005[שנינו]:\u0006 \u0003לא הוכשרו למלאכת שמים אלא עור בהמה טהורה בלבד,\u0004 וודאי אם כן שתחש היה מין טהור!","על כך \u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003ר' אבא,\u0004 והרי שנינו ש\u0003ר' יהודה אומר: שני מכסאות היו\u0004 למשכן, \u0003אחד של עורות אילים מאדמים ואחד של עורות תחשים.\u0004 ואילו \u0003ר' נחמיה אומר: מכסה אחד\u0004 בלבד \u0003היה\u0004 למשכן, וחציו עורות אילים, וחציו עורות תחשים. והיה \u0003דומה כמין\u0004 החיה הנקראת \u0003תלא אילן.\u0004 ושואלים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003תלא אילן\u0004 יצור \u0003טמא הוא!\u0004 ומתקנים: \u0003הכי קאמר\u0004 \u0005[כך אמר,\u0006 כך היתה כוונתו\u0005]:\u0006 \u0003כמין תלא אילן הוא שיש בו גוונין הרבה, ו\u0004אולם \u0003לא תלא אילן\u0004 ממש, ש\u0003אילו התם\u0004 \u0005[שם]\u0006 תלא אילן \u0003הוא טמא, והכא\u0004 \u0005[וכאן]\u0006 כיסוי האהל היה \u0003טהור,\u0004 מחיות טהורות. \u0003אמר רב יוסף: אי הכי היינו דמתרגמינן\u0004 \u0005[אם\u0006 כך, \u0005זהו\u0006 הטעם \u0005שאנו מתרגמים]\u0006 \"תחש\" \u0003\"ססגונא\",\u0004 שהכוונה היא \u0003ששש\u0004 (שמח) \u0003בגוונין הרבה.\u0004","\u0003רבא אמר\u0004 כי ההוכחה ש\u0003עור בהמה טמאה\u0004 שהוא \u0003מטמא באהל המת\u0004 באה \u0003מהכא\u0004 \u0005[מכאן],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 בדיני טומאת הנגעים נאמר כי הנגע יכול להיות \"או בשתי או בערב לפשתים ולצמר או בעור או בכל מלאכת עור\" (ויקרא יג, מח). ולמעשה היה יכול להיות כתוב לשון \u0003\"\u0004או \u0003עור\",\u0004 ונאמר \"או בעור\", ואמרו חכמים: במילים \u0003\"או בעור\" ריבה\u0004 הכתוב \u0003עור בהמה טמאה\u0004 שאף הוא מיטמא. \u0003ו\u0004אילו עור \u0003שלקה ביד כהן,\u0004 שלפני שהראהו בעליו לכהן לא היה בו נגע, אבל נעשה בו נגע בידיו של הכהן, \u0003או\u0004 ש\u0003קצץ\u0004 מכל אחד מן המינים הללו \u0003ועשה\u0004 מטלית \u0003אחת מהן, מנין\u0004 שהוא מקבל טומאה? — \u0003תלמוד לומר\u0004 מן הריבוי הרחב יותר: \u0003\"או בכל מלאכת עור \".\u0004 ומעירים: \u0003ואיכא למיפרך\u0004 \u0005[ויש\u0006 מקום \u0005לפרוך,\u0006 לשבור\u0005]\u0006 את ההשוואה, ומתוך כך גם לא נוכל ללמוד טומאת מת מדיני נגעים, כי \u0003מה ל\u0004השוואה מ\u0003נגעים\u0004 שהחמיר בהם הכתוב \u0003שכן\u0004 גם \u0003שתי וערב\u0004 שלא נארגו \u0003טמא בהן\u0004 הנגע.","\u0003אלא\u0004 יש לומר כי \u0003גמר\u0004 \u0005[למד]\u0006 \u0003מ\u0004דיני טומאת \u0003שרצים,\u0004 שנאמר בהם: \"וכל אשר יפול עליו מהם במותם יטמא מכל כלי עץ או בגד או עור או שק כל כלי אשר יעשה מלאכה בהם\" (ויקרא יא, לב). \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 מן האמור סתם \u0003\"עור \"אין לי\u0004 ללמוד שיהיה מיטמא במגע שרץ \u0003אלא עור בהמה טהורה,\u0004 ואולם \u0003עור בהמה טמאה מנין\u0004 שאף הוא מיטמא? \u0003תלמוד לומר\u0004 מן הריבוי \u0003\"או עור \".\u0004 ומתוך שבטומאת שרצים דין עור הטהור והטמא זהה נלמד מזה אף לדיני אהל המת. ושוב אומרים: \u0003ואיכא למיפרך\u0004 \u0005[ויש\u0006 מקום \u0005לפרוך,\u0006 לשבור\u0005]\u0006 את ההשוואה ולומר כי \u0003מה לשרצים\u0004 דינם כן, \u0003שכן\u0004 הם \u0003מטמאין\u0004 אפילו \u0003ב\u0004שיעור קטן \u0003כעדשה,\u0004 מה שאין כן המת ששיעור טומאתו גדול יותר בכזית. על כן אומרים: אם כן, \u0003נגעים יוכיחו\u0004 שטומאתם ביותר מכעדשה ואף על פי כן עור בהמה טמאה טמא בהם. \u0003וחזר הדין,\u0004 כלומר, הדין (ההוכחה) פונה, סובב, ממוכיח אחד אל השני, והסיכום — שאמנם \u0003לא ראי זה כראי זה ולא ראי זה כראי זה,\u0004 שאין דבר אחד נראה ונידון כדבר אחר לפי שיש בכל אחד מהם חומרות מיוחדות, ואולם \u0003הצד השוה שבהן\u0004 — \u0003שעור\u0004 בכלל \u0003טמא בהן, ועשה\u0004 הכתוב דין \u0003עור בהמה טמאה כעור בהמה טהורה\u0004 להיטמא. \u0003אף אני אביא\u0004 את ההלכה הנוספת של \u0003אהל המת שעור טמא בו, ונעשה\u0004 אף \u0003בו עור בהמה טמאה כעור בהמה טהורה.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא מברניש לרב אשי:\u0004 עדיין \u0003איכא למיפרך\u0004 \u0005[יש לפרוך,\u0006 לשבור\u0005]\u0006 דברים אלו ולומר: \u0003מה להצד השוה שבהן\u0004 (בנגעים ובשרצים) \u0003שכן טמאין\u0004 הם שניהם \u0003בפחות מכזית, תאמר במת שאינו מטמא אלא בכזית\u0004 לפחות.","על כן נמצא שלמרות ההבדלים חמורות שתי הלכות אלה מדיני טומאת המת ואין ללמוד מהן. \u0003אלא אמר רבא מברניש,\u0004 יש ללמוד זאת כך:"],["\u0003אתיא\u0004 \u0005[בא,\u0006 נלמד\u0005]\u0006 הדבר \u0003בקל וחומר מנוצה\u0004 (שיער) \u0003של עזים,\u0004 שאף \u0003שאין\u0004 הוא \u0003מטמא בנגעים,\u0004 מכל מקום הוא \u0003מטמא באהל המת,\u0004 הרי \u0003עור בהמה טמאה שמטמאה בנגעים אינו דין\u0004 (קל וחומר) \u0003שמטמאה באהל המת.\u0004","מאחר שהיתה המסקנה כי אף עור בעל חי טמא מיטמא באהל המת, הרי אין חובה להניח כי מכסה המשכן היה מעור בהמה טהורה דווקא. ואם כן, \u0003הא דתני\u0004 \u0005[זה ששנה]\u0006 \u0003רב יוסף\u0004 ש\u0003לא הוכשרו במלאכת שמים אלא עור בהמה טהורה בלבד\u0004 — \u0003למאי הלכתא\u0004 \u0005[למה,\u0006 לאיזו \u0005הלכה]\u0006 הוא מוסב? שהרי כאמור אינו שייך לדיני המשכן. ומשיבים: הלכה זו \u0003ל\u0004ענין \u0003תפילין\u0004 נאמרה שאין לעשותם אלא מעור בהמה טהורה. ושואלים: לשם מה דברי רב יוסף, והלא \u0003תפילין בהדיא כתיב בהו\u0004 \u0005[במפורש נאמר בהם]\u0006 \u0003\"\u0004והיה לך לאות על ידך ולזכרון בין עיניך למען \u0003תהיה תורת ה' בפיך\"\u0004 (שמות יג, ט), ומכאן למדו חכמים כי התפילין צריכות להיות עשויות \u0003מן המותר בפיך\u0004 גם באכילה!","\u0003אלא\u0004 אומרים כי הלכה זו של רב יוסף \u0003ל\u0004ענין \u0003עורן\u0004 של בתי התפילין בלבד נאמרה, שהוא הצריך לדעתו להיות של בהמה טהורה, ואולם לא לענין הקלף עליו כתובות פרשיות התפילין. ושואלים: \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003אביי:\u0004 חובת עשיית ה\u0003שי\"ן של תפילין\u0004 המצויה ובולטת בתפילין של ראש הריהי \u0003הלכה למשה מסיני,\u0004 ומאחר שכתוב דבר גם על בית התפילין הרי דינו לכאורה כדין הקלף ואיסור עשייתו מעור בהמה טמאה הוא מהתורה!","\u0003 אלא \u0004מסבירים כי הלכה זו של רב יוסף מלמדת שיש \u0003לכורכן\u0004 את פרשיות התפילין \u0003בשערן\u0004 (בשיער של בהמה טהורה), \u0003ו\u0004כן \u0003לתופרן\u0004 את התפילין \u0003בגידן\u0004 (בחוטים העשויים מגידי בהמה טהורה). ושואלים: \u0003הא נמי\u0004 \u0005[\u0006הלכות \u0005אלו גם כן]\u0006 מקורן ב\u0003הלכה למשה מסיני הוא, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003תפילין\u0004 שיהיו \u0003מרובעות\u0004 — \u0003הלכה\u0004 היא \u0003למשה מסיני,\u0004 וכן שהן \u0003נכרכות בשערן ונתפרות בגידן!\u0004","\u0003אלא\u0004 אומרים שדברי רב יוסף באו ללמד \u0003ל\u0004דין \u0003רצועות\u0004 התפילין. ושואלים: \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' יצחק:\u0004 ש\u0003רצועות\u0004 התפילין חייבות שתהיינה \u0003שחורות\u0004 הרי זו \u0003הלכה למשה מסיני?\u0004 ומשיבים: \u0003נהי דגמירי\u0004 \u0005[אם אמנם שלמדנו]\u0006 בהלכה מקובלת זו שהרצועות צריכות להיות \u0003שחורות,\u0004 ואולם \u0003שתהיינה מבהמות טהורות מי גמירי\u0004 \u0005[האם למדנו]?\u0006 אלא ודאי לכך נתכווין רב יוסף במה שאמר שכל מלאכת שמים דינה שתהא מעור בהמה טהורה.","ושואלים: \u0003מאי הוי עלה\u0004 \u0005[מה היה עליה],\u0006 על השאלה בדבר ה\u0003תחש שהיה בימי משה? אמר ר' אלעא אמר ר' שמעון בן לקיש, אומר היה ר' מאיר: תחש שהיה בימי משה בריה בפני עצמה היה, ולא הכריעו\u0004 (החליטו) \u0003בה חכמים אם מין חיה הוא אם מין בהמה הוא, וקרן אחת היתה לו במצחו, ו\u0004תחש זה \u0003לפי שעה\u0004 (רק אז) נזדמן לו למשה בשעת עשיית המשכן, \u0003ועשה ממנו\u0004 כיסוי ל\u0003משכן ו\u0004מאז \u0003נגנז\u0004 התחש, ואין מוצאים עוד מין חיה זה.","ומעירים: \u0003מדקאמר\u0004 \u0005[ממה שנאמר]\u0006 ש\u0003קרן אחת היתה לו במצחו שמע מינה\u0004 \u0005[למד ממנה]\u0006 שהתחש \u0003טהור היה,\u0004 שבדומה לזה \u0003אמר רב יהודה:\u0004 ה\u0003שור שהקריב אדם הראשון\u0004 כקרבן תודה על חייו \u0003קרן אחת היתה לו במצחו, שנאמר: \"ותיטב לה' משור פר מקרן מפריס\"\u0004 (תהלים סט, לב). ו\"מקרין\" פירושו — בעל קרן. ושואלים: והלא \u0003\"מקרין\" תרתי\u0004 \u0005[שתים]\u0006 \u0003משמע,\u0004 שהוא בעל קרניים, והרי שתים! ומשיבים: \u0003אמר רב נחמן בר יצחק \"מקרן\"\u0004 חסר י' \u0003כתיב\u0004 \u0005[נאמר],\u0006 להדגיש שהיתה לו רק קרן אחת. ושואלים: אם כן \u0003וליפשוט מיניה\u0004 \u0005[ושיפתור ממנה]\u0006 מאותה ברייתא שכשם שלמדנו משור של אדם הראשון שבעל חיים שיש לו קרן אחת במצחו טהור הוא, מדוע לא נלמד שגם \u0003מין בהמה הוא?\u0004 ומשיבים: \u0003כיון דאיכא\u0004 \u0005[שיש]\u0006 \u0003\"קרש \"\u0004ש\u0003מין חיה הוא ולית ליה\u0004 \u0005[ואין לו]\u0006 \u0003אלא חדא קרן\u0004 \u0005[קרן אחת]\u0006 \u0003איכא למימר\u0004 \u0005[יש\u0006 אפשרות \u0005לומר]\u0006 ש\u0003מין חיה הוא\u0004 גם התחש. ושאלה זו לא נפתרה איפוא.","\u0003פתילת הבגד, ש\u0004היא מטלית בד שעשה ממנה פתילה לנר, ו\u0003קיפלה\u0004 בגודל ובצורה המתאימים לפתילה, \u0003ו\u0004אולם עדיין \u0003לא הבהבה\u0004 (חרך אותה קצת באש, כדי לסייע בהדלקתה), \u0003ר' אליעזר אומר:\u0004 פתילה זו \u0003טמאה היא,\u0004 שלענין דיני טומאה עדיין מקבלת היא טומאה כשאר בגדים, \u0003ואין מדליקין בה\u0004 בשבת. \u0003ר' עקיבא אומר: טהורה היא ו\u0004אף \u0003מדליקין בה\u0004 בשבת.","שואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003לענין טומאה בהא פליגי\u0004 \u0005[בזה\u0006 הם \u0005חלוקים],\u0006 וברורים טעמי המחלוקת, ש\u0003ר' אליעזר סבר\u0004 \u0005[סבור]\u0006 ש\u0003קיפול\u0004 בלבד \u0003אינו מועיל\u0004 להוציא את הבגד ממהותו הקודמת, \u0003ובמילתיה קמייתא קיימא\u0004 \u0005[ובדברו,\u0006 בתכונתו \u0005הראשונה נשאר],\u0006 ולכך הוא עדיין מקבל טומאה כבגד. \u0003ו\u0004אילו \u0003ר' עקיבא סבר\u0004 \u0005[סבור]\u0006 ש\u0003קיפול מועיל, ובטולי בטיל\u0004 \u0005[ובטל]\u0006 מכדי להיות בגד ולכן אינו מקבל עוד טומאה כבגד.","\u0003אלא לענין הדלקה בשבת במאי פליגי\u0004 \u0005[במה\u0006 הם \u0005חלוקים]?\u0006 \u0003אמר ר' אלעזר אמר ר' אושעיא, וכן אמר רב אדא בר אהבה: הכא\u0004 \u0005[כאן]\u0006 \u0003ב\u0004מטלית שיש בה \u0003שלש על שלש\u0004 אצבעות \u0003מצומצמות\u0004 (בדיוק) \u0003עסקינן\u0004 \u0005[עוסקים אנו],\u0006 \u0003וביום טוב שחל להיות\u0004 ב\u0003ערב שבת עסקינן\u0004 \u0005[עוסקים אנו].\u0006 ועלינו עוד להניח כי \u0003דכולי עלמא אית להו\u0004 \u0005[לדעת הכל יש להם,\u0006 מקבלים\u0005]\u0006 את שיטת \u0003ר' יהודה\u0004 ש\u0003אמר\u0004 כי ביום טוב \u0003מסיקין בכלים\u0004 שלמים שהם מותרים לטלטול ואין בהם דין מוקצה, \u0003ו\u0004אולם \u0003אין מסיקין בשברי כלים,\u0004 כלומר, בכלים שנשברו ביום טוב, שמאחר והיו קודם שלמים ונשברו ביום טוב עצמו, הרי הם אסורים באיסור \"נולד\", ואסורים בטלטול. וכן יש לומר \u0003דכולי עלמא אית להו\u0004 \u0005[לדעת הכל יש להם,\u0006 מקבלים\u0005]\u0006 את שיטת \u0003עולא,\u0004 ש\u0003אמר עולא: המדליק\u0004 את הנר \u0003צריך שידליק ברוב\u0004 חלק הפתילה \u0003היוצא\u0004 מן הנר. ועל סמך הנחות אלה נבין את המחלוקת במשנה כך: \u0003ר' אליעזר סבר\u0004 \u0005[סבור]\u0006 כי \u0003קיפול\u0004 בלבד \u0003אינו מועיל\u0004 לבטל את הפתילה מלהיות כלי, \u0003וכיון דאדליק ביה פורתא\u0004 \u0005[כשהוא מדליק בה מעט]\u0006 \u0003הויא ליה \u0004\u0005[הרי היא]\u0006 נעשית בכך \u0003שבר כלי,\u0004 כי משנדלקה הפתילה חלקה נשרף ונעשית פחות משלוש על שלוש אצבעות, ובפחות משלוש על שלוש אין הבגד חשוב עוד למאומה, \u0003וכי קא מדליק בשבר כלי קמדליק\u0004, \u0005[ונמצא שהוא מדליק בשבר כלי]\u0006 וכאמור אסור להדליק בשברי כלים. \u0003ו\u0004אילו \u0003ר' עקיבא סבר\u0004 \u0005[סבור]\u0006 כי \u0003קיפול מועיל, ו\u0004מיד עם קיפול הבגד שוב \u0003אין תורת כלי עליו,\u0004 אינו נחשב ככלי, \u0003וכי קמדליק\u0004 \u0005[וכאשר הוא מדליק]\u0006 — \u0003בעץ בעלמא קמדליק\u0004 \u0005[בלבד הוא מדליק].\u0006","\u0003אמר רב יוסף, היינו דתנינא\u0004 \u0005[זהו ששניתי]:\u0006 \u0003\"שלש על שלש מצומצמות\" ולא ידענא למאי הלכתא\u0004 \u0005[ידעתי לאיזו הלכה].\u0006 שקיבל רב יוסף מרבותיו שמדובר בשלוש על שלוש בדיוק, ולא ידע לאיזה ענין חשוב שיהיה שלוש על שלוש מצומצמות, ולא יותר.","ובדרך אגב אומרים: \u0003ומדקא\u0004 \u0005[וממה]\u0006 ש\u0003מתרץ רב אדא בר אהבה\u0004 משנה זו \u0003אליבא\u0004 \u0005[לשיטת],\u0006 \u0003ר' יהודה, שמע מינה\u0004 \u0005[למד ממנה]\u0006 כי \u0003כר' יהודה סבירא ליה\u0004 \u0005[סבור הוא],\u0006 ואולם, \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר רב אדא בר אהבה הכי\u0004 \u0005[כך]?\u0006 \u0003והאמר רב אדא בר אהבה\u0004 עצמו:"],["\u0003גוי שחקק\u0004 ביום טוב חלל בנפח של \u0003קב\u0004 בתוך \u0003בקעת\u0004 (חתיכת) עץ ועשה אותה על ידי כך כלי חדש — \u0003ישראל מסיקה\u0004 מלכתחילה \u0003ביום טוב. ואמאי\u0004 \u0005[ומדוע]?\u0006 והרי כלי חדש זה שנעשה בעץ \u0003נולד הוא,\u0004 ונולד ביום טוב הריהו מוקצה. ומאחר שהתירו רב אדא בר אהבה, מכאן שהוא סבור שאין דין מוקצה ביום טוב, ושלא כר' יהודה! ומשיבים: \u0003לדבריהם\u0004 של \u0003ר' אליעזר ור' עקיבא קאמר ליה\u0004 \u0005[אמר לו]\u0006 דברים אלה, \u0003וליה לא סבירא ליה\u0004 \u0005[\u0006\u0005והוא\u0006 עצמו \u0005אינו סבור כן],\u0006 שאף שהסביר את המשנה לשיטת ר' יהודה, הוא עצמו סבור כי אין הלכה כדבריו.","\u0003רבא אמר, היינו טעמא\u0004 \u0005[זהו הטעם]\u0006 של \u0003ר' אליעזר\u0004 בענין הדלקת הפתילה: \u0003לפי\u0004 שהוא סבור \u0003שאין מדליקין\u0004 בשבת \u0003בפתילה שאינה מחורכת\u0004 (חרוכה קצת ומוכנה לבעירה) \u0003ולא בסמרטוטין שאינן מחורכין\u0004 מבעוד יום. שאם מהבהב את הפתילה לפני הדלקתה, תבער יפה, ופתילה שאינה מחורכת אינה בוערת יפה ואינה לכבוד השבת. ושואלים: אם כן, \u0003הא דתני\u0004 \u0005[זה ששנה]\u0006 \u0003רב יוסף \"שלש על שלש מצומצמות\" למאי הלכתא?\u0004 \u0005[למה,\u0006 לאיזו \u0005הלכה]\u0006 נאמר הדבר? שהרי לענייננו אין הבדל מה מידתה המדוייקת של פתילת הבגד! ומשיבים: דבר זה נאמר \u0003לענין\u0004 אחר, בדיני \u0003טומאה. דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]\u0006 במסכת כלים: \u0003שלש על שלש\u0004 אצבעות \u0003שאמרו\u0004 כשיעור מינימלי לטומאת הבגד — הכוונה היא \u0003חוץ מן המלל\u0004 (החוטים היוצאים בשולי הבגד, שחוזרים ותופרים אותם כאימרה), אלו \u0003דברי ר' שמעון. ו\u0004אילו \u0003חכמים אומרים: שלש על שלש מכוונות\u0004 אפילו עם המלל. והן שלוש על שלוש מצומצמות שזכר רב יוסף.","ולענין שהוזכר, \u0003אמר רב יהודה אמר רב,\u0004 מחלוקת תנאים היא בענין זה: \u0003מסיקין\u0004 ביום טוב \u0003בכלים ואין מסיקין בשברי כלים,\u0004 אלו \u0003דברי ר' יהודה. ו\u0004אילו \u0003ר' שמעון מתיר\u0004 להסיק אף בשברי כלים. והלכה נוספת: \u0003מסיקין\u0004 ביום טוב \u0003בתמרין\u0004 שלמים, ואם \u0003אכלן אין מסיקין בגרעיניהן,\u0004 שהם מוקצה, אלו \u0003דברי ר' יהודה. ור' שמעון מתיר.\u0004 ועוד: \u0003מסיקין\u0004 ביום טוב \u0003באגוזים\u0004 שלמים. ואם \u0003אכלן אין מסיקין בקליפותיהן,\u0004 אלו \u0003דברי ר' יהודה. ור' שמעון מתיר.\u0004","ומעירים: \u0003וצריכא\u0004 \u0005[וצריך]\u0006 להזכיר שלוש דוגמאות אלה, שכן בכל אחת מהן יש חידוש. \u0003דאי אשמעינן קמייתא\u0004 \u0005[שאילו היה משמיע לנו\u0006 את \u0005הראשונה]\u0006 בלבד, היינו אומרים כי דווקא \u0003ב\u0004הלכה \u0003ההיא\u0004 בענין הסקה בשברי כלים \u0003קאמר\u0004 \u0005[אומר]\u0006 כך \u0003ר' יהודה, משום דמעיקרא\u0004 \u0005[שמתחילה]\u0006 היה זה \u0003כלי והשתא\u0004 \u0005[ועכשיו]\u0006 הוא \u0003שבר כלי, והוה ליה\u0004 \u0005[והריהו]\u0006 כ\u0003נולד, ואסור, אבל תמרים דמעיקרא\u0004 \u0005[שמתחילה]\u0006 היו בהם \u0003גרעינין והשתא\u0004 \u0005[ו\u0006גם \u0005עכשיו]\u0006 יש בהם \u0003גרעינין,\u0004 ואם כן \u0003אימא שפיר דמי\u0004 \u0005[הייתי אומר\u0006 כי \u0005יפה\u0006 הדבר, \u0005מותר\u0006\u0005].\u0006 \u0003ו\u0004כן \u0003אי אשמעינן\u0004 \u0005[אם היה משמיע לנו]\u0006 ב\u0003גרעינין\u0004 של תמרים \u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 שאסורים הם משום \u0003דמעיקרא מכסיין\u0004 \u0005[שמתחילה היו מכוסים]\u0006 בפרי \u0003והשתא מיגליין\u0004 \u0005[ועכשיו\u0006 הם \u0005מגולים],\u0006 והרי זה כנולד ויש מקום לאסור. \u0003אבל קליפי אגוזין, דמעיקרא מיגלו והשתא מיגלו\u0004 \u0005[שמתחילה הן מגולות ו\u0006אף \u0005עכשיו מגולות הן],\u0006 שהם כמו שהיו, ואם כן \u0003אימא שפיר דמי\u0004 \u0005[הייתי אומר\u0006 כי \u0005יפה\u0006 הדבר, \u0005מותר\u0006\u0005].\u0006 על כן \u0003צריכא\u0004 \u0005[צריך]\u0006 היה להשמיענו כל אלה.","ומוסיפים: \u0003והא\u0004 \u0005[ו\u0006הלכה \u0005זו]\u0006 של \u0003רב לאו\u0004 \u0005[לא]\u0006 \u0003בפירוש איתמר\u0004 \u0005[נאמרה],\u0006 \u0003אלא מכללא איתמר\u0004 \u0005[מכלל\u0006 הדברים \u0005נאמרה],\u0006 שדברים אלה הסיקו ממה שנהג רב, ולא מדבריו המפורשים. שמעשה היה ש\u0003רב אכל תמרי\u0004 \u0005[תמרים]\u0006 ביום \u0003חול ושדא קשייתא לבוכיא\u0004 \u0005[וזרק\u0006 את \u0005הגרעינים לתנור].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' חייא: בר פחתי\u0004 \u0005[בן אצילים],\u0006 \u0003כנגדו ביום טוב אסור.\u0004 כלומר, דבר דומה לזה, לזרוק גרעיני תמרים ולהסיק בהם תנור — אסור ביום טוב. ושואלים: \u0003קיבלה\u0004 רב להלכה זו \u0003מיניה\u0004 \u0005[ממנו],\u0006 \u0003או לא קיבלה מיניה\u0004 \u0005[ממנו]?\u0006","\u0003תא שמע: דכי אתא\u0004 \u0005[שכאשר בא]\u0006 \u0003רב\u0004 מארץ ישראל \u0003לבבל אכל תמרי\u0004 \u0005[תמרים]\u0006 ביום טוב \u0003ושדא קשייתא לחיותא\u0004 \u0005[וזרק את הגרעינים לבהמות]\u0006 לאכילה. \u0003מאי לאו בפרסייאתא\u0004 \u0005[האם לא\u0006 היה זה \u0005ב\u0006תמרים \u0005פרסיים]\u0006 שהם תמרים מעולים, והבשר, גוף הפרי, יורד כולו מן הגרעינים והגרעין נשאר חשוף לגמרי, והריהו לכאורה מוקצה גמור, שהרי אין בו שימוש לאדם כלל. ומאחר שזרקו רב לבהמות הרי זה סימן כי \u0003לא קיבלה\u0004 להלכה זו ממנו, ואינו סבור שיש בכך איסור. ומשיבים: \u0003לא,\u0004 מדובר כאן \u0003בארמיאתא\u0004 \u0005[ב\u0006תמרים \u0005ארמיים]\u0006 שאינם נקלפים יפה, ומשהו מבשר התמר נשאר על הגרעין. וגרעינים אלה \u0003הואיל וחזי\u0004 \u0005[וראויים]\u0006 הם \u0003אגב אימייהו\u0004 \u0005[אמם,\u0006 הפרי עצמו\u0005],\u0006 מותר לטלטל אף אותם.","\u0003אמר ליה רב שמואל בר בר חנה לרב יוסף: ל\u0004דעת \u0003ר' יהודה\u0004 ש\u0003אמר\u0004 ש\u0003מסיקין בכלים\u0004 שלמים \u0003ואין מסיקין בשברי כלים,\u0004 כיצד אפשר להדליק אף בכלים שלמים? והלא \u0003כיון דאדליק בהו פורתא הוה ליה\u0004 \u0005[שהדליק בהם משהו, הרי הם נעשים]\u0006 \u0003שברי כלים, וכי קא\u0004 \u0005[וכאשר הוא]\u0006 \u0003מהפך\u0004 בעצים, להחיש את בעירתם — \u0003באיסורא קא\u0004 \u0005[באיסור הוא]\u0006 \u0003מהפך,\u0004 שהרי אסור להדליק בשברי כלים. ומשיבים: \u0003דעבד\u0004 \u0005[שעשה]\u0006 \u0003כ\u0004דברי \u0003רב מתנה.\u0004 ש\u0003אמר רב מתנה אמר רב: עצים שנשרו מן הדקל לתנור ביום טוב,\u0004 וענפים אלה כיון שבכניסת החג היו מחוברים לעץ הריהם מוקצים ואסור לו להפך בהם, מכל מקום יש לו תקנה בכך שיהא \u0003מרבה\u0004 (מוסיף) עליהם \u0003עצים\u0004 שהיו \u0003מוכנין\u0004 להסקה מערב יום טוב, עד שיהיו רוב העצים בתנור שאינם מוקצה, \u0003ומסיקן,\u0004 שמאחר והרוב היתר אינו חושש למיעוט. וכן עושה בכלים, שמרבה עליהם עצים שאין בהם דין מוקצה.","\u0003רב המנונא אמר\u0004 הסבר אחר למחלוקת במשנה. ולדעתו \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003ב\u0004בגד ה\u0003פחות משלשה על שלשה\u0004 טפחים \u0003עסקינן\u0004 \u0005[עוסקים אנו],\u0006 \u0003ומקולי מטלניות שנו כאן,\u0004 שעיקרן של הדברים קשור בבעיית הדינים שקבעו חכמים במטליות קטנות, שאינן חשובות (\"קלות\") בעיני אדם.","\u0003ואזדא\u0004 \u0005[והלך]\u0006 \u0003ר' אליעזר לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005],\u0006 \u0003ור' עקיבא לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005].\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]\u0006 במסכת כלים: אריג \u0003פחות משלשה על שלשה\u0004 טפחים \u0003שהתקינו לפקק בו את המרחץ\u0004 או כדי להחזיק ו\u0003לנער בו את הקדירה\u0004 החמה, או \u0003לקנח בו את הרחיים, בין\u0004 שהיה בד זה \u0003מן המוכן\u0004 לצורך זה, \u0003ובין שאין\u0004 הוא \u0003מן המוכן\u0004 — הריהו \u0003טמא,\u0004 כלומר, ראוי לקבל טומאה, אלו \u0003דברי ר' אליעזר. ור' יהושע אומר: בין\u0004 שהיה \u0003מן המוכן ובין\u0004 שהיה \u0003שלא מן המוכן\u0004 — הריהו \u0003טהור\u0004 כלומר, אינו ראוי לקבל טומאה. ו\u0003ר' עקיבא\u0004 מחלק בדברים ו\u0003אומר:\u0004 לדעתו \u0003מן המוכן\u0004 — \u0003טמא, ושלא מן המוכן\u0004 — \u0003טהור.\u0004 ועתה השאלה למעשה הריהי מה משמעות \"מוכן\" בהקשר זה. \u0003ואמר עולא, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רבה בר בר חנה אמר ר' יוחנן: הכל מודים\u0004 שמטלית בגודל זה, אם \u0003זרקו באשפה\u0004 — ל\u0003דברי הכל טהור,\u0004 שבכך הראה שהוא מבטל מטלית זו מתורת בגד, ואינו מחשיבה עוד."],["ואם \u0003הניחו בקופסא\u0004 — ל\u0003דברי הכל טמא,\u0004 לפי שבכך הוא מראה שהוא מחשיב את המטלית ושומרה לשימוש. \u0003ולא נחלקו אלא\u0004 באופן \u0003שתלאו\u0004 לבגד זה \u0003במגוד\u0004 (יתד שבקיר), \u0003או שהניחו לאחורי הדלת.\u0004 ש\u0003ר' אליעזר סבר\u0004 \u0005[סבור]\u0006 ש\u0003מ\u0004תוך זה ש\u0003לא זרקו באשפה\u0004 ודאי \u0003דעתיה עילויה\u0004 \u0005[דעתו עליו]\u0006 ומתכוון להשתמש בו. \u0003ומאי קרי ליה\u0004 \u0005[ומה,\u0006 מדוע, \u0005קרא לו]\u0006 \u0003\"שלא מן המוכן\"\u0004 — מאחר ש\u0003לגבי\u0004 זה המונח \u0003בקופסא\u0004 אין הוא נחשב כמוכן לשימוש. \u0003ו\u0004אילו \u0003ר' יהושע סבר\u0004 \u0005[סבור]\u0006 ש\u0003מ\u0004תוך ש\u0003לא הניחו בקופסא\u0004 ודאי \u0003בטולי בטליה\u0004 \u0005[בטלו],\u0006 \u0003ומאי קרי ליה\u0004 \u0005[ומה,\u0006 מדוע, \u0005קרא לו],\u0006 \u0003\"מוכן\"?\u0004 — משום ש\u0003לגבי\u0004 זה המונח ב\u0003אשפה\u0004 בגד כזה ל\u0003מוכן\u0004 לשימוש \u0003הוא,\u0004 אבל לאמיתו של דבר כבר בטל מחשיבותו. \u0003ו\u0004אילו \u0003ר' עקיבא בתלאו במגוד סבר כר' אליעזר,\u0004 שעדיין לא ביטלוהו משימוש, ועל כן היא מיטמא. ו\u0003בהניחו מאחורי הדלת סבר לה\u0004 \u0005[סבור הוא]\u0006 \u0003כר' יהושע\u0004 שביטלהו מחשיבותו כבגד ושוב אינו מיטמא.","ומעירים: \u0003והדר ביה\u0004 \u0005[וחזר בו]\u0006 \u0003ר' עקיבא לגביה\u0004 \u0005[אצל]\u0006 דעת \u0003ר' יהושע\u0004 וסבר כמותו. ו\u0003ממאי\u0004 \u0005[ממה]\u0006 יודעים אנו זאת? \u0003אמר רבא: מדקתני\u0004 \u0005[ממה ששנינו]\u0006 במשנתנו בלשון \u0003\"פתילת הבגד\". מאי איריא\u0004 \u0005[מה שייך,\u0006 מדוע דווקא\u0005]\u0006 שנה \u0003\"פתילת הבגד\"? ליתני\u0004 \u0005[שישנה]\u0006 בלשון \u0003\"פתילה של בגד\",\u0004 או פתילה העשויה מבגד, ומשום מה אמר \"פתילת הבגד\" — משום \u0003שעדיין בגד הוא.\u0004 ובכל זאת, סבור ר' עקיבא שטהורה היא, כדעת ר' יהושע.","יסוד המחלוקת במשנה זו הוא בהגדרת הבערה וכיבוי בשבת, ואם יש לאסור גם כאשר נגרמת פעולת ההבערה או הכיבוי שלא במישרין. שאמרו חכמים: \u0003לא יקוב אדם\u0004 חור ב\u0003שפופרת של ביצה וימלאנה שמן ויתננה על פי הנר בשביל שתהא\u0004 הביצה \u0003מנטפת\u0004 שמן נוסף אל תוך הנר ומאריכה על ידי כך את זמן בעירתו. \u0003ואפילו\u0004 לא היתה זו ביצה ממש אלא \u0003היא\u0004 כלי \u0003של חרס. ור' יהודה מתיר. אבל אם חברה היוצר\u0004 (עושה כלי החרס) לביצה זו \u0003מתחילה\u0004 לנר — \u0003מותר\u0004 למלאותה שמן \u0003מפני שהוא\u0004 נחשב כ\u0003כלי אחד,\u0004 גדול יותר. וגזרו ש\u0003לא ימלא אדם קערה של שמן ויתננה בצד הנר ויתן\u0004 את \u0003ראש הפתילה\u0004 שאיננו בוער \u0003בתוכה,\u0004 בתוך הקערה \u0003בשביל שתהא שואבת\u0004 שמן נוסף מן הקערה ובכך יתארך זמן הבעירה. \u0003ור' יהודה מתיר.\u0004","על מה שהביאה המשנה שלושה מקרים אף שלכולם טעם זהה מעירים: \u0003וצריכא\u0004 \u0005[וצריך]\u0006 היה להביא את כל המקרים הנזכרים, שכן אי אפשר ללמוד דבר אחד מחבירו. \u0003דאי אשמעינן\u0004 \u0005[שאילו היה משמיע לנו]\u0006 רק את האיסור ב\u0003שפופרת של ביצה\u0004 — הייתי יכול לומר כי דווקא \u0003בהא קאמרי רבנן\u0004 \u0005[בזה אמרו חכמים]\u0006 שאסור לעשות כך, שמ \u0003כיון דלא מאיסא\u0004 \u0005[ש\u0006הביצה \u0005אינה מאוסה]\u0006 מלכלוך יש לחשוש שמא \u0003אתי לאסתפוקי מינה\u0004 \u0005[יבוא להסתפק,\u0006 לאכול, \u0005ממנה],\u0006 והריהו כנוטל שמן מנר בוער בשבת, ובכך גורם לכיבוי מוקדם. \u0003אבל\u0004 שפופרת \u0003של חרס דמאיסא\u0004 \u0005[שהיא מאוסה]\u0006 — שמא \u0003אימא מודו ליה\u0004 \u0005[אמור\u0006 כי \u0005מודים\u0006 הם \u0005לו]\u0006 \u0003לר' יהודה\u0004 שאין לחשוש, ואף לדברי חכמים הדבר מותר. ולהיפך, \u0003אי אשמעינן\u0004 \u0005[אילו היה משמיע לנו]\u0006 איסור רק בשפופרת \u0003של חרס\u0004 — הייתי אומר כי דווקא \u0003בהא קאמר\u0004 \u0005[ב\u0006מקרה \u0005זה אומר]\u0006 \u0003ר' יהודה\u0004 שהיא מותרת, משום שהיא מאוסה, כאמור, \u0003אבל בההיא,\u0004 בשפופרת ביצה שאינה מאוסה — \u0003אימא מודי להו לרבנן\u0004 \u0005[הייתי אומר\u0006 כי \u0005מודה הוא לחכמים]\u0006 ואף לדבריו אסור. \u0003ואי אשמעינן הנך תרתי\u0004 \u0005[ואילו השמיענו\u0006 רק \u0005שתי אלה],\u0006 שפופרת של ביצה, ושל חרס הייתי אומר כי דווקא \u0003בהני קאמר\u0004 \u0005[באלה אמר]\u0006 \u0003ר' יהודה\u0004 שמותר \u0003משום דלא מיפסק\u0004 \u0005[שאין מובדל]\u0006 הנר מכלי הקיבול הנוסף, \u0003אבל קערה דמיפסקא\u0004 \u0005[ש\u0006היא \u0005מופסקת]\u0006 \u0003אימא מודי להו לרבנן\u0004 \u0005[הייתי אומר\u0006 כי \u0005מודה להם לחכמים]\u0006 ואף לדבריו אסור. ולהיפך, \u0003ואי אשמעינן בההיא\u0004 \u0005[ואילו היה משמיע לנו\u0006 רק \u0005בההיא],\u0006 בקערה הנוספת — הייתי אומר כי רק \u0003בההיא קאמרי רבנן\u0004 \u0005[אמרו חכמים]\u0006 שהדבר אסור, משום שהיא מופסקת, \u0003אבל בהני תרתי\u0004 \u0005[בשני אלו]\u0006 שפופרת של ביצה ושל חרס, \u0003אימא מודו\u0004 \u0005[הייתי אומר\u0006 כי \u0005מודים]\u0006 חכמים בכך \u0003לר' יהודה\u0004 ואף הם מתירים. על כן \u0003צריכא\u0004 \u0005[צריך]\u0006 לפרט ולומר הלכה זו בכל המקרים הנזכרים.","שנינו במשנה ש\u0003אם חברה היוצר\u0004 לאותה שפופרת אל הנר \u0003מתחלה מותר\u0004 למלאותה שמן ולהשתמש בה. ובברייתא \u0003תנא\u0004 \u0005[שנינו]\u0006 שאף \u0003אם חברה\u0004 בעל הבית בערב שבת מבעוד יום \u0003ב\u0004אמצעות \u0003סיד\u0004 או \u0003בחרסית\u0004 (טיט יבש) \u0003מותר.\u0004 ושואלים: \u0003והא אנן\u0004 \u0005[והרי אנחנו]\u0006 \u0003\"\u0004אם חיברה ה\u0003יוצר\" תנן\u0004 \u0005[שנינו]\u0006 ולא אחר כך! ומשיבים: \u0003מאי\u0004 \u0005[מה\u0006 משמעות\u0005]\u0006 \u0003\"יוצר \"\u0004ששנינו — כל חיבור שהוא \u0003כעין\u0004 החיבור של ה\u0003יוצר.\u0004","על מחלוקת ר' יהודה וחכמים \u0003תניא\u0004 \u0005[שנויה]\u0006 ברייתא ש\u0003אמר ר' יהודה\u0004 לחכמים: \u0003פעם אחת שבתינו\u0004 היתה \u0003אמורה להיות בעליית בית נתזה בלוד. והביאו לנו שפופרת ביצה ומלאנוה שמן ונקבנוה והנחנוה על פי הנר\u0004 כדי להאריך את זמן בעירתו, \u0003והיה שם ר' טרפון וזקנים\u0004 אחרים, \u0003ולא אמרו לנו דבר.\u0004 הרי שאין בכך משום איסור! \u0003אמרו לו\u0004 חכמים: \u0003משם ראיה?! שאני\u0004 \u0005[שונים]\u0006 החכמים שהיו יושבים ב\u0003בית נתזה\u0004 ש\u0003זריזין הן\u0004 ואין לחשוש להם שמא ישתמשו בשמן שבשפופרת הביצה ויקדימו בכך את כיבויו, אבל במקום אחר אסור.","ומסופר: \u0003אבין ציפוראה\u0004 \u0005[מ\u0006העיר \u0005ציפורי]\u0006 \u0003גרר ספסלא בעיליתא דשישא לעילא\u0004 \u0005[ספסל בעליה\u0006 שרצפתה \u0005שיש לפני]\u0006 \u0003ר' יצחק בן אלעזר. אמר ליה\u0004 \u0005[לו]\u0006 ר' יצחק בן אלעזר: \u0003אי שתוקי\u0004 \u0005[אם אשתוק]\u0006 \u0003לך כדשתיקו ליה חבריא\u0004 \u0005[כמו ששתקו לו בני החבורה],\u0006 ר' טרפון והחכמים \u0003לר' יהודה, נפיק מיניה חורבא\u0004 \u0005[יצא מזה נזק]\u0006 שינהגו בכך היתר לעתיד. שאילו היו מעירים בשעתו לר' יהודה שאסור לנקוב את שפופרת הביצה לא היה חולק על חכמים, ולומד משם היתר כללי לכל מלאכת שבת שאינו מתכוין בעשייתה לתוצאות העלולות לצאת ממלאכה זו. וכן כאן, \u0003גזירה\u0004 גזרו חכמים \u0003עליתא דשישא\u0004 \u0005[\u0006ב\u0005עליה\u0006 \u0003של שיש] אטו עליתא דעלמא\u0004 \u0005[משום עליה סתם]\u0006 שרצפתה אדמה, והגורר בה ספסל עושה בה חריץ.","ובענין גרירה, מסופר כי \u0003ריש כנישתא\u0004 \u0005[ראש הכנסת]\u0006 של \u0003בצרה גרר ספסלא לעילא\u0004 \u0005[ספסל לפני]\u0006 \u0003ר' ירמיה רבה\u0004 \u0005[הגדול]\u0006 בשבת. \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' ירמיה: \u0003כמאן\u0004 \u0005[כ\u0006דעת \u0005מי]\u0006 אתה מתיר לעצמך לגרור ספסל בשבת? — \u0003כ\u0004דעת \u0003ר' שמעון,\u0004 אך, \u0003אימר\u0004 \u0005[אמור]\u0006 ש\u0003אמר ר' שמעון\u0004 דבריו דווקא \u0003ב\u0004ספסלים \u0003גדולים דלא\u0004 \u0005[שאי]\u0006 \u0003אפשר\u0004 להעבירם ממקום למקום בדרך אחרת, \u0003אבל ב\u0004ספסלים \u0003קטנים מי\u0004 \u0005[האם]\u0006 \u0003אמר\u0004 שמותר לגוררם?! \u0003ופליגא\u0004 \u0005[וחלוקה]\u0006 אימרה זו על שיטת \u0003עולא.\u0004 ש\u0003אמר עולא\u0004 שה\u0003מחלוקת\u0004 בענין גרירה היא \u0003ב\u0004ספסלים \u0003קטנים, אבל ב\u0004ספסלים \u0003גדולים\u0004 ל\u0003דברי הכל מותר\u0004 לגוררם, שכן אין אפשרות להעבירם בדרך אחרת.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 על כך \u0003רב יוסף\u0004 ממה ששנינו בברייתא, ש\u0003ר' שמעון אומר: גורר אדם מטה, כסא וספסל\u0004 על גבי הרצפה בשבת אף שנעשה בכך חריץ, \u0003ובלבד שלא יתכוין\u0004 מלכתחילה \u0003לעשות חריץ.\u0004 ובברייתא זו \u0003קתני\u0004 \u0005[שנה]\u0006 חפצים \u0003גדולים\u0004 כמטה, \u0003וקתני\u0004 \u0005[ושנה]\u0006 \u0003קטנים\u0004 ככסא, ואם כן \u0003קשיא לתרוייהו\u0004 \u0005[קשה לשניהם]\u0006 לר' ירמיה הגדול שלדעתו אף ר' שמעון אוסר בקטנים, וכן לעולא שלדעתו אפילו חכמים מתירים בגדולים, שאם כדבריו לא הוצרך ר' שמעון להתיר!","ומשיבים כי \u0003עולא מתרץ לטעמיה\u0004 \u0005[מיישב\u0006 את הדברים \u0005לטעמו,\u0006 לשיטתו\u0005]\u0006 \u0003ור' ירמיה רבה מתרץ לטעמיה\u0004 \u0005[מיישב\u0006 את הדברים \u0005לטעמו,\u0006 לשיטתו\u0005].\u0006 ומפרטים: \u0003עולא מתרץ לטעמיה\u0004 \u0005[מיישב\u0006 את הדברים \u0005לטעמו,\u0006 לשיטתו\u0005]\u0006 — \u0003מטה דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003כסא,\u0004 שלר' שמעון מדובר כאן במטה קטנה שאפשר לשאת אותה כשם שנושאים כסא. \u0003ור' ירמיה רבה מתרץ לטעמיה\u0004 \u0005[הגדול מיישב\u0006 את הדברים \u0005לטעמו,\u0006 לשיטתו\u0005]\u0006 — \u0003כסא דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003מטה.\u0004 שהמדובר בכסא כבד שמוכרחים לגרור אותו.","על דברי ר' ירמיה \u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רבה\u0004 על כך ממה ששנינו במשנה: \u0003מוכרי כסות\u0004 המוכרים בגדי שעטנז \u0003מוכרין כדרכן\u0004 לגויים, ומותר להם לשים את הבגדים שהם מוכרים על כתפיהם, ואינם צריכים לחשוש ללבישת שעטנז, \u0003ובלבד שלא יתכוין\u0004 הלובש להנות מבגדים אלה \u0003בחמה\u0004 כהגנה \u0003מפני החמה,\u0004 או \u0003ב\u0004עונת ה\u0003גשמים\u0004 כהגנה \u0003מפני הגשמים.\u0004 ואילו \u0003הצנועין,\u0004 כלומר, אנשים הנזהרים והמדקדקים, היו נוהגים ש\u0003מפשילין במקל לאחוריהן\u0004 ותולין את בגדי השעטנז על המקל. \u0003והא הכא\u0004 \u0005[והרי כאן]\u0006 הרי \u0003אפשר למיעבד\u0004 \u0005[לעשות]\u0006 \u0003כ\u0004מו ה\u0003צנועין, דכי\u0004 \u0005[שכמו]\u0006 הספסלים \u0003הקטנים דמו\u0004 \u0005[\u0006הם \u0005נחשבים]\u0006 ובכל זאת \u0003כי\u0004 \u0005[כאשר]\u0006 הוא \u0003לא\u0004 מתכוין לכך — \u0003שרי\u0004 \u0005[התיר]\u0006 \u0003ר' שמעון\u0004 אפילו \u0003לכתחלה.\u0004 הרי שר' שמעון סבור כי איסור שאינו מתכוון לעשותו, ואף שבידו להמנע ממנו — אין צריך לחשוש ולא לעשותו, ועל פי אותו עקרון ברור כי ר' שמעון יתיר אף בספסלים קטנים, שכיוון שאינו מתכוון לעשות בגרירתם חריץ, מותר. והרי זו \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 על \u0003ר' ירמיה רבה\u0004 \u0005[הגדול]\u0006 שאסר לגרור ספסלים קטנים. ומסכמים: אכן, \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 היא.","\u0003המכבה את הנר\u0004 בשבת \u0003מפני שהוא מתירא מפני\u0004 ה\u0003גוים\u0004 שהוא מתחבא מהם בביתו או \u0003מפני\u0004 ה\u0003ליסטים,\u0004 או שהיה מתיירא \u0003מפני רוח רעה,\u0004 שהוא בדיכאון ונוח לו לשבת בחושך, או שכיבה את הנר \u0003מפני החולה\u0004 כדי \u0003שיישן\u0004 — הרי זה \u0003פטור.\u0004 ואולם \u0003כ\u0004ש\u0003חס על הנר\u0004 או \u0003כחס על השמן,\u0004 או \u0003כחס על הפתילה\u0004 וכיבה את הנר מפני אחד מאלו — \u0003חייב. ר' יוסי פוטר בכולן,\u0004 בכל המקרים הללו, שלדעתו אין בכיבוי זה משום מלאכה, \u0003חוץ מן\u0004 המקרה שהוא חס על \u0003הפתילה,\u0004 שרק אז יש בכיבוי מלאכת יצירה, \u0003מפני שהוא עושה פחם\u0004 בפתילה בשעת כיבויו."],["\u0003מדקתני סיפא\u0004 \u0005[ממה ששנה בסוף\u0006 המשנה\u0005]\u0006 שהמכבה את הנר בשבת \u0003חייב,\u0004 הרי \u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 שמשנה זו לשיטת \u0003ר' יהודה היא,\u0004 שלדעתו מי שעשה מלאכה בשבת, אף אם אינו צריך לגופה חייב עליה חטאת. שהרי בכיבוי הנר אינו צריך לדבר הנוצר מן הכיבוי כי אם למניעת האור. ואם כן, \u0003רישא במאי עסיקנא\u0004 \u0005[בראש,\u0006 המשנה, \u0005במה אנו עוסקים]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 מדובר \u0003ב\u0004מכבה את הנר בגלל \u0003חולה שיש בו סכנה\u0004 — הרי הלשון \"פטור\" אינה מדוייקת, אלא לשון \u0003\"מותר\" מיבעי ליה\u0004 \u0005[צריך היה לו]\u0006 לומר, שמפני הסכנה מותר חילול שבת אף לכתחילה. \u0003ואי\u0004 \u0005[ואם]\u0006 מדובר \u0003בחולה שאין בו סכנה\u0004 מדוע פטור המכבה? \u0003\"חייב חטאת \" מיבעי ליה\u0004 \u0005[צריך היה לו]\u0006 לומר!","ומשיבים: \u0003לעולם\u0004 המדובר \u0003בחולה שיש בו סכנה, ובדין הוא דליתני\u0004 \u0005[שישנה]\u0006 לשון \u0003\"מותר\", ואיידי דבעי למתני סיפא\u0004 \u0005[ו\u0006אולם \u0005מתוך שהיה צריך לשנות בסוף]\u0006 \u0003\"חייב\", תנא נמי רישא\u0004 \u0005[שנה גם כן בראש]\u0006 \u0003\"פטור\"\u0004 כדי להעמיד את המשנה בסגנון אחד, ואולם להלכה לא רק פטור אם עשה כן, אלא גם מותר לכתחילה. ושואלים: \u0003והתני\u0004 \u0005[והרי שנה]\u0006 \u0003ר' אושעיא\u0004: אם רוצה לכבות את הנר בשבת \u0003בשביל החולה שיישן — לא יכבה, ו\u0004אולם \u0003אם כבה\u0004 — בדיעבד \u0003פטור, אבל\u0004 מלכתחילה \u0003אסור\u0004 לעשות כן! ומשיבים: אין הדבר דומה, שברייתא \u0003ההיא\u0004 מדברת \u0003בחולה שאין בו סכנה ו\u0004לשיטת \u0003ר' שמעון היא,\u0004 שאמר שמלאכה שאינו צריך לגופה פטור עליה, ומשנתנו מדברת בחולה שיש בו סכנה.","מסופר: \u0003שאול שאילה\u0004 \u0005[שאלו שאלה]\u0006 \u0003זו לעילא\u0004 \u0005[לפני]\u0006 \u0003ר' תנחום\u0004 ש\u0003מן\u0004 העיירה \u0003נוי: מהו\u0004 הדין לענין \u0003לכבות בוצינא דנורא מקמי באישא בשבתא\u0004 \u0005[נר בוער מלפני החולה בשבת]?\u0006 ומסופר כי מסביב לשאלה זו דרש ר' תנחום דרשה שלמה באגדה ובהלכה. ו\u0003פתח ואמר: אנת\u0004 \u0005[אתה]\u0006 \u0003שלמה\u0004 המלך \u0003אן\u0004 \u0005[היכן]\u0006 \u0003חכמתך, אן סוכלנותך\u0004 \u0005[היכן\u0006 \u0003תבונתך]? לא דייך שדבריך סותרין\u0004 את \u0003דברי דוד אביך, אלא שדבריך סותרין\u0004 אף \u0003זה את זה.\u0004 כי \u0003דוד אביך אמר: \"לא המתים יהללו יה\u0004 ולא כל יורדי דומה\u0003\"\u0004 (תהלים קטו, יז), \u0003ואת\u0004 \u0005[ואתה]\u0006 \u0003אמרת \"ושבח אני את המתים\u0004 שכבר מתו מן החיים אשר המה חיים עדנה\u0003\"\u0004 (קהלת ד, ב). \u0003וחזרת ואמרת \"כי לכלב חי הוא טוב מן האריה המת\"\u0004 (קהלת ט, ד), הרי שיש כאן דעות שונות בהערכת החיים והמוות!","ותירץ את הסתירות הללו כך: \u0003לא קשיא\u0004 \u0005[אין\u0006 הדבר \u0005קשה],\u0006 כי \u0003הא דקאמר\u0004 \u0005[זה שאמר]\u0006 \u0003דוד \"לא המתים יהללו יה\" הכי קאמר\u0004 \u0005[כך אמר,\u0006 כך היתה כוונתו\u0005]:\u0006 \u0003לעולם יעסוק אדם בתורה ובמצות קודם שימות, שכיון ש\u0004כבר \u0003מת,\u0004 כלומר, אחר מותו הריהו \u0003בטל מן התורה ומן המצות ואין להקדוש ברוך הוא שבח\u0004 (הנאה) \u0003בו\u0004 עוד. \u0003והיינו\u0004 \u0005[וזהו]\u0006 ש\u0003אמר ר' יוחנן, מאי דכתיב\u0004 \u0005[מה\u0006 משמעות \u0005זה שנאמר]\u0006 \u0003\"במתים חפשי\u0004 כמו חללים שוכבי קבר אשר לא זכרתם עוד\u0003\"\u0004 (תהלים פח, ו) — \u0003כיון שמת אדם\u0004 הריהו \u0003נעשה חפשי מן התורה ומן המצות.\u0004","\u0003ו\u0004מה ש\u0003אמר שלמה \"ושבח אני את המתים שכבר מתו\"\u0004 — לא בכל המתים אמר כך, אלא בשבח מתים מסויימים. \u0003שכשחטאו ישראל במדבר עמד משה לפני הקדוש ברוך הוא ואמר כמה תפלות ותחנונים לפניו ולא נענה, וכשאמר \"זכור לאברהם ליצחק ולישראל עבדיך\"\u0004 (שמות לב, יג) — \u0003מיד נענה. ו\u0004אם כן \u0003לא יפה אמר שלמה \"ושבח אני את המתים שכבר מתו \"?\u0004 ובודאי יפה זכות האבות המתים מן הצדיקים החיים. או \u0003דבר אחר: מנהגו של עולם\u0004 שכאשר \u0003שר\u0004 (מלך) \u0003בשר ודם גוזר גזרה\u0004 על הציבור — \u0003ספק\u0004 הם \u0003מקיימין אותה ספק אין מקיימין אותה\u0004. \u0003ואם תמצי לומר\u0004 \u0005[ו\u0006אף \u0005אם תרצה לומר]\u0006 ש\u0003מקיימין אותה\u0004 — הרי רק \u0003בחייו מקיימין אותה\u0004 ואילו \u0003במותו אין מקיימין אותה. ואילו משה רבינו גזר כמה גזירות ותיקן כמה תקנות וקיימות הן לעולם ולעולמי עולמים. ו\u0004כי \u0003לא יפה\u0004 אם כן מה ש\u0003אמר שלמה \"ושבח אני את המתים\u0004 שכבר מתו \u0003\"?!\u0004","\u0003דבר אחר\u0004 ניתן לפרש את דברי הכתוב \u0003\"ושבח אני\u0004 את המתים שכבר מתו \u0003\"כ\u0004מו ש\u0003אמר רב יהודה\u0004 ש\u0003אמר\u0004 בשם רב. ש\u0003אמר רב יהודה אמר רב: מאי דכתיב\u0004 \u0005[מה\u0006 משמעות כתוב זה \u0005שנאמר]\u0006 בהסברת הכתוב \u0003\"עשה עמי אות לטובה ויראו שנאי ויבשו\"\u0004 (תהלים פו, יז) — \u0003אמר דוד לפני הקדוש ברוך הוא: רבונו של עולם, מחול לי על אותו עון\u0004 בענין בת שבע. \u0003אמר לו: מחול לך. אמר לו\u0004 דוד: \u0003עשה עמי אות בחיי\u0004 שידעו הכל שמחלת לי. \u0003אמר לו\u0004 הקדוש ברוך הוא: \u0003בחייך איני מודיע\u0004 שנמחל לך, ואולם \u0003בחיי שלמה בנך אני מודיע.\u0004","ו\u0003כשבנה שלמה את בית המקדש\u0004 ו\u0003ביקש להכניס\u0004 את ה\u0003ארון לבית קדשי הקדשים דבקו\u0004 ה\u0003שערים זה בזה\u0004 ולא ניתן היה לפתחם. \u0003אמר שלמה עשרים וארבעה רננות,\u0004 שאמר בתפילתו עשרים וארבע לשונות של תפילה, רינה וכו' (מלכים א, ח), \u0003ולא נענה. פתח ואמר: \"שאו שערים ראשיכם והנשאו פתחי עולם ויבא מלך הכבוד\"\u0004 (תהלים כד, ז). מיד \u0003רהטו בתריה למיבלעיה\u0004 \u0005[רצו אחריו לבולעו]\u0006 שחשבו שבמלים \"מלך הכבוד\" הוא מתכוון לעצמו, ו\u0003אמרו\u0004 לו: \u0003מי הוא זה מלך הכבוד\"\u0004 (תהלים כד , ח). \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003\"ה' עזוז וגבור\u0004 ה' גבור מלחמה\" (תהלים כד, ח). ו\u0003חזר ואמר: \"שאו שערים ראשיכם ושאו פתחי עולם ויבא מלך הכבוד מי הוא זה מלך הכבוד ה' צבאות הוא מלך הכבוד סלה\"\u0004 (תהלים ט, י), \u0003ולא נענה. כיון שאמר \"ה' אלהים אל תשב פני משיחך זכרה לחסדי דוד עבדך\"\u0004 (דברי הימים ב' ו, מב), \u0003מיד נענה\u0004 וירדה האש מן השמים. (דברי הימים ב' ז, א). \u0003באותה שעה נהפכו פני כל שונאי דוד כשולי קדירה\u0004 (תחתיתה המפוחמת של קדירה). \u0003וידעו ישראל שמחל לו הקדוש ברוך הוא על אותו עון. ו\u0004אם כן וכי \u0003לא יפה אמר שלמה \"ושבח אני את המתים שכבר מתו\",\u0004 כלומר, את דוד, יותר \"מן החיים\" שלא נענה להם הקדוש ברוך הוא.","\u0003והיינו דכתיב\u0004 \u0005[וזהו שנאמר]:\u0006 \u0003ביום השמיני שלח את העם ויברכו את המלך וילכו לאהליהם שמחים וטובי לב על כל הטובה אשר עשה ה' לדוד עבדו ולישראל עמו\"\u0004 (מלכים א' ח, סו). ומפרש: \u0003\"וילכו לאהליהם\"\u0004 — לפי הביטוי הרגיל של \"ביתו זו אשתו\" מפורש \u0003שמצאו נשותיהן\u0004 כשהן \u0003בטהרה\u0004 מטומאת נדה בבואם. \u0003\"שמחים\"\u0004 — \u0003שנהנו מזיו השכינה\u0004 בחנוכת המקדש. \u0003\"וטובי לב\"\u0004 — \u0003שנתעברו נשותיהן של כל אחד ואחד וילדה זכר. \"על כל הטובה אשר עשה ה' לדוד עבדו ולישראל עמו\", \"לדוד עבדו\"\u0004 — שראו הכל באותה הזדמנות \u0003שמחל לו\u0004 הקדוש ברוך הוא \u0003על אותו עון. \"ולישראל עמו\"\u0004 — \u0003דאחיל להו\u0004 \u0005[שמחל להם]\u0006 על ה\u0003עון\u0004 של \u0003יום הכפורים\u0004 שבאותה שנה לא צמו (עיין מלכים א' ח, סה).","וממשיכים: \u0003ודקאמר\u0004 \u0005[ו\u0006מה \u0005שאמר]\u0006 \u0003שלמה כי \"לכלב חי הוא טוב מן האריה המת\"\u0004 (קהלת ט, ד) — יש להבינו על פי מה שסיפר \u0003רב יהודה\u0004 ש\u0003אמר רב.\u0004 ש\u0003אמר רב יהודה אמר רב: מאי דכתיב\u0004 \u0005[מה\u0006 משמעות כתוב זה \u0005שנאמר]\u0006 שאמר דוד \u0003\"הודיעני ה' קצי ומדת ימי מה היא, אדעה מה חדל אני\"\u0004 (תהלים לט, ה) — כך פירושו: \u0003אמר דוד לפני הקדוש ברוך הוא: רבונו של עולם, הודיעני ה' קצי,\u0004 מתי, בעוד כמה זמן, אמות? \u0003אמר לו\u0004 הקדוש ברוך הוא: \u0003גזרה היא מלפני שאין מודיעין קצו של בשר ודם.\u0004 וביקש עוד: \u0003\"ומדת ימי מה היא\",\u0004 כלומר, באיזה יום בשנה ימות. אמר לו: \u0003גזרה היא מלפני שאין מודיעין\u0004 לבשר ודם \u0003מדת ימיו של אדם.\u0004 ושוב ביקש: \u0003\"ואדעה מה חדל אני\",\u0004 באיזה יום בשבוע אמות? \u0003אמר לו: בשבת תמות.\u0004 בקש דוד מה': \u0003אמות באחד בשבת\u0004 שלא יגע כבוד השבת בצער המוות. \u0003אמר לו:\u0004 ביום זה \u0003כבר הגיע\u0004 זמן \u0003מלכות שלמה בנך, ואין מלכות נוגעת בחברתה\u0004 ונוטלת מן הקצוב לה \u0003אפילו כמלא נימא\u0004 (שערה). אמר לו: אוותר על יום אחד מחיי ו\u0003אמות בערב שבת. אמר לו\u0004 הקדוש ברוך הוא: \u0003\"כי טוב יום בחצריך מאלף\"\u0004 (תהלים פד, יא) — \u0003טוב לי יום אחד שאתה יושב ועוסק בתורה\u0004 יותר \u0003מאלף עולות שעתיד שלמה בנך להקריב לפני על גבי המזבח\u0004 (עיין מלכים א' ג, ד)."],["\u0003כל יומא דשבתא הוה יתיב וגריס כולי יומא\u0004 \u0005[יום השבת היה יושב ולומד כל היום]\u0006 להגן ממלאך המוות. \u0003ההוא יומא דבעי למינח נפשיה, קם\u0004 \u0005[אותו יום שהיתה צריכה לנוח נפשו,\u0006 היה צריך להיפטר מן העולם, \u0005עמד]\u0006 \u0003מלאך המות קמיה\u0004 \u0005[לפניו]\u0006 \u0003ולא יכיל ליה\u0004 \u0005[יכול\u0006 היה \u0005לו],\u0006 משום ש\u0003לא הוה פסק פומיה מגירסא\u0004 \u0005[היה פוסק פיו מלימוד].\u0006 \u0003אמר\u0004 מלאך המות: \u0003מאי אעביד ליה\u0004 \u0005[מה אעשה לו]?\u0006 \u0003הוה ליה בוסתנא\u0004 \u0005[היה לו בוסתן,\u0006 גן\u0005]\u0006 \u0003אחורי ביתיה\u0004 \u0005[ביתו],\u0006 \u0003אתא\u0004 \u0005[בא]\u0006 \u0003מלאך המות סליק ובחיש באילני\u0004 \u0005[עלה\u0006 \u0003ונענע באילנות]. נפק למיחזי\u0004 \u0005[יצא\u0006 דוד \u0005לראות].\u0006 \u0003הוה סליק בדרגא איפחית דרגא מתותיה, אישתיק ונח נפשיה\u0004 \u0005[\u0006כש\u0005היה עולה במדרגות נפחתה המדרגה מתחתיו,\u0006 נבהל \u0005ו\u0006\u0005שתק\u0006 לרגע, \u0005ונחה נפשו,\u0006 נפטר\u0005].\u0006","וכיון שמת בגן \u0003שלח שלמה לבי מדרשא\u0004 \u0005[לבית המדרש]\u0006 שאלות אלה: \u0003אבא מת ומוטל בחמה, וכלבים של בית אבא רעבים\u0004 (ויש לחשוש שמא יבואו להזיק לגופו) \u0003מה אעשה? שלחו ליה\u0004 \u0005[לו]\u0006 בתשובה: \u0003חתוך נבלה והנח לפני הכלבים,\u0004 שבשביל שהכלבים הרעבים מותר לטלטל את הנבילה ולהאכיל אותם בה. \u0003ו\u0004ביחס ל\u0003אביך,\u0004 אין היתר לטלטלו במישרין, אלא \u0003הנח עליו ככר\u0004 לחם \u0003או תינוק וטלטלו\u0004 למקום הצל אגב התינוק או הכיכר. \u0003ו\u0004כי \u0003לא יפה אמר שלמה: \"כי לכלב חי הוא טוב מן האריה המת\",\u0004 ואם כן מסקנת כל הדברים היא שעדיפים החיים. \u0003ו\u0004מכאן \u0003לענין שאילה דשאילנא קדמיכון\u0004 \u0005[השאלה ששאלתי לפניכם],\u0006 שאמר בלשון ענוה, כלומר, השאלה ששאלתם אותי, הרי \u0003הנר קרויה \"נר\" ו\u0004גם \u0003נשמתו של אדם קרויה \"נר\"\u0004 (\"נר ה' נשמת אדם\". משלי כ, כז), \u0003מוטב\u0004 ש\u0003תכבה נר של בשר ודם\u0004 כדי שלא יכבה \u0003נרו של הקדוש ברוך הוא.\u0004 ומותר איפוא לכבות את הנר לצורך החולה.","ומאחר שהוזכרו הסתירות בספר קהלת, מביאים דברים נוספים בענין זה. \u0003אמר רב יהודה בריה\u0004 \u0005[בנו]\u0006 של \u0003רב שמואל בר שילת משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב: בקשו חכמים לגנוז\u0004 את \u0003ספר קהלת מפני שדבריו סותרין זה את זה\u0004 ועשוי הוא לבלבל את קוראיו. \u0003ומפני מה לא גנזוהו?\u0004 — \u0003מפני שתחילתו דברי תורה וסופו דברי תורה.\u0004 והפרטים הנראים כסותרים טפלים הם לעיקר הספר המכוון לתורה. ומפרטים: \u0003תחילתו דברי תורה\u0004 — \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 בו: \u0003\"מה יתרון לאדם בכל עמלו שיעמול תחת השמש\"\u0004 (קהלת א, ג), \u0003ואמרי דבי\u0004 \u0005[ואמרו\u0006 חכמי \u0005בית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ינאי:\u0004 יש להבין זאת ש\u0003\"תחת השמש \" הוא\u0004 ש\u0003אין לו\u0004 לאדם יתרון בעמלו, אבל \u0003קודם\u0004 ה\u0003שמש,\u0004 כלומר, בעיסוק בתורה שהיא קדמה לשמש — \u0003יש לו\u0004 יתרון. וכן \u0003סופו דברי תורה, דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"סוף דבר הכל נשמע את האלהים ירא ואת מצותיו שמור כי זה כל האדם\"\u0004 (קהלת יב, יג): ואגב הזכרת הפסוק שואלים: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש הכתוב \u0003\"כי כל האדם\"? אמר ר' אליעזר: כל העולם כולו לא נברא אלא בשביל\u0004 אדם \u0003זה. ר' אבא בר כהנא אמר: שקול\u0004 אדם \u0003זה כנגד כל העולם כולו.\u0004 ו\u0003שמעון בן עזאי אומר, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 ש\u0003שמעון בן זומא אומר\u0004 זאת: יתר על כן, \u0003לא נברא כל העולם כולו אלא לצוות\u0004 (להתחבר) \u0003לזה,\u0004 שלא יהיה בודד.","ולגופו של ענין שואלים: \u0003מאי\u0004 \u0005[מה]\u0006 התכוין בדבריו \u0003\"דבריו סותרין זה את זה\"?\u0004 שבפסוק אחד \u0003כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"טוב כעס משחוק\"\u0004 (קהלת ז, ג), \u0003ו\u0004מצד שני \u0003כתיב\u0004 \u0005[נאמר]\u0006 שם \u0003\"לשחוק אמרתי מהולל\"\u0004 (קהלת ב, ב). והבינוהו שהכוונה \"משובח\"?! וכן בפסוק אחד \u0003כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"ושבחתי אני את השמחה\"\u0004 (קהלת ח, טו) \u0003ו\u0004במקום אחר \u0003כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"ולשמחה מה זה עשה\u0004 (קהלת ב, ב)?! ומתרצים: \u0003לא קשיא\u0004 \u0005[אין\u0006 הדבר \u0005קשה]\u0006 שכן יש להסביר \u0003כי \"טוב כעס משחוק\"\u0004 משמעו: \u0003טוב\u0004 ה\u0003כעס שכועס הקדוש ברוך הוא על הצדיקים בעולם הזה, משחוק שמשחק הקדוש ברוך הוא על\u0004 (עם) \u0003הרשעים\u0004 ונותן להם כל טוב \u0003בעולם הזה. ו\u0004אילו \u0003\"לשחוק אמרתי מהולל\"\u0004 — \u0003זה\u0004 ה\u0003שחוק שמשחק הקדוש ברוך הוא עם הצדיקים בעולם הבא.\u0004","ובדומה לכך, \u0003\"ושבחתי אני את השמחה\"\u0004 — זו \u0003שמחה של מצוה, \"ולשמחה מה זה עושה\"\u0004 — \u0003זו שמחה שאינה של מצוה.\u0004 ומשבחה של השמחה למדנו \u0003שאין השכינה שורה לא מתוך עצבות, ולא מתוך עצלות, ולא מתוך שחוק, ולא מתוך קלות ראש, ולא מתוך שיחה\u0004 סתם, \u0003ולא מתוך דברים בטלים, אלא מתוך דבר שמחה של מצוה.\u0004 וכפי \u0003שנאמר\u0004 באלישע, שלאחר שכעס על מלך ישראל לא שרתה עליו הנבואה, אלא לאחר שביקש \u0003\"ועתה קחו לי מנגן והיה כנגן המנגן ותהי עליו יד ה'\"\u0004 (מלכים ב' ג, טו). \u0003אמר רב יהודה: וכן\u0004 הוא, שיש להקדים דברי בדיחות ושמחה לפני אמירת \u0003דבר הלכה. אמר רבא: וכן\u0004 יש לאדם להיות בשמחה לפני השינה אם רוצה שיחלום בשנתו \u0003חלום טוב.\u0004","ושואלים: \u0003איני\u0004 \u0005[ו\u0006כי \u0005כן היא]\u0006 שיש לפתוח לפני אמירת הלכה בדבר שמחה, \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב גידל אמר רב: כל תלמיד חכם שיושב לפני רבו ואין שפתותיו נוטפות\u0004 (מלאות) \u0003מר\u0004 (מרירות) מחמת אימת רבו, \u0003תכוינה\u0004 שפתיים אלה, וכפי \u0003שנאמר: \"שפתותיו שושנים נטפות מור עבר\"\u0004 (שיר השירים ה, יג). ודרש: \u0003אל תקרי\u0004 \u0005[תקרא]\u0006 \u0003\"מור עבר\", אלא \"מר עבר \".\u0004 וכן \u0003אל תקרי\u0004 \u0005[תקרא]\u0006 \u0003\"שושנים \" אלא \"ששונים\",\u0004 כלומר, השפתיים השונות בתורה צריכות להיות מלאות מרירות. ומסבירים: אין כאן סתירה, שכן \u0003הא\u0004 \u0005[זה]\u0006 ששנינו שצריך להיות בשמחה לפני אמירת דבר הלכה הרי זה מדובר \u0003ברבה\u0004 \u0005[ברב],\u0006 \u0003והא\u0004 \u0005[וזה]\u0006 ששנינו שצריך להיות מלא מרירות הרי זה \u0003בתלמיד\u0004 שצריך להקשיב לרבו באימה. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 כי \u0003הא והא\u0004 \u0005[זה וזה]\u0006 מדובר \u0003ברבה\u0004 \u0005[ברב],\u0006 \u0003ולא קשיא\u0004 \u0005[ואין\u0006 הדבר \u0005קשה],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 ששנינו שצריך להיות בשמחה, הרי זה \u0003מקמי דלפתח\u0004 \u0005[לפני שיפתח]\u0006 הרב בשיעורו, ואילו \u0003הא\u0004 \u0005[זה]\u0006 ששנינו שצריך להיות מלא מרירות מאימת רבו, הרי זה \u0003לבתר\u0004 \u0005[לאחר]\u0006 שכבר \u0003פתח\u0004 הרב בדברי הלכה. \u0003כי הא\u0004 \u0005[כמו\u0006 מנהג \u0005זה]\u0006 שנהג \u0003רבה, מקמי\u0004 \u0005[לפני]\u0006 ש\u0003פתח להו לרבנן\u0004 \u0005[להם לחכמים]\u0006 בדבר \u0003הלכה אמר מילתא דבדיחותא ובדחי רבנן\u0004 \u0005[היה אומר דברי בדיחה והיו מתבדחים החכמים],\u0006 ו\u0003לסוף יתיב באימתא ופתח בשמעתא\u0004 \u0005[לבסוף היה\u0006 יושב \u0005באימה והיה פותח בהלכה]\u0006.","אומרים עוד כי \u0003אף\u0004 את \u0003ספר משלי בקשו\u0004 החכמים \u0003לגנוז\u0004 משום \u0003שהיו דבריו סותרין זה את זה. ומפני מה לא גנזוהו? אמרי\u0004 \u0005]אמרו[\u0006: \u0003ספר קהלת לאו עיינינן ואשכחינן טעמא\u0004 \u0005[האם לא עיינו ומצאנו טעם]?\u0006 \u0003הכי נמי ליעיינן\u0004 \u0005[אף כאן נעיין].\u0006 \u0003ומאי\u0004 \u0005[ומה]\u0006 הם אותם דברים שאמרנו ש\u0003דבריו סותרים זה את זה?\u0004 — שמצד אחד \u0003כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"אל תען כסיל כאולתו\u0004 פן תשוה לו גם אתה\u0003\"\u0004 (משלי כו, ד), \u0003ו\u0004מצד אחר \u0003כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"ענה כסיל כאולתו\u0004 פן יהיה חכם בעיניו\u0003\"\u0004 (משלי כו, ה)?! ומתרצים: \u0003לא קשיא, הא\u0004 \u0005[זה]\u0006 שנאמר שיש לענות לכסיל זהו כשהוא טוען \u0003בדברי תורה,\u0004 ואילו \u0003הא\u0004 \u0005[זה]\u0006 שנאמר שאין לענות לו הרי זה \u0003במילי דעלמא\u0004 \u0005[בענייני העולם].\u0006 וסיפרו כיצד נהגו חכמים בשני הדברים.","\u0003כי הא דההוא דאתא לקמיה\u0004 \u0005[כמו\u0006 מעשה \u0005זה, שאותו אדם בא לפני רבי]\u0006 \u0003רבי\u0004 ו\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אשתך\u0004 — \u0003אשתי ובניך\u0004 — \u0003בני. אמר ליה\u0004 \u0005[לו]\u0006 רבי: האם \u0003רצונך שתשתה כוס של יין? שתה ופקע\u0004 (מת). וכעין זה מסופר: \u0003ההוא דאתא לקמיה\u0004 \u0005[אותו אדם שבא לפני]\u0006 \u0003ר' חייא, אמר ליה\u0004 \u0005[לו]\u0006 ר' חייא: \u0003אמך אשתי ואתה בני. אמר ליה\u0004 \u0005[לו]:\u0006 \u0003רצונך שתשתה כוס של יין? שתה ופקע. אמר ר' חייא\u0004 על מה שקרה לרבי: \u0003אהניא ליה צלותיה\u0004 \u0005[הואילה לו תפילתו]\u0006 \u0003לרבי\u0004 ש\u0003לא לשווייה בני ממזירי\u0004 \u0005[יעשה\u0006 את \u0005בניו ממזרים].\u0006 ש\u0003רבי כי הוה מצלי אמר\u0004 \u0005[כאשר היה מתפלל היה אומר]\u0006 אחר תפילתו: \u0003\"יהי רצון מלפניך ה' אלהינו, שתצילני היום מעזי פנים ומעזות פנים\"\u0004 ועזות פנים היא הממזרות. ומתוך תפילתו פקע אותו אדם, ולא הספיק להוציא לעז על בניו של רבי.","ואילו, \u0003בדברי תורה מאי\u0004 \u0005[מה]\u0006 \u0003היא\u0004 שאמרו שמותר לענות כסיל כאיולתו? — \u0003כי הא דיתיב\u0004 \u0005[כמו\u0006 מעשה \u0005זה שהיה יושב]\u0006 \u0003רבן גמליאל וקא דריש\u0004 \u0005[והיה דורש]:\u0006 \u0003עתידה אשה\u0004 לעולם הבא \u0003שתלד בכל יום, שנאמר \"הרה ויולדת יחדיו\"\u0004 (ירמיהו לא, ז), ופירש שביום ההריון תהיה הלידה. \u0003ליגלג עליו אותו תלמיד\u0004 ו\u0003אמר:\u0004 אין הדבר יכול להיות, שכן כבר נאמר \u0003\"אין כל חדש תחת השמש \"! אמר לו\u0004 רבן גמליאל: \u0003בא ואראך דוגמתן\u0004 של דברים אלה \u0003בעולם הזה. נפק אחוי ליה\u0004 \u0005[יצא והראה לו]\u0006 \u0003תרנגולת\u0004 שזה דרכה שהיא מטילה בכל יום.","\u0003ותו\u0004 \u0005[ועוד]:\u0006 \u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003רבן גמליאל וקא דריש\u0004 \u0005[והיה דורש]:\u0006 \u0003עתידים אילנות\u0004 לעולם הבא \u0003ש\u0004יהיו \u0003מוציאין פירות בכל יום,\u0004 וכפי \u0003שנאמר: \"ונשא ענף ועשה פרי\"\u0004 (יחזקאל יז, כג) — \u0003מה ענף גדל בכל יום אף\u0004 ה\u0003פרי\u0004 יהיה \u0003בכל יום. ליגלג עליו אותו תלמיד\u0004 ו\u0003אמר: והכתיב\u0004 \u0005[והרי נאמר]\u0006 \u0003\"אין כל חדש תחת השמש\". אמר לו: בא ואראך דוגמתם בעולם הזה. נפק אחוי ליה\u0004 \u0005[יצא והראה לו]\u0006 \u0003צלף,\u0004 שבכל עונה בשנה יש בו חלק מסויים הראוי לאכילה.","\u0003ותו\u0004 \u0005[ועוד]:\u0006 \u0003יתיב\u0004 \u0005[היה יושב]\u0006 \u0003רבן גמליאל וקא דריש\u0004 \u0005[והיה דורש]:\u0006 \u0003עתידה ארץ ישראל\u0004 לעתיד לבוא \u0003שתוציא גלוסקאות\u0004 (עוגות) \u0003וכלי מילת\u0004 (צמר מובחר) מוכנים \u0003שנאמר יהי פסת בר בארץ\u0004 \u0005(תהלים עב, טז)\u0006. \u0003ליגלג עליו אותו תלמיד ואמר:\u0004 והלא כבר נאמר \u0003\"אין כל חדש תחת השמש\". אמר ליה\u0004 \u0005[לו]\u0006 רבן גמליאל: \u0003בא ואראך דוגמתן בעולם הזה. נפק אחוי ליה\u0004 \u0005[יצא\u0006 ו\u0005הראה לו]\u0006 \u0003כמיהין ופטריות\u0004 היוצאים גמורים מהאדמה במשך לילה אחד, ויש להם תבנית של ככרות לחם. \u0003ו\u0004לגבי \u0003כלי מילת\u0004 — הראה לו \u0003נברא בר קורא\u0004 \u0005[לבוש ענף הדקל],\u0006 שכשהוא צעיר יוצא הוא עטוף בכעין רשת דקה.","וכיון שדובר בסבלנותם של תלמידי חכמים לשמוע הערות הבל ולשתוק, הביאו מעשים נוספים מעין זה. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003לעולם יהיה אדם ענוותן כהלל ואל יהא קפדן כשמאי.\u0004 שסיפרו: \u0003מעשה בשני בני אדם\u0004"],["\u0003שהמרו זה את זה\u0004 (התערבו) ו\u0003אמרו: כל מי שילך ויקניט\u0004 (ירגיז) \u0003את הלל\u0004 עד שיגער בו \u0003יטול ארבע מאות זוז.\u0004 ו\u0003אמר אחד מהם: אני אקניטנו.\u0004 ו\u0003אותו היום\u0004 שבחר לשם כך \u0003ערב שבת היה, והלל חפף את ראשו. הלך ועבר\u0004 אז \u0003על פתח ביתו\u0004 של הלל ובלשון זלזול \u0003אמר: מי כאן הלל, מי כאן הלל? נתעטף\u0004 הלל בלבוש מכובד \u0003ויצא לקראתו. אמר לו: בני, מה אתה מבקש? אמר לו: שאלה יש לי לשאול. אמר לו\u0004 הלל: \u0003שאל בני. שאל: מפני מה ראשיהן של\u0004 ה\u0003בבליים סגלגלות\u0004 (עגולים מדי)? ועל ידי כך רצה ברמז להעליב את הלל שהיה מבבל. \u0003אמר לו\u0004: \u0003בני, שאלה גדולה שאלת.\u0004 וטעמו של דבר: \u0003מפני שאין להם חיות\u0004 (מילדות) \u0003פקחות\u0004 ואינן יודעות לעצב את צורת קדקדו של הילד.","\u0003הלך\u0004 אותו אדם \u0003והמתין שעה אחת\u0004 (זמן מסויים), ושוב \u0003חזר\u0004 וחיפש את הלל ו\u0003אמר : מי כאן הלל, מי כאן הלל?\u0004 ושוב \u0003נתעטף\u0004 הלל \u0003ויצא לקראתו. אמר לו\u0004 הלל: \u0003בני, מה אתה מבקש? אמר לו\u0004 אותו אדם: \u0003שאלה יש לי לשאול. אמר לו: שאל.\u0004 ו\u0003שאל: מפני מה עיניהן של תרמודיין\u0004 (בני תדמור) \u0003תרוטות\u0004 (ממצמצות ורכות)? \u0003אמר לו\u0004 הלל: \u0003בני, שאלה גדולה שאלת,\u0004 וטעמו של דבר — \u0003מפני ש\u0004הם \u0003דרין בין החולות,\u0004 והחול נכנס לתוך עיניהם.","ושוב \u0003הלך\u0004 אותו האיש \u0003והמתין שעה אחת\u0004 ו\u0003חזר ואמר: מי כאן הלל, מי כאן הלל?\u0004 ושוב \u0003נתעטף\u0004 הלל \u0003ויצא לקראתו,\u0004 ו\u0003אמר לו: בני, מה אתה מבקש? אמר לו: שאלה יש לי לשאול. אמר לו: שאל בני. שאל\u0004 אותו האיש: \u0003מפני מה רגליהם של אפרקיים רחבות? אמר לו\u0004 הלל: \u0003שאלה גדולה שאלת,\u0004 וטעמו של דבר — \u0003מפני ש\u0004הם \u0003דרין בין בצעי המים\u0004 (ביצות) ורגליהם מתרחבות, שיוכלו להלך במקום טובעני כזה.","הוסיף ו\u0003אמר לו\u0004 אותו אדם: \u0003שאלות הרבה יש לי לשאול\u0004 עוד, \u0003ו\u0004אולם \u0003מתירא אני שמא תכעוס. נתעטף\u0004 הלל \u0003וישב לפניו\u0004 ו\u0003אמר לו: כל\u0004 ה\u0003שאלות שיש לך לשאול שאל.\u0004 כעס אותו אדם ואמר: \u0003וכי אתה הוא הלל שקורין\u0004 (קוראים) \u0003אותך \"נשיא ישראל\"? אמר לו: הן\u0004 \u0005[כן].\u0006 \u0003אמר לו: אם אתה הוא\u0004 זה, אם כן ש\u0003לא ירבו כמותך בישראל. אמר לו\u0004 הלל: \u0003בני, מפני מה\u0004 אתה אומר כך? \u0003אמר לו\u0004 אותו אדם: \u0003מפני שאבדתי על ידך\u0004 (בגללך) \u0003ארבע מאות זוז. אמר לו\u0004 הלל: \u0003הוי זהיר ברוחך\u0004 שלא להתערב בכעין זה, ו\u0003כדי\u0004 (כדאי) \u0003הוא הלל,\u0004 כלומר, מסוגל הוא, \u0003שתאבד על ידו\u0004 בדרך זו \u0003ארבע מאות זוז ו\u0004עוד \u0003ארבע מאות זוז והלל לא יקפיד.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מעשה בגוי אחד שבא לפני שמאי. אמר לו\u0004 אותו גוי לשמאי: \u0003כמה תורות יש לכם? אמר לו: שתים, תורה שבכתב ותורה שבעל פה. אמר לו\u0004 הגוי: על התורה \u0003שבכתב אני מאמינך, ו\u0004תורה \u0003שבעל פה\u0004 — \u0003איני מאמינך. גיירני על מנת שתלמדני\u0004 את ה\u0003תורה שבכתב\u0004 בלבד. \u0003גער בו\u0004 שמאי \u0003והוציאו בנזיפה. בא\u0004 אותו גוי \u0003לפני הלל\u0004 ו\u0003גייריה\u0004 \u0005[גיירו],\u0006 והתחיל ללמדו תורה. \u0003יומא קמא אמר ליה\u0004 \u0005[ביום הראשון אמר\u0006 והראה \u0005לו]\u0006 את אותיות האל\"ף בי\"ת: \u0003אלף, בית, גימל, דלת. למחר אפיך ליה\u0004 \u0005[הפך לו]\u0006 את סדר האותיות ואמר לו על אל\"ף שהוא ת\"ו וכיוצא, \u0003אמר ליה\u0004 \u0005[לו]\u0006 הגר: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אתמול לא אמרת לי הכי\u0004 \u0005[כך]!\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 הלל: אם כן רואה אתה שאי אפשר לדעת אף דברים הכתובים במפורש מבלי להסתמך על מסורת שבעל פה, ו\u0003לאו עלי דידי סמכת\u0004 \u0005[ולא עלי אתה סומך]?\u0006 ואם כן בענין שב\u0003על פה נמי\u0004 \u0005[גם כן]\u0006 \u0003סמוך עלי,\u0004 וקבל את הפרשנות שיש בה.","ו\u0003שוב מעשה בגוי אחד שבא לפני שמאי, אמר לו\u0004 אותו גוי לשמאי: \u0003גיירני על מנת שתלמדני\u0004 את \u0003כל התורה כולה כשאני עומד על רגל אחת! דחפו\u0004 שמאי \u0003באמת הבנין שבידו,\u0004 שהיה שמאי בנאי במקצועו. \u0003בא\u0004 אותו גוי \u0003לפני הלל, גייריה\u0004 \u0005[גיירו]\u0006 ו\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003דעלך סני לחברך לא תעביד\u0004 \u0005[\u0006מה \u0005שעליך שנוא אל תעשה לחברך],\u0006 \u0003זו היא כל התורה כולה, ואידך\u0004 \u0005[והשאר]\u0006 \u0003פירושה הוא זיל גמור\u0004 \u0005[לך\u0006 ו\u0005למד].\u0006","ו\u0003שוב מעשה בגוי אחד שהיה עובר אחורי בית המדרש ושמע קול סופר\u0004 (מלמד תינוקות) \u0003שהיה\u0004 מלמד תורה לתלמידיו ואומר את מאמר הכתוב \u0003\"ואלה הבגדים אשר יעשו חשן ואפוד\u0004 ומעיל וכתנת תשבץ מצנפת ואבנט\u0003\"\u0004 (שמות כח, ד), ו\u0003אמר:\u0004 בגדים \u0003הללו למי\u0004 הם מיועדים? \u0003אמרו לו\u0004 התלמידים: \u0003לכהן גדול. אמר אותו גוי בעצמו: אלך ואתגייר בשביל שישימוני כהן גדול. בא לפני שמאי\u0004 ו\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003גיירני על מנת שתשימני כהן גדול. דחפו\u0004 שמאי \u0003באמת הבנין שבידו. בא לפני הלל\u0004 ו\u0003גייריה\u0004 \u0005[גיירו].\u0006","\u0003אמר לו\u0004 הלל לגר: \u0003כלום\u0004 דרך העולם ש\u0003מעמידין מלך אלא מי שיודע טכסיסי מלכות,\u0004 מנהגי המלכות ודרכיה, \u0003לך למוד טכסיסי מלכות,\u0004 ולשם כך עליך לעסוק בתורה תחילה. \u0003הלך וקרא,\u0004 במקרא. \u0003כיון שהגיע\u0004 לפסוק האומר \u0003\"והזר הקרב יומת\"\u0004 (במדבר א, נא) \u0003אמר ליה\u0004 \u0005[לו]\u0006 אותו גר להלל: \u0003מקרא זה על מי נאמר? אמר לו\u0004 הלל: \u0003אפילו על דוד מלך ישראל. נשא אותו גר קל וחומר בעצמו: ומה ישראל שנקראו בנים למקום\u0004 (לה') \u0003ומתוך אהבה שאהבם\u0004 ה' \u0003קרא להם,\u0004 כלומר, אמר אליהם: \u0003\"בני בכרי ישראל\"\u0004 (שמות ד, כב), ובכל זאת \u0003כתיב\u0004 \u0005[נאמר]\u0006 עליהם \u0003\"והזר הקרב יומת\"\u0004 — ה\u0003גר הקל שבא\u0004 בלי זכויות אלא \u0003במקלו ובתרמילו\u0004 בלבד, \u0003על אחת כמה וכמה\u0004 שדינו כן.","\u0003בא\u0004 הגר \u0003לפני שמאי\u0004 ו\u0003אמר לו\u0004 שחוזר הוא בו מדרישתו לעשות אותו כהן גדול, שכן \u0003כלום ראוי אני להיות כהן גדול? והלא כתיב\u0004 \u0005[נאמר]:\u0006 \u0003בתורה \"והזר הקרב יומת\". בא לפני הלל\u0004 ו\u0003אמר לו: ענוותן הלל, ינוחו לך ברכות על ראשך שהקרבתני תחת כנפי השכינה.\u0004 ומסופר: \u0003לימים נזדווגו\u0004 (נזדמנו) \u0003שלשתן,\u0004 אותם שלושה גרים, \u0003במקום אחד,\u0004 ו\u0003אמרו: קפדנותו של שמאי בקשה לטורדנו מן העולם, ענוותנותו של הלל קרבנו תחת כנפי השכינה.\u0004","ומאחר שדובר על נוהג תלמידי החכמים מביאים את מה ש\u0003אמר ריש לקיש: מאי דכתיב\u0004 \u0005[מהי\u0006 משמעות זה \u0005שנאמר]\u0006 \u0003\"והיה אמונת עתיך חסן ישועות חכמת ודעת\u0004 יראת ה' היא אוצרו\u0003\"\u0004 (ישעיהו לג, ו)? \u0003\"אמונת\"\u0004 — \u0003זה סדר זרעים\u0004 במשנה, שמאמין אדם בה' וזורע (ירושלמי). \u0003\"עתיך\"\u0004 — \u0003זה סדר מועד,\u0004 העוסק בעתים ובמועדים השונים בשנה. \u0003\"חסן\"\u0004 — \u0003זה סדר נשים. \" ישועות\"\u0004 — \u0003זה סדר נזיקין,\u0004 שמושיעים את הנרדף מיד רודפו. \u0003\"חכמת\"\u0004 — \u0003זה סדר קדשים. \"ודעת\"\u0004 — \u0003זה סדר טהרות\u0004 שהם קשים ביותר ללמוד. \u0003ואפילו הכי\u0004 \u0005[כך]\u0006 אף אם למד וידע כל אלו, \u0003\"יראת ה' היא אוצרו\",\u0004 שהיא העיקר.","וכעין זה \u0003אמר רבא:\u0004 לאחר שנפטר האדם מהעולם הזה, \u0003בשעה שמכניסין אדם לדין\u0004 על חייו שחי בעולם הזה \u0003אומרים לו\u0004 לפי הסדר שבאותו כתוב: האם \u0003נשאת ונתת באמונה,\u0004 האם \u0003קבעת עתים לתורה,\u0004 האם \u0003עסקת בפריה ורביה,\u0004 האם \u0003צפית לישועה,\u0004 האם \u0003פלפלת בחכמה\u0004 או הבנת \u0003דבר מתוך דבר? ואפילו הכי\u0004 \u0005[כך],\u0006 על כל אלה \u0003אי\u0004 \u0005[אם]\u0006 \u0003יראת ה' היא אוצרו\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 ראוי הדבר, \u0003אי\u0004 \u0005[אם]\u0006 \u0003לא\u0004 — \u0003לא,\u0004 אין כל ההישגים הללו בעלי ערך. \u0003ומשל לאדם שאמר לשלוחו: העלה לי כור חיטין לעלייה,\u0004 לשומרם שם. \u0003הלך\u0004 השליח \u0003והעלה לו. אמר לו\u0004 המשלח: האם \u0003עירבת לי בהן קב חומטון\u0004 (מלח להרחיק את התולעים)? \u0003אמר לו? לאו\u0004 \u0005[לא].\u0006 \u0003אמר לו\u0004 המשלח: אם כן, \u0003מוטב\u0004 היה \u0003אם לא העליתה,\u0004 כי מה תועלת בחטים מתולעות? וכן תורה ומצוות בלא יראת שמים אין להן ערך.","בדרך אגב מזכירים כאן את ההלכה ש\u0003תנא דבי\u0004 \u0005[שנה\u0006 התנא \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל: מערב אדם\u0004 המוכר חיטים לכתחילה \u0003קב חומטון ב\u0004תוך \u0003כור של תבואה, ואינו חושש\u0004 לגזל כשמוכר את הכל בדמי חיטה, מפני שקב החומטין חשוב לשימורה של החיטה.","ועוד בענין זה, אמר \u0003רבה בר רב הונא: כל אדם שיש בו תורה ו\u0004אולם \u0003אין בו\u0004"],["\u0003יראת שמים,\u0004 הריהו \u0003דומה לגזבר שמסרו לו מפתחות הפנימיות\u0004 של אוצר \u0003ו\u0004את ה\u0003מפתחות החיצונות לא מסרו לו, בהי עייל\u0004 \u0005[באיזה יכנס]?\u0006 שאמנם התורה היא מפתח פנימי, אך בלא יראת שמים אין להגיע לתורה אמיתית. בדומה לכך, היה \u0003מכריז ר' ינאי: חבל על\u0004 מי \u0003דלית ליה דרתא ותרעא לדרתא עביד\u0004 \u0005[שאין לו חצר ועושה שער לחצר],\u0006 שאין בו יראת שמים ובכל זאת הוא עוסק בתורה. וכן \u0003אמר רב יהודה: לא ברא הקדוש ברוך הוא את עולמו אלא כדי שייראו מלפניו,\u0004 וכפי \u0003שנאמר: \"והאלהים עשה שיראו מלפניו\"\u0004 (קהלת ג, יד).","ומסופר עוד כי \u0003ר' סימון ור' אלעזר הוו יתבי\u0004 \u0005[היו יושבים].\u0006 \u0003חליף ואזיל\u0004 \u0005[חלף ועבר]\u0006 \u0003ר' יעקב בר אחא\u0004 סמוך להם. \u0003אמר ליה חד לחבריה\u0004 \u0005[אחד לחבירו]:\u0006 \u0003ניקו מקמיה דגבר דחיל חטאין\u0004 \u0005[נעמוד מלפניו שאדם ירא חטא]\u0006 \u0003הוא. אמר ליה אידך\u0004 \u0005[לו השני]\u0006 לחבירו: \u0003ניקו מקמיה דגבר בר אוריין\u0004 \u0005[נעמוד מלפניו שאדם בן תורה]\u0006 \u0003הוא. אמר ליה: אמינא\u0004 \u0005[אומר]\u0006 \u0003לך אנא\u0004 \u0005[אני]\u0006 \u0003דגבר דחיל חטאין\u0004 \u0005[שאדם ירא חטא]\u0006 \u0003הוא, ואמרת\u0004 \u0005[ואומר]\u0006 \u0003לי את\u0004 \u0005[אתה]\u0006 כי \u0003בר אוריין\u0004 \u0005[בן תורה]\u0006 \u0003הוא?!\u0004 והרי השבח הראשון גדול בהרבה מן האחרון.","ומעירים: \u0003תסתיים\u0004 \u0005[תוגדר,\u0006 יוחלט\u0005]\u0006 כי \u0003ר' אלעזר הוא\u0004 ש\u0003אמר\u0004 את השבח \u0003דגבר דחיל חטאין\u0004 \u0005[שאדם ירא חטא]\u0006 \u0003הוא,\u0004 שמוצאים אנו במקום אחר את דבריו בשבח היראה. ש\u0003אמר ר' יוחנן משום\u0004 (בשם) \u0003ר' אלעזר: אין לו להקדוש ברוך הוא בעולמו אלא יראת שמים בלבד,\u0004 וכפי \u0003שנאמר: \"ועתה ישראל מה ה' אלהיך שואל מעמך כי אם ליראה\u0004 את ה' אלהיך\u0003\"\u0004 (דברים י, יב). \u0003וכתיב\u0004 \u0005[ו\u0006כן \u0005נאמר]:\u0006 \u0003\"ויאמר לאדם הן יראת ה' היא חכמה\u0004 וסור מרע בינה\u0003\"\u0004 (איוב כח, כח), \u0003שכן בלשון יוני קורין\u0004 (קוראים) \u0003לאחת \"הן\".\u0004 ומכאן שהדבר היחידי שנחשב הוא יראת ה'. ומסכמים: אכן \u0003תסתיים\u0004 \u0005[תוגדר]\u0006 שר' אלעזר הוא שאמר כן.","\u0003דרש רב עולא: מאי דכתיב\u0004 \u0005[מה\u0006 משמעות כתוב זה \u0005שנאמר]\u0006 \u0003\"אל תרשע הרבה\"\u0004 (קהלת ז, יז). ולכאורה הדבר תמוה, שכן מדברי הכתוב משמע כי רק \u0003הרבה הוא\u0004 ש\u0003לא לירשע\u0004 \u0005[ירשע],\u0006 \u0003הא\u0004 \u0005[הרי]\u0006 \u0003מעט לירשע\u0004 \u0005[ירשע]?!\u0006 \u0003אלא\u0004 כך יש להבין את הדבר כעין הפתגם: \u0003מי שאכל שום וריחו נודף\u0004 וכי \u0003יחזור ויאכל\u0004 עוד \u0003שום אחר ויהא\u0004 הלאה \u0003ריחו נודף?!\u0004 לאמור, אם רשעת מעט אל תחשוב שראוי לך להמשיך ולהיות רשע הרבה.","\u0003דרש רבא בר רב עולא: מאי דכתיב\u0004 \u0005[מה\u0006 משמעות כתוב זה \u0005שנאמר]\u0006 \u0003\"כי אין חרצבות למותם ובריא אולם\"\u0004 (תהלים עג, ד) — \u0003אמר הקדוש ברוך הוא:\u0004 וכי \u0003לא דיין לרשעים שאינם חרדין ועצבין\u0004 (על משקל המלה \"חרצובות\") \u0003מיום המיתה, אלא\u0004 עוד זה \u0003שלבם בריא להן כאולם\u0004 ואף אינם חושבים בענין זה. \u0003והיינו\u0004 \u0005[וזהו]\u0006 ש\u0003אמר רבה\u0004 על הכתוב \u0003\"זה דרכם כסל למו\u0004 ואחריהם בפיהם ירצו סלה\u0003\"\u0004 (תהלים מט, יד) — ש\u0003יודעין\u0004 הם ה\u0003רשעים שדרכם\u0004 מוליכה \u0003למיתה,\u0004 מיתת עולם, אלא \u0003שיש להם חלב על כסלם\u0004 (קרבם) ואין הדבר נכנס ללבם. ו\u0003שמא תאמר שכחה היא מהן?\u0004 על כן \u0003תלמוד לומר: \"ואחריהם בפיהם ירצו סלה\"\u0004 (תהלים מט, יד), כלומר, את אחריתם מזכירים הם בפיהם, ואין הדבר נוגע להם.","שנינו במשנה שאם כיבה את הנר בשבת מפני שהיה \u0003חס על הנר\u0004 או על הפתילה — חייב, ור' יוסי פוטר בכל, מלבד המקרה שבו כיבה את הנר כשחס על הפתילה. ושואלים: \u0003ר' יוסי כמאן סבירא ליה\u0004 \u0005[כ\u0006דעת \u0005מי סבור הוא]?\u0006 בהלכות מלאכות הנעשות בשבת מבלי שיהא לעושה צורך בגוף המלאכה עצמה. \u0003אי\u0004 \u0005[אם]\u0006 \u0003כ\u0004שיטת \u0003ר' יהודה סבירא ליה\u0004 \u0005[סבור הוא],\u0006 שלדעתו מלאכה שאינה צריכה לגופה חייב עליה, אם כן \u0003אפילו בהנך נמי ליחייב\u0004 \u0005[באלה גם כן יחייב]!\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003כ\u0004שיטת \u0003ר' שמעון סבירא ליה\u0004 \u0005[סבור הוא],\u0006 שלדעתו העושה בשבת מלאכה שאינה צריכה לגופה פטור, אם כן ב\u0003פתילה נמי ליפטר\u0004 \u0005[גם כן\u0006 לדעתו \u0005ייפטר].\u0006 \u0003אמר עולא: לעולם\u0004 יכול אתה לומר כי ר' יוסי \u0003כ\u0004דעת \u0003ר' יהודה סבירא ליה\u0004 \u0005[סבור הוא],\u0006 \u0003ו\u0004אולם \u0003קסבר\u0004 \u0005[סבור הוא]\u0006 \u0003ר' יוסי\u0004 שכל מלאכה של סתירה הרי כש\u0003סותר על מנת לבנות במקומו הוי\u0004 \u0005[\u0006הריהו \u0005נחשב]\u0006 כ\u0003סותר,\u0004 וחייב משום עושה מלאכה בשבת. ואולם הסותר \u0003על מנת לבנות שלא במקומו\u0004 — \u0003לא הוי\u0004 \u0005[אינו נחשב]\u0006 כעושה מלאכת \u0003סותר,\u0004 אלא מקלקל בלבד — ופטור. ובכל המקרים הללו, כשהוא מכבה את הנר אינו מעונין להשתמש בנר ובשמן הללו על מנת להדליק בהם מחדש, חוץ מן המקרה של כיבוי הפתילה שאז מראה הוא שרצונו להשתמש בפתילה זו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבה:\u0004 סברה זו לא תתכן, שכן \u0003מכדי\u0004 \u0005[הרי]\u0006 את \u0003כל\u0004 ה\u0003מלאכות\u0004 האסורות בשבת \u0003ילפינן להו\u0004 \u0005[לומדים אנו אותן]\u0006 \u0003מ\u0004מלאכת ה\u0003משכן, והתם\u0004 \u0005[שם]\u0006 \u0003סותר על מנת לבנות שלא במקומו הוא,\u0004 שהרי היו מפרקים את המשכן ומעמידים אותו אחר כך במקום אחר! \u0003אמר ליה\u0004 \u0005[לו]\u0006 עולא לרבה: אין זו ראייה, שכן \u0003שאני התם\u0004 \u0005[שונה שם]\u0006 \u0003כיון דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"על פי ה' יחנו\"\u0004 (במדבר ט, כג), ומכיון שזמן ומקום נסיעתם וחנייתם לא נקבעו על פי רצונם אלא על פי ה' הרי זה \u0003כסותר על מנת לבנות במקומו.\u0004 שגם הסתירה וגם הבניה נעשו על פי ציוויו של הקדוש ברוך הוא, ואין בהם קלקול שלא לצורך.","ואילו \u0003ר' יוחנן אמר: לעולם\u0004 יש לפרש שדעת ר' יוסי \u0003כ\u0004דעת \u0003ר' שמעון ו\u0004על השאלה \u0003מאי שנא\u0004 \u0005[במה שונה]\u0006 ה\u0003פתילה?\u0004 יש לענות כמו ש\u0003אמר רב המנונא, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רב אדא בר אהבה: הכא\u0004 \u0005[כאן]\u0006 \u0003בפתילה שצריך להבהבה\u0004 (לחרוך אותה מעט לפני הדלקתה כדי שתבער יפה) \u0003עסקינן\u0004 \u0005[עוסקים אנו]\u0006 \u0003דבההיא\u0004 \u0005[שב\u0006מקרה ההוא] \u0003אפילו ר' שמעון מודי\u0004 \u0005[מודה]\u0006 שכיבוי זה נחשב למלאכה, \u0003דקא מתקן מנא\u0004 \u0005[ש\u0006בכך \u0005הוא מתקן כלי].\u0006 \u0003אמר רבא: דיקא נמי\u0004 \u0005[מדויק גם כן]\u0006 על פי סגנון המשנה, שזהו הפירוש הנכון, \u0003דקתני\u0004 \u0005[ששנינו\u0006 בה\u0005]\u0006 בלשון מסויים, שהמכבה את הפתילה חייב משום \u0003שהוא עושה פחם,\u0004 מרצון, \u0003ולא קתני\u0004 \u0005[ולא נאמר]\u0006 \u0003מפני שנעשית פחם\u0004 מעצמה. ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד ממנה],\u0006 מהמשנה, שכך יש להבין את הדבר.","משנה זו מסיימת את ענין הדלקת הנר בדבר אגדה. \u0003על שלש עבירות נשים\u0004 נענשות ו\u0003מתות בשעת לידתן: על שאינן זהירות ב\u0004שמירת דיני ה\u0003נדה,\u0004 ו\u0003ב\u0004הפרשת \u0003חלה\u0004 מהעיסה, \u0003ובהדלקת הנר\u0004 בשבת.","שואלים: זו שלא היתה זהירה בשמירת דיני \u0003נדה מאי טעמא\u0004 \u0005[מה טעם]\u0006 נענשת היא בשעת לידתה? \u0003אמר ר' יצחק:\u0004 מאחר ש\u0003היא קלקלה\u0004 (חטאה) \u0003בחדרי בטנה, לפיכך תלקה בחדרי בטנה.\u0004 ושואלים: דבר זה \u0003תינח\u0004 \u0005[נוח]\u0006 ומובן בענין \u0003נדה,\u0004 ואולם זו שלא היתה \u0003זהירה בחלה והדלקת הנר מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 אלא יש להסביר \u0003כדדרש ההוא גלילאה עליה\u0004 \u0005[כפי שדרש גלילי אחד לפני]\u0006 \u0003רב חסדא,\u0004 ש\u0003אמר הקדוש ברוך הוא: רביעית דם נתתי בכם\u0004 בשעת יצירה ו\u0003על עסקי דם\u0004 נידה \u0003הזהרתי אתכם.\u0004"],["\u0003\"ראשית\" קראתי אתכם\u0004 (כנאמר: \"קודש ישראל לה' ראשית תבואתה\". ירמיהו ב, ג), \u0003ועל עסקי ראשית\u0004 (\"ראשית עריסותכם חלה תרימו תרומה\". במדבר טו, כ) \u0003הזהרתי אתכם. נשמה שנתתי בכם קרויה \"נר\"\u0004 (\"נר ה' נשמת אדם\". משלי כ, כז), ו\u0003על עסקי נר\u0004 שבת \u0003הזהרתי אתכם; אם אתם מקיימים אותם\u0004 דברים — \u0003מוטב, ואם לאו\u0004 \u0005[לא]\u0006 — \u0003הריני נוטל\u0004 את \u0003נשמתכם.\u0004","ואולם אם כן \u0003מאי שנא\u0004 \u0005[במה שונה,\u0006 מדוע דווקא\u0005]\u0006 \u0003בשעת לידתן\u0004 פוגעת בהן מידת הדין על חוסר זהירות במצוות אלה? כתשובה הביאו חכמים פתגמים עממיים שונים המביעים את הרעיון שבשעת הסכנה נפרעים מאדם על כל חטאיו. \u0003אמר רבא: נפל תורא\u0004 \u0005[השור]\u0006 — \u0003חדד לסכינא\u0004 \u0005[את הסכין]\u0006 לשחוט אותו. \u0003אביי אמר\u0004: \u0003תפיש תירוס אמתא, בחד מחטרא ליהוי\u0004 \u0005[תרבה חוצפת השפחה, במלקות אחת תלקה].\u0006 וכמו כן האשה, כאשר היא כורעת לילד ורבים יסוריה מחמת חטא חוה בעץ הדעת, אז מצרפים להם עוד מה שהיתה צריכה ללקות בשל חטאיה היא. \u0003רב חסדא אמר: שבקיה לרויא, דמנפשיה נפיל\u0004 \u0005[עזוב את השיכור, שמעצמו הוא נופל].\u0006 וכמו כן שעת הלידה שעת סכנה היא, ודיה שאין הקדוש ברוך הוא עוזרה בשעה זו, כדי שתמות. \u0003מר עוקבא אמר: רעיא חגרא ועיזי ריהטן\u0004 \u0005[הרועה חיגר והעיזים רצות],\u0006 ואינו יכול להשיגן, אבל \u0003אבב חוטרא מילי, ואבי דרי חושבנא\u0004 \u0005[ליד הגדר\u0006 הוא אומר \u0005מילים\u0006 קשות, \u0005ובתוך הדיר\u0006 הוא גומר את \u0005החשבון].\u0006 וכמו כן האשה כל הזמן שהיא בבריאות שלמה תולים לה חטאיה ואין עורכים עימה חשבון עליהם, ואולם בהגיע עת לידתה שהיא עת סכנה, אז מזכירים לה חטאיה ובאים עימה חשבון אם ראויה היא לנס. \u0003רב פפא אמר: אבב חנואתא נפישי אחי ומרחמי\u0004 \u0005[על פתח החנויות,\u0006 בזמן עשירות, אז \u0005רבים\u0006 הם \u0005האחים והאוהבים],\u0006 שכולם נעשים אז לאדם המצליח בנכסיו כאחים ואוהבים, ואולם \u0003אבב בזיוני\u0004 \u0005[על פתח הבזיון]\u0006 כאשר מגיע זמן של הפסד ועוני, אז אין \u0003לא אחי\u0004 \u0005[אחים]\u0006 \u0003ולא מרחמי\u0004 \u0005[אוהבים],\u0006 שכולם מתנכרים לו.","ושואלים: \u0003וגברי היכא מיבדקי\u0004 \u0005[והגברים\u0006 היכן הם \u0005נבדקים]?\u0006 כלומר, היכן עומדים הם לדין וחשבון על מעשיהם? \u0003אמר ריש לקיש: בשעה שעוברים על הגשר.\u0004 ותוהים: רק כאשר הם עוברים על ה\u0003גשר ותו לא\u0004 \u0005[ולא עוד]?\u0006 אלא \u0003אימא\u0004 \u0005[אמור]:\u0006 \u0003כעין גשר,\u0004 כל מקום שסכנתו מצויה. מעין זה מספרים: \u0003רב לא עבר במברא דיתיב ביה\u0004 \u0005[היה עובר\u0006 נהר \u0005במעבורת שישב בה]\u0006 \u0003גוי.\u0004 ש\u0003אמר\u0004 לעצמו: \u0003דילמא מיפקיד ליה דינא עליה ומתפיסנא בהדיה\u0004 \u0005[שמא מופקד דין עליו ואתפס איתו]\u0006 בשעת עונשו. ואילו \u0003שמואל לא עבר\u0004 \u0005[היה עובר]\u0006 \u0003אלא במברא דאית\u0004 \u0005[במעבורת שיש]\u0006 \u0003בה גוי,\u0004 ש\u0003אמר: שטנא בתרי אומי לא שליט\u0004 \u0005[השטן בשתי אומות אינו שולט],\u0006 ואת חשבונותיו הוא עושה עם כל עם לחוד.","ואילו \u0003ר' ינאי בדיק ועבר\u0004 \u0005[היה בודק,\u0006 את המעבורת, \u0005ועובר].\u0006 ומעירים כי \u0003ר' ינאי לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005],\u0006 ש\u0003אמר : לעולם אל יעמוד אדם במקום סכנה לומר שעושין לו נס, שמא\u0004 לבסוף \u0003אין עושין לו נס.\u0004 ולא עוד אלא שאף \u0003אם עושין לו נס\u0004 — \u0003מנכין לו\u0004 על ידי כך \u0003מזכיותיו.\u0004 ו\u0003אמר ר' חנין: מאי קראה\u0004 \u0005[מהו הכתוב]\u0006 המרמז על כך? — שאמר יעקב: \u0003\"קטנתי מכל החסדים ומכל האמת\u0004 אשר עשית את עבדך\u0003\"\u0004 (בראשית לב, יא), ומפרש: כיון שהרבית חסדים ואמת עלי, קטנו זכויותי. ומעין זה מסופר ש\u0003ר' זירא ביומא דשותא\u0004 \u0005[ביום של רוח דרומית]\u0006 \u0003לא נפיק לביני דיקלא\u0004 \u0005[היה יוצא\u0006 והולך \u0005בין הדקלים],\u0006 מחשש שמא יפלו עליו.","בדומה לזה \u0003אמר רב יצחק בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהודה: לעולם יבקש אדם רחמים שלא יחלה, ש\u0004כן \u0003אם יחלה\u0004 כבר — \u0003אומרים לו: הבא זכות והפטר,\u0004 ונוח לו לאדם שלא יצטרך להוכיח שזכאי הוא לחיות שמא לא יעלה בידו להוכיח. \u0003אמר מר עוקבא: מאי קראה\u0004 \u0005[מהו הכתוב]\u0006 המרמז על כך? — שנאמר: \u0003\"\u0004כי תבנה בית חדש ועשית מעקה לגגך ולא תשים דמים בביתך \u0003כי יפל הנפל ממנו\"\u0004 (דברים כב, ח), ומפרשו: \u0003ממנו להביא ראיה,\u0004 כלומר, כאשר נופל מישהו ממצבו הקודם, עליו מוטלת חובת הראיה לזכותו לצאת בשלום. \u0003תנא דבי\u0004 \u0005[שנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל:\u0004 פירוש הכתוב \u0003\"כי יפל הנפל ממנו\"\u0004 הוא — אמנם \u0003ממנו ראוי\u0004 היה אדם \u0003זה ליפול\u0004 מאותו גג עוד \u0003מששת ימי בראשית,\u0004 כלומר, מעצם סדר הדברים בעולם, \u0003שהרי\u0004 עדיין \u0003לא נפל, ו\u0004בכל זאת \u0003הכתוב קראו \"נופל\". אלא ש\u0004בכל זאת מאשימים בכך את בעל הבית, כי \u0003מגלגלין זכות על ידי זכאי וחובה על ידי חייב.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מי שחלה ונטה למות, אומרים לו: התודה, שכן כל המומתין\u0004 בידי בית דן \u0003מתודין,\u0004 ואפילו מת בידי שמים טוב שיראה את מיתתו ככפרה על עוונותיו. ואמרו: \u0003אדם יוצא לשוק,\u0004 שיש שם קטטות ומריבות, \u0003יהי דומה בעיניו כמי שנמסר לסרדיוט\u0004 \u0005[לחייל].\u0006 ואם היה \u0003חש בראשו\u0004 — \u0003יהי דומה בעיניו כמי שנתנוהו בקולר\u0004 (חבל שבו קושרים את האסירים). אם \u0003עלה למטה ונפל\u0004 למשכב — \u0003יהי דומה בעיניו כמי שהעלוהו לגרדום\u0004 (למקום המשפט) \u0003לידון, שכל העולה לגרדום לידון אם יש לו פרקליטין גדולים\u0004 — \u0003ניצול, ואם לאו\u0004 \u0005[לאו]\u0006 — \u0003אינו ניצול.\u0004","ולגבי דיני שמים, \u0003אלו הן פרקליטין של אדם: תשובה ומעשים טובים.\u0004 ומעירים: \u0003ואפילו תשע מאות ותשעים ותשעה מלמדים עליו חובה ואחד\u0004 בלבד \u0003מלמד עליו זכות\u0004 — \u0003ניצול,\u0004 וכפי \u0003שנאמר: \"אם יש עליו מלאך מליץ אחד מני אלף להגיד לאדם ישרו. ויחננו ויאמר פדעהו מרדת שחת\u0004 מצאתי כופר\u0003\"\u0004 (איוב לג, כג–כד). \u0003ר' אליעזר בנו של ר' יוסי הגלילי אומר: אפילו\u0004 היו \u0003תשע מאות ותשעים ותשעה\u0004 חלקים \u0003באותו מלאך לחובה ו\u0004חלק \u0003אחד לזכות\u0004 — \u0003ניצול, שנאמר: \"מליץ אחד מני אלף\",\u0004 שאף כאשר במליץ היושר יש רק אחד מני אלף של זכות, גם אז \"ויחוננו ויאמר פדעהו מרדת שחת מצאתי כופר\".","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003על שלש עבירות נשים מתות\u0004 בשעה שהן \u0003יולדות.\u0004 ו\u0003ר' אלעזר\u0004 גורס ו\u0003אומר\u0004 שה\u0003נשים מתות\u0004 כשהן \u0003ילדות\u0004 (צעירות), והן שנימנו במשנה, נדה, חלה והדלקת הנר. \u0003ר' אחא אומר\u0004 שהוא \u0003בעון\u0004 שהן \u0003מכבסות צואת בניהם בשבת. ויש אומרים: על שקורין\u0004 (קוראים) \u0003לארון הקודש \"ארנא\"\u0004 \u0005[\"ארון\"]\u0006 סתם.","ובדומה לכך \u0003תניא\u0004 \u0005[שנינו\u0006 בברייתא\u0005]\u0006 ש\u0003ר' ישמעאל בן אלעזר אומר: בעון שני דברים עמי הארצות מתים\u0004 כשהם צעירים (יעב\"ץ): \u0003על שקורין לארון הקודש \"ארנא\"\u0004 \u0005[\"ארון\"]\u0006 סתם, \u0003ועל שקורין לבית הכנסת \"בית עם\". תניא\u0004 \u0005[שנינו\u0006 בברייתא\u0005]\u0006 ש\u0003ר' יוסי אומר: שלשה בדקי מיתה\u0004 (סדקי, מקומות רופפים) \u0003נבראו באשה, ואמרי לה\u0004 \u0005[ויש אומרים]:\u0006 \u0003שלשה דבקי מיתה\u0004 (דברים המדביקים, המקרבים את המיתה), והם: \u0003נדה וחלה והדלקת הנר.\u0004 ומסבירים כי גירסה \u0003חדא\u0004 \u0005[אחת]\u0006 היא \u0003כר' אלעזר\u0004 שאמר שנשים מתות ילדות והוא \"דבקי מיתה\". \u0003וחדא\u0004 \u0005[ואחת,\u0006 האחרת\u0005]\u0006 \u0003כרבנן\u0004 \u0005[כ\u0006דברי \u0005חכמים],\u0006 שאמרו שנשים מתות כשהן יולדות, והוא \"בדקי מיתה\".","ובדומה לכך \u0003תניא\u0004 \u0005[שנינו\u0006 בברייתא\u0005]\u0006 ש\u0003ר' שמעון בן גמליאל אומר: הלכות הקדש, תרומות ומעשרות הן הן גופי תורה,\u0004 וחמורים הם ביותר"],["\u0003ונמסרו\u0004 בין השאר גם \u0003לעמי הארץ.\u0004 ולעתים כשמתרשלים הם בכך — נענשים הם בשל כך.","\u0003תניא\u0004 \u0005[שנינו\u0006 בברייתא] ש\u0003ר' נתן אומר: בעון נדרים\u0004 שנודר אדם ואינו משלם \u0003מתה אשה של אדם.\u0004 ורמז לדבר ממה \u0003שנאמר: \"אם אין לך לשלם למה יקח משכבך מתחתיך\"\u0004 (משלי כב, כז). \u0003רבי אומר: בעון נדרים\u0004 של שוא \u0003בנים מתים כשהן קטנים, שנאמר: \"\u0004טוב אשר לא תדור משתדור ולא תשלם. \u0003אל תתן את פיך לחטיא את בשרך ואל תאמר לפני המלאך כי שגגה היא למה יקצף האלהים על קולך וחבל את מעשה ידיך\"\u0004 (קהלת ה, ד–ה). ו\u0003איזה הן מעשה ידיו של אדם? הוי אומר בניו ובנותיו של אדם.\u0004","לשם ברור השאלה בעוון מה מתים ילדים קטנים מביאים את מה ש\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא בענין זה: \u0003בעון נדרים בנים מתים,\u0004 אלו \u0003דברי ר' אלעזר בר' שמעון. ר' יהודה הנשיא אומר: בעון ביטול תורה.\u0004 ושואלים: \u0003בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006דעת \u0005מי שאומר]\u0006 שהבנים מתים \u0003בעון נדרים\u0004 — הרי זה \u0003כדאמרן\u0004 \u0005[כפי שאמרנו]\u0006 קודם, \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 כי הבנים מתים \u0003בעון ביטול תורה מאי קראה\u0004 \u0005[מהו הכתוב]\u0006 המסייע לכך? ומשיבים: \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"לשוא הכיתי את בניכם מוסר לא לקחו\"\u0004 (ירמיה ב, ל), שיש לפרשו שהבנים מתים משום שהאבות אינם לוקחים (לומדים) את המוסר, התורה. \u0003רב נחמן בר יצחק אמר: למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 כי הבנים מתים \u0003בעון נדרים נמי מהכא\u0004 \u0005[גם כן מכאן]\u0006 מקור לדבריו, ומפרש: \u0003\"לשוא הכיתי את בניכם\"\u0004 — \u0003על עסקי שוא,\u0004 שנודרים נדר ואין משלמים אותו. ושואלים: \u0003מכדי\u0004 \u0005[הרי]\u0006 \u0003ר' יהודה הנשיא היינו\u0004 \u0005[הוא הוא]\u0006 \u0003רבי, ו\u0004הרי שנינו בתוספתא ש\u0003רבי בעון נדרים קאמר\u0004 \u0005[אמר]\u0006 שהבנים מתים, ואיך אתה אומר בשם ר' יהודה הנשיא שהוא משום עוון ביטול תורה?! ומשיבים: \u0003בתר\u0004 \u0005[אחר]\u0006 ש\u0003שמעה\u0004 לסברה זו \u0003מר' אלעזר בר' שמעון\u0004 חזר לשנות כדבריו.","בנושא זה עצמו \u0003פליגי\u0004 \u0005[חלוקים]\u0006 \u0003בה ר' חייא בר אבא ור' יוסי, חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר\u0004 שהבנים מתים \u0003בעון מזוזה. וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר\u0004 ש\u0003בעון ביטול תורה\u0004 הבנים מתים. \u0003למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 שהבנים מתים \u0003בעון מזוזה,\u0004 הרי זה משום שלדעתו עיקרון פרשני הוא ש\u0003מקרא נדרש לפניו ולא לפני פניו.\u0004 שפסוק זה יש ליחסו רק לפסוק הקודם לו (לפניו), ולא לפסוקים הקודמים אף לזה (לפני פניו). ולעניננו, נאמר \"למען ירבו ימיכם וימי בניכם\" (דברים יא, כא), וקודם לכן נאמר \"וכתבתם על מזוזות ביתך ובשעריך\" (דברים יא, כ). \u0003ולמאן דאמר\u0004 \u0005[ול\u0006דעת \u0005מי שאומר]\u0006 כי הבנים מתים \u0003בעון ביטול תורה\u0004 הרי זה משום שלדעתו עיקרון פרשני הוא ש\u0003מקרא נדרש לפניו ולפני פניו,\u0004 שלדעתו ברכת אריכות הימים קשורה גם לפסוק הקודם לקודם \"ולמדתם אותם את בניכם לדבר בם\" (דברים יא, יט).","ובאותו ענין, \u0003פליגי\u0004 \u0005[חלוקים]\u0006 \u0003בה\u0004 בענין זה גם התנאים \u0003ר' מאיר ור' יהודה. חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר\u0004 שהבנים מתים \u0003בעון מזוזה, וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר\u0004 שהבנים מתים \u0003בעון ציצית.\u0004 ושואלים: \u0003בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006שיטת \u0005מי שאומר]\u0006 שהבנים מתים \u0003בעון מזוזה\u0004 הרי זה מתוך הסתמכות על קשר הכתובים, \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"וכתבתם על מזוזות ביתך\u0004 ובשעריך \u0003\", וכתיב בתריה\u0004 \u0005[ונאמר אחריו]:\u0006 \u0003\"למען ירבו ימיכם וימי בניכם\". אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 שהבנים מתים \u0003בעון ציצית מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? מה הקשר בין הדברים? \u0003אמר רב כהנא, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003שילא מרי:\u0004 הדבר נדרש ממה \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"גם בכנפיך נמצאו דם נפשות אביונים נקיים\"\u0004 (ירמיה ב, לד), משום שאינם שמים ציצית על כנפות הבגד מתים \"אביונים נקיים\" — הילדים הקטנים שאין בהם חטא. \u0003רב נחמן בר יצחק אמר: למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 כי הבנים מתים \u0003בעון מזוזה נמי מהכא\u0004 \u0005[גם כאן מכאן]\u0006 הוא מביא ראיה, \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"לא במחתרת מצאתים\u0004 כי על כל אלה \u0003\",\u0004 הרי שעונש זה בא על \u0003שעשו פתחים כמחתרת\u0004 של גנבים ולא שמו בפתחיהם מזוזות.","ומאחר שדובר בחשיבות מצוות ציצית מביאים את מה ש\u0003אמר ריש לקיש: כל הזהיר בציצית זוכה\u0004 לעתיד לבוא \u0003ומשמשין לו שני אלפים ושמונה מאות עבדים.\u0004 ורמז לדבר ממה \u0003שנאמר: \"כה אמר ה' צבאות בימים ההמה אשר יחזיקו עשרה אנשים מכל לשנות הגוים והחזיקו בכנף איש יהודי לאמר נלכה עמכם\u0004 כי שמענו אלהים עמכם\u0003\"\u0004 (זכריה ח, כג), ומפרשו: שבכל כנף של אדם מישראל שציצית מצויה בה יחזיקו עשרה אנשים מכל שבעים האומות, הרי שבע מאות איש לכל כנף, ובסך הכל אלפים ושמונה מאות איש.","עם הדברים הללו מוסיפים להביא מדברי חכמים על עונשים הבאים על עבירות שונות. ו\u0003סימן\u0004 יש לכל המימרות, והוא: \u0003שנא חלה תרומה נגזלת דינא שבועה שיפוכתא גילויא ונבלותא. תניא\u0004 \u0005[שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' נחמיה אומר: בעון שנאת חנם\u0004 ששונא אדם את חבירו נענש הוא ש\u0003מריבה רבה בתוך ביתו של אדם, ואשתו מפלת נפלים, ובניו ובנותיו של אדם מתים כשהן קטנים. ר' אלעזר בר' יהודה אומר: בעון\u0004 שאין מפרישים \u0003חלה\u0004 מן העיסה \u0003אין ברכה במכונס\u0004 (במחסני התבואה), \u0003ומארה\u0004 (קללה) \u0003משתלחת בשערים,\u0004 שעולים מחירי היבולים, \u0003וזורעין זרעים ואחרים אוכלין\u0004 מן התבואה, \u0003שנאמר: \"אף אני אעשה זאת לכם והפקדתי עליכם בהלה את השחפת ואת הקדחת מכלות עינים ומדיבת נפש וזרעתם לריק זרעכם ואכלהו אויביכם\"\u0004 (ויקרא כו, טז). ו\u0003אל תקרי\u0004 \u0005[תקרא]\u0006 \u0003\"בהלה\" אלא \"בחלה\",\u0004 שבשל אי הפרשת חלה באים כל העונשים הללו. \u0003ואם נותנין\u0004 חלה — \u0003מתברכין, שנאמר: \"וראשית עריסותיכם תתנו לכהן להניח ברכה אל ביתך\"\u0004 (יחזקאל מד, ל).","ועוד אמרו: \u0003בעון ביטול תרומות ומעשרות שמים נעצרין מלהוריד טל ומטר, והיוקר הוה\u0004 (נעשה), \u0003והשכר אבד, ובני אדם רצין אחר פרנסתן ואין מגיעין\u0004 (משיגים) אותה, \u0003שנאמר: \"ציה גם חום יגזלו מימי שלג שאול חטאו\"\u0004 (איוב כד, יט). ושואלים: \u0003מאי משמע\u0004 \u0005[מה המשמעות],\u0006 כלומר, כיצד נלמד רעיון זה מדברי הכתוב? \u0003תנא דבי\u0004 \u0005[שנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל,\u0004 יש לפרש כך: \u0003בשביל דברים שצויתי אתכם בימות החמה\u0004 (להפריש תרומות ומעשרות מתבואות הקיץ) \u0003ולא עשיתם, יגזלו מכם מימי שלג בימות הגשמים. ואם נותנין\u0004 תרומות ומעשרות — \u0003מתברכין, שנאמר: \"הביאו את כל המעשר אל בית האוצר ויהי טרף בביתי ובחנוני נא בזאת אמר ה' צבאות אם לא אפתח לכם את ארובות השמים והריקתי לכם ברכה עד בלי די\"\u0004 (מלאכי ג, י). ואגב שואלים \u0003מאי\u0004 \u0005[מה]\u0006 משמעות המילים \u0003\"עד בלי די \"? אמר רמי בר רב אמר רב:\u0004 הכוונה היא שירבה כל כך השפע \u0003עד שיבלו\u0004 (\"בלי\") \u0003שפתותיכם מלומר \"די\".\u0004","ועוד אמרו: \u0003בעון גזל הגובאי\u0004 (הארבה) \u0003עולה, והרעב הווה, ובני אדם אוכלים בשר בניהן ובנותיהן,\u0004 וכפי \u0003שנאמר: \"שמעו הדבר הזה פרות הבשן אשר בהר שמרון העשקות דלים הרצצות אביונים\u0004 האומרות לאדוניהן הביאה ונשתה\u0003\"\u0004 (עמוס ד, א), ואחרי כן נאמר: \"וגם אני נתתי לכם נקיון שיניים בכל עריכם וחוסר לחם בכל מקומותיכם\" (עמוס ד, ו) — הרי רעב. \u0003אמר רבא:\u0004 פרות הבשן אלו הרי הן \u0003כגון הני\u0004 \u0005[אותן]\u0006 \u0003נשי\u0004 העיר \u0003מחוזא\u0004"],["\u0003דאכלן ולא עבדן\u0004 \u0005[האוכלות ואינן עושות]\u0006 דבר לפרנסתן, וגורמות בכך לבעליהן לחטוא בגזל. \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"הכיתי אתכם בשדפון ובירקון הרבות גנותיכם וכרמיכם ותאניכם וזיתיכם יאכל הגזם\"\u0004 (עמוס ד, ט), \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"יתר הגזם אכל הארבה ויתר הארבה אכל הילק ויתר הילק אכל החסיל\"\u0004 (יואל א, ד). \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"ויגזר על ימין ורעב ויאכל על שמאל ולא שבעו איש בשר זרעו יאכלו\"\u0004 (ישעיהו ט, יט), \u0003אל תקרי\u0004 \u0005[תקרא]\u0006 \u0003\"בשר זרועו\" אלא \"בשר זרעו \".\u0004 הרי שנתפרשו במקרא אותם דברים שאמרו כעונש על הגזל.","ועוד אמרו כי \u0003בעון עינוי הדין\u0004 שמשהים הדיינים את פסק הדין בשל חישובים משלהם, \u0003ו\u0004בשל \u0003עיוות הדין\u0004 שמעוותים בזדון, \u0003ו\u0004בשל \u0003קלקול הדין\u0004 שנעשה מתוך רשלנות \u0003ו\u0004בשל \u0003ביטול תורה\u0004 — \u0003חרב וביזה רבה\u0004 בעולם, \u0003ודבר ובצורת בא, ובני אדם אוכלין ואינן שבעין ואוכלין לחמם במשקל. דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"והבאתי עליכם חרב נקמת נקם ברית\u0004 ונאספתם אל עריכם ושילחתי דבר בתוככם וניתתם ביד אויב\u0003\"\u0004 (ויקרא כו, כה), \u0003ואין\u0004 משמעות \u0003לשון \"ברית\" אלא תורה, שנאמר: \"אם לא בריתי יומם ולילה\u0004 חוקות שמים וארץ לא שמתי\u0003\"\u0004 (ירמיהו לג, כה), והתורה היא המצווה הנוהגת גם ביום וגם בלילה. \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 עוד בעונש זה: \u0003\"בשברי לכם מטה לחם ואפו עשר נשים\u0004 לחמכם בתנור אחד והשיבו לחמכם במשקל ואכלתם ולא תשבעו\u0003\"\u0004 (ויקרא כו, כו). ונאמר: \u0003\"יען וביען במשפטי מאסו\u0004 ואת חקותי געלה נפשם\u0003\"\u0004 (ויקרא כו, מג), הרי שכל העונשים הללו באים בשל פגם בברית התורה, ובשל קלקול במשפט.","ועוד אמרו: \u0003בעון שבועת שוא\u0004 (שנשבע שלא לצורך) \u0003ושבועת שקר וחילול שבת וחילול השם\u0004 — \u0003חיה רעה רבה\u0004 בעולם, \u0003ובהמה כלה, ובני אדם מתמעטין, והדרכים משתוממין\u0004 (נעשים שממה). \u0003שנאמר: \"ואם באלה לא תוסרו לי\u0004 והלכתם עמי קרי\u0003\"\u0004 (ויקרא כו, כג), \u0003אל תקרי\u0004 \u0005[תקרא]\u0006 \u0003\"באלה\" אלא \"באלה\"\u0004 (בשל שבועת שקר). \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 כי העונש על כך הוא \u0003\"והשלחתי בכם את חית השדה\u0004 ושיכלה אתכם והכריתה את בהמתכם והמעיטה אתכם ונשמו דרכיכם\u0003\"\u0004 (ויקרא כו, כב) \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 \u0003בשבועת שקר: \"ולא תשבעו בשמי לשקר וחללת את שם אלהיך\u0004 אני ה'\u0003\"\u0004 (ויקרא יט, יב). \u0003ובחלול השם כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"ולא תחללו את שם קדשי\"\u0004 (ויקרא כב, לב). \u0003ובחלול שבת כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"מחלליה מות יומת\"\u0004 (שמות לא, יד), \u0003ויליף\u0004 \u0005[ולומד]\u0006 בגזירה שווה \u0003\"חילול\" \"חילול\" משבועת שקר,\u0004 שכשם שהעונש על שבועת שקר הוא שממה והתרבות החיות הרעות, כן גם עונש חילול השבת וחילול השם.","ועוד אמרו: \u0003בעון שפיכות דמים בית המקדש חרב, ושכינה מסתלקת מישראל, שנאמר: \"ולא תחניפו\u0004 את הארץ אשר אתם בה כי הדם הוא יחניף את הארץ ולארץ לא יכופר לדם אשר שפך בה כי אם בדם שופכו. \u0003ולא תטמא את הארץ אשר אתם ישבים בה אשר אני שכן בתוכה\u0004 כי אני ה' שוכן בתוך בני ישראל\u0003\"\u0004 (במדבר לה, לג–לד). ואולם \u0003הא\u0004 \u0005[הרי]\u0006 כש\u0003אתם מטמאים אותה,\u0004 את הארץ — \u0003אינכם יושבים בה ואיני שוכן בתוכה.\u0004","\u0003בעון גלוי עריות ועבודה זרה ו\u0004אי \u0003השמטת\u0004 הארץ ב\u0003שמיטין ויובלות\u0004 — \u0003גלות בא לעולם, ומגלין אותן,\u0004 את ישראל מארצם, \u0003ובאין אחרים ויושבין במקומן. שנאמר\u0004 לגבי עבודה זרה וגילוי עריות: \u0003\"כי את כל התועבות האל עשו אנשי הארץ\u0004 אשר לפניכם ותטמא הארץ. ולא תקיא הארץ אתכם בטמאכם אותה כאשר קאה את הגוי אשר לפניכם\u0003\"\u0004 (ויקרא יח, כז–כח). \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 עוד \u0003\"ותטמא הארץ ואפקד עונה עליה\u0004 ותקיא הארץ את יושביה\u0003\"\u0004 (ויקרא יח, כה). \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 עוד: \u0003\"ולא תקיא הארץ אתכם בטמאכם אותה\u0004 כאשר קאה את הגוי אשר לפניכם\".","\u0003ובעבודה זרה כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"ונתתי את פגריכם\u0004 על פגרי גלוליכם\" (ויקרא, כו, ל). \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"והשמותי את מקדשיכם\u0004 ולא אריח בריח ניחוחכם\u0003\"\u0004 (ויקרא כו, לא). ונאמר עוד: \u0003\"ואתכם אזרה בגוים\u0004 והריקותי אחריכם חרב והיתה ארצכם שממה ועריכם יהיו חרבה\" (ויקרא כו, לג).","ובעוון זלזול \u0003בשמיטין וביובלות כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"אז תרצה הארץ את שבתתיה כל ימי השמה ואתם בארץ אויביכם\u0004 אז תשבת הארץ והרצת את שבתותיה. \u0003כל ימי השמה\u0004 תשבות את אשר לא שבתה בשבתותיכם בשבתכם עליה\u0003\"\u0004 (ויקרא לד, לה).","\u0003בעון נבלות\u0004 (ניבול) \u0003פה צרות רבות, וגזירות קשות מתחדשות, ובחורי שונאי ישראל\u0004 (לשון נקייה על ישראל) \u0003מתים, יתומים ואלמנות צועקין ואינן נענין, שנאמר: \"על כן על בחוריו לא ישמח ה' ואת יתמיו ואת אלמנתיו לא ירחם כי כלו חנף ומרע וכל פה דבר נבלה בכל זאת לא שב אפו ועוד ידו נטויה\"\u0004 (ישעיה ט, טז).","ומסבירים \u0003מאי\u0004 \u0005[מה]\u0006 משמעות הלשון \u0003\"ועוד ידו נטויה\"\u0004 — \u0003אמר רב חנן בר רבא: הכל יודעין כלה למה נכנסה לחופה\u0004 ואין בדבר משום גילוי דברים שאינם ידועים. \u0003אלא\u0004 אף על פי כן \u0003כל המנבל פיו\u0004 בכך \u0003אפילו חותמין עליו גזר דין של שבעים שנה לטובה\u0004 — \u0003הופכין עליו\u0004 אותו \u0003לרעה\u0004 בגלל עוון זה. ו\u0003אמר רבא בר שילא אמר רב חסדא: כל המנבל את פיו\u0004 — \u0003מעמיקין לו גיהנם, שנאמר: \"שוחה עמקה פי זרות\u0004 זעום ה' יפל שם\u0003\"\u0004 (משלי כב, יד), שהמנבל פיו (\"פי זרות\") מעמיקים לו את השוחה בגיהנום. \u0003רב נחמן בר יצחק אמר: אף\u0004 ה\u0003שומע\u0004 ניבול פה \u0003ושותק\u0004 נענש בכך. \u0003שנאמר: \"זעום ה' יפל שם\",\u0004 אפילו אם הוא עצמו אינו מדבר כלל.","ומעין זה \u0003אמר רב אושעיא: כל הממרק\u0004 (מכין) \u0003עצמו לעבירה\u0004 — \u0003חבורות ופצעין יוצאים בו. שנאמר: \"חברות פצע תמרוק ברע\u0004 ומכות חדרי בטן\u0003\"\u0004 (משלי כ, ל). \u0003ולא עוד אלא ש\u0004הוא \u0003נדון ב\u0004מחלת \u0003הדרוקן\u0004 (מחלת מעיים), שנאמר: \u0003\"ומכות חדרי בטן\".\u0004 וכן \u0003אמר רב נחמן בר יצחק: סימן\u0004 למי שעבר \u0003עבירה\u0004 — מחלת \u0003הדרוקן.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003שלשה מיני הדרוקן הן:\u0004 זה שבא כעונש על \u0003עבירה\u0004 הוא \u0003עבה, ו\u0004הידרוקן \u0003של\u0004 (הבא מתוך) \u0003רעב\u0004 הוא \u0003תפוח\u0004 (נפוח), אבל אינו עבה ממש. \u0003ו\u0004הידרוקן \u0003של כשפים\u0004 הוא \u0003דק,\u0004 שבשרו של החולה נעשה רזה בשאר המקומות.","מסופר: \u0003שמואל הקטן חש ביה\u0004 \u0005[חלה בו],\u0006 בהידרוקן. \u0003אמר: רבונו של עולם, מי מפיס?\u0004 כלומר, מי יוכל להבחין שהידרוקן זה לא בא מחמת עבירה? ואכן, \u0003איתסי\u0004 \u0005[התרפא].\u0006 אף \u0003אביי חש ביה\u0004 \u0005[חלה בו],\u0006 בהידרוקן. העיד ו\u0003אמר\u0004 עליו \u0003רבא: ידענא ביה\u0004 \u0005[יודע אני בו]\u0006 \u0003בנחמני\u0004 (אביי) \u0003דמכפין נפשיה\u0004 \u0005[ש\u0006הוא \u0005מרעיב את עצמו],\u0006 והידרוקן שלו מחמת רעב היה. ומסופר עוד: ש\u0003רבא חש ביה\u0004 \u0005[חלה בו],\u0006 ושאלו: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רבא\u0004 לא היה מרעיב עצמו, ואף בעבירה אין לחשוד בו, ואם לומר שמחמת שלא עשה צרכיו בזמן חש בהידרוקן, והלא רבא ידע על כך, ו\u0003הוא\u0004 ש\u0003אמר : נפישי קטילי קדר מנפיחי כפן\u0004 \u0005[מרובים הרוגי\u0006 קדירה, שאינם נזהרים בעשיית צרכיהם, \u0005מנפוחי רעב].\u0006 ומשיבים: \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003רבא דאנסי ליה רבנן בעידניה בעל כורחיה\u0004 \u0005[שאונסין אותו החכמים\u0006 להשאר במקומו \u0005בשעת דרשתו בעל כורחו],\u0006 ומאחר שאינו יכול להיפנות — חלה בהידרוקן.","אגב כך מביאים מה ש\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003ארבעה סימנין הן: סימן לעבירה\u0004 — \u0003הדרוקן, סימן לשנאת חנם\u0004 — \u0003ירקון, סימן לגסות הרוח\u0004 — \u0003עניות,\u0004 ו\u0003סימן ללשון הרע\u0004 — \u0003אסכרה.\u0004","בענין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אסכרה באה לעולם\u0004 כעונש"],["\u0003על\u0004 ביטול \u0003המעשר. ר' אלעזר בר' יוסי אומר:\u0004 אסכרה באה כעונש \u0003על לשון הרע. אמר רבא ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003ר' יהושע בן לוי: מאי קראה\u0004 \u0005[מהו הכתוב]\u0006 המרמז על כך — \u0003\"והמלך ישמח באלהים יתהלל כל הנשבע בו כי יסכר פי דוברי שקר\"\u0004 (תהלים סג, יב), הרי שעונש דיבור השקר הוא סכירת הפה — אסכרה הפוגעת בין השאר גם בפה.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם],\u0006 לבני בית המדרש שאלה זו: האם \u0003ר' אלעזר בר' יוסי\u0004 שאסכרה היא עונש \u0003על לשון הרע\u0004 בלבד \u0003קאמר\u0004 \u0005[אמר],\u0006 \u0003או דילמא\u0004 \u0005[שמא]\u0006 \u0003אף על לשון הרע נמי קאמר\u0004 \u0005[גם כן אמר]?\u0006 \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לשאלה זו ממה ששנינו בברייתא: \u0003כשנכנסו רבותינו לכרם ביבנה היו שם ר' יהודה ור' אלעזר בר' יוסי ור' שמעון\u0004 ו\u0003נשאלה שאלה זו בפניהם: מכה זו\u0004 של אסכרה, \u0003מפני מה מתחלת בבני מעיים וגומרת בפה? נענה ר' יהודה בר' אלעאי \"ראש המדברים בכל מקום \" ואמר: אף על פי שכליות יועצות, ולב מבין, ולשון מחתך\u0004 את המילים, בכל זאת ה\u0003פה\u0004 הוא \u0003גומר\u0004 ומוציאן, ולכן מתחילה המחלה במקום שהתחילה לשון הרע, ומסיימת בפה. \u0003נענה ר' אלעזר בר' יוסי ואמר:\u0004 מחלה זו גומרת בפה \u0003מפני שאוכלין בה דברים טמאים.\u0004 ומיד תוהים על כך: \u0003דברים טמאים סלקא דעתך\u0004 \u0005[עולה על דעתך]\u0006 לומר? וכי מרובים כל כך האוכלים דברים טמאים? \u0003אלא\u0004 שהיא עונש על \u0003שאוכלין בה דברים שאינן מתוקנים\u0004 שלא הופרשו המעשרות מהם. \u0003נענה ר' שמעון ואמר:\u0004 מחלה זו באה כעונש על \u0003עון ביטול תורה.\u0004","\u0003אמרו לו: נשים יוכיחו\u0004 שאינן חייבות בתלמוד תורה ובכל זאת חולות הן באסכרה! ענה להם: הן נענשות על \u0003שמבטלות את בעליהן\u0004 מתלמוד תורה. אמרו לו: \u0003גוים יוכיחו\u0004 שאף הם חולים באסכרה אף שאינם חייבים בלימוד התורה! ענה להם: אף הם נענשים מפני \u0003שמבטלין את ישראל\u0004 מלימוד התורה. אמרו לו: \u0003תינוקות\u0004 קטנים \u0003יוכיחו\u0004 שאינם חייבים כלל בתלמוד תורה, וחולים באסכרה! ענה להם: אף הם נענשים מפני \u0003שמבטלין את אביהן\u0004 מתלמוד תורה. אמרו לו: \u0003תינוקות של בית רבן יוכיחו\u0004 שהם עוסקים בתורה ואף על פי כן חולים באסכרה.","ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 יש להבין את הדבר \u0003כ\u0004דברי \u0003ר' גוריון,\u0004 ש\u0003אמר ר' גוריון, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רב יוסף בר' שמעיה: בזמן שהצדיקים\u0004 מצויים \u0003בדור,\u0004 ה\u0003צדיקים נתפסים\u0004 ומתים או מתייסרים על, כלומר, בעוון \u0003הדור,\u0004 ואם \u0003אין צדיקים בדור\u0004 — \u0003תינוקות של בית רבן\u0004 שאף הם נקיים מחטא \u0003נתפסים על הדור. אמר ר' יצחק בר זעירי, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 ש\u0003אמר\u0004 זאת \u0003ר' שמעון בן נזירא: מאי קראה\u0004 \u0005[מהו הכתוב]\u0006 המרמז על כך — \u0003\"אם לא תדעי לך היפה בנשים צאי לך בעקבי הצאן\u0004 ורעי את גדיותיך על משכנות הרועים\u0003\"\u0004 (שיר השירים א, ח), \u0003ואמרינן\u0004 \u0005[ואומרים אנו]\u0006 בפירושו: שהם ה\u0003גדיים הממושכנין\u0004 (\"משכנות\") \u0003על הרועים.\u0004 שאם רועי הדור ומנהיגיו מחטיאים את הרבים, מתים הילדים הקטנים בעוונם. ולענין השאלה \u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 שכוונת ר' אלעזר בר' יוסי היא שמכת האסכרה היא \u0003אף על לשון הרע נמי קאמר\u0004 \u0005[גם כן אמר],\u0006 שהרי בברייתא זו נותן הוא גם טעם אחר. ומעירים: אכן \u0003שמע מינה\u0004 \u0005[למד ממנה].\u0006","בתוך הברייתא הוזכר כעין תואר לר' יהודה \"ראש המדברים בכל מקום\" ושואלים: \u0003ואמאי קרו ליה\u0004 \u0005[ומדוע קראו לו]\u0006 \u0003\"ראש המדברים בכל מקום \"?\u0004 ומספרים כי הדבר אירע בשל מעשה שהיה. \u0003דיתבי\u0004 \u0005[שישבו]\u0006 \u0003ר' יהודה ור' יוסי ור' שמעון, ויתיב\u0004 \u0005[וישב]\u0006 \u0003יהודה בן גרים גבייהו\u0004 \u0005[לידם].\u0006 \u0003פתח ר' יהודה ואמר: כמה נאים מעשיהן של אומה זו\u0004 הרומאים, שהרי רואים שהם \u0003תקנו שווקים, תקנו גשרים, תקנו מרחצאות. ר' יוסי שתק. נענה ר' שמעון בן יוחאי ואמר: כל מה שתקנו לא תקנו אלא לצורך עצמן. תקנו שווקין\u0004 כדי \u0003להושיב בהן זונות, מרחצאות\u0004 — \u0003לעדן בהן\u0004 את \u0003עצמן,\u0004 ו\u0003גשרים\u0004 — \u0003ליטול מהן מכס\u0004 מכל עובר גשר. \u0003הלך יהודה בן גרים וסיפר דבריהם\u0004 בביתו, \u0003ו\u0004כך התגלגלו הדברים עד ש\u0003נשמעו למלכות.\u0004 ופסקו: \u0003יהודה שעילה\u0004 את השלטון הרומאי \u0003יתעלה\u0004 ויתמנה מנהיג החכמים (\"ראש המדברים\"). \u0003יוסי ששתק\u0004 — \u0003יגלה\u0004 כעונש ממקומו ביהודה \u0003לציפורי\u0004 בגליל. \u0003ושמעון שגינה\u0004 את המלכות — \u0003יהרג.\u0004","\u0003אזל\u0004 \u0005[הלך]\u0006 \u0003הוא,\u0004 ר' שמעון בר יוחאי \u0003ובריה\u0004 \u0005[ובנו]\u0006 ר' אלעזר, \u0003טשו בי מדרשא\u0004 \u0005[\u0006ו\u0005התחבאו בבית המדרש].\u0006 \u0003כל יומא הוה מייתי להו דביתהו ריפתא וכוזא דמיא וכרכי\u0004 \u0005[כל יום היתה מביאה להם אשתו\u0006 של ר' שמעון \u0005לחם וקנקן מים ואכלו].\u0006 \u0003כי תקיף גזירתא\u0004 \u0005[כאשר התחזקה הגזירה]\u0006 \u0003אמר ליה לבריה\u0004 \u0005[לו\u0006 ר' שמעון \u0005לבנו]:\u0006 \u0003נשים דעתן קלה עליהן,\u0004 ויש אם כן לחשוש \u0003דילמא מצערי לה ומגליא לן\u0004 \u0005[שמא יצערו אותה השלטונות ותגלה אותנו].\u0006 \u0003אזלו טשו במערתא\u0004 \u0005[הלכו והתחבאו במערה].\u0006 \u0003איתרחיש ניסא איברי להו חרובא ועינא דמיא\u0004 \u0005[התרחש נס ונברא להם\u0006 עץ \u0005חרוב ומעין מים],\u0006 \u0003והוו משלחי מנייהו והוו יתבי\u0004 \u0005[והיו פושטים בגדיהם והיו יושבים]\u0006 \u0003עד צוארייהו בחלא\u0004 \u0005[צווארם בחול],\u0006 שלא להשאר ערומים, וכך \u0003כולי יומא גרסי\u0004 \u0005[כל היום\u0006 היו \u0005לומדים].\u0006 \u0003בעידן צלויי לבשו מיכסו ומצלו, והדר משלחי מנייהו, כי היכי דלא ליבלו\u0004 \u0005[\u0006ו\u0005בזמן התפילה היו מתלבשים מתכסים ומתפללים, וחוזרים ופושטים\u0006 את \u0005בגדיהם, כדי שלא יבלו].\u0006 \u0003איתבו תריסר שני במערתא\u0004 \u0005[ישבו שתים עשרה שנה במערה].\u0006 \u0003אתא\u0004 \u0005[בא]\u0006 \u0003אליהו\u0004 הנביא \u0003וקם אפיתחא דמערתא\u0004 \u0005[ועמד על פתח המערה]\u0006 ו\u0003אמר: מאן לודעיה\u0004 \u0005[מי יודיעו]\u0006 \u0003לבר יוחאי דמית\u0004 \u0005[שמת]\u0006 ה\u0003קיסר ובטיל גזרתיה\u0004 \u0005[ובטלה גזירתו].\u0006","\u0003נפקו\u0004 \u0005[יצאו]\u0006 מהמערה, ובתוך כך \u0003חזו אינשי דקא כרבי וזרעי\u0004 \u0005[יצאו, ראו אנשים שהם חורשים וזורעים]\u0006 ו\u0003אמר:\u0004 הרי אנשים אלה \u0003מניחין חיי עולם\u0004 של לימוד תורה \u0003ועוסקין בחיי שעה\u0004 לצורך פרנסתם. ומסופר כי ב\u0003כל מקום ש\u0004הם \u0003נותנין\u0004 בו את \u0003עיניהן מיד\u0004 היה \u0003נשרף. יצתה בת קול ואמרה להם:\u0004 וכי \u0003להחריב\u0004 את \u0003עולמי יצאתם\u0004 מהמערה?! \u0003חיזרו למערתכם! הדור אזול איתיבו תריסר ירחי שתא\u0004 \u0005[חזרו\u0006 ו\u0005הלכו\u0006 ו\u0005ישבו שנים עשר חודש].\u0006 \u0003אמרי\u0004 \u0005[אמרו]:\u0006 \u0003משפט רשעים בגיהנם שנים עשר חדש\u0004 ובודאי כבר נתכפר להם חטאם בישיבה נוספת זו. \u0003יצתה בת קול ואמרה\u0004 להם: \u0003צאו ממערתכם! נפקו\u0004 \u0005[יצאו].\u0006 \u0003כל היכא דהוה מחי\u0004 \u0005[מקום שהיה מכה]\u0006 \u0003ר' אלעזר, הוה מסי\u0004 \u0005[היה מרפא]\u0006 \u0003ר' שמעון. אמר לו\u0004 ר' שמעון לר' אלעזר בנו: \u0003בני, די לעולם אני ואתה\u0004 שאנו שנינו עוסקים בתורה כראוי.","\u0003בהדי פניא דמעלי שבתא חזו ההוא סבא דהוה נקיט תרי מדאני אסא ורהיט\u0004 \u0005[בערוב יום ערב שבת ראו זקן אחד שהיה מחזיק שני צרורות הדסים ורץ]\u0006 \u0003בין השמשות. אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003הני\u0004 \u0005[אלה]\u0006 \u0003למה לך? אמר להו\u0004 \u0005[להם]:\u0006 \u0003לכבוד שבת.\u0004 אמרו לו: \u0003ותיסגי\u0004 \u0005[ויספיק]\u0006 \u0003לך בחד\u0004 \u0005[ב\u0006צרור \u0005אחד]!\u0006 ענה להם: \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003כנגד \"זכור\u0004 את יום השבת לקדשו\u0003\"\u0004 (שמות \u0003כ, ח), וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003כנגד \"שמור\u0004 את יום השבת לקדשו\u0003\"\u0004 (דברים ה, יב). \u0003אמר ליה לבריה\u0004 \u0005[לו\u0006 ר' שמעון \u0005לבנו]:\u0006 \u0003חזי\u0004 \u0005[ראה]\u0006 \u0003כמה חביבין מצות על ישראל. יתיב דעתייהו\u0004 \u0005[נתיישבה דעתם]\u0006 ולא כעסו עוד על שאין הכל עוסקין בתורה.","\u0003שמע ר' פנחס בן יאיר חתניה\u0004 \u0005[חתנו]\u0006 של ר' שמעון \u0003ונפק לאפיה\u0004 \u0005[ויצא לפניו,\u0006 לקראתו\u0005].\u0006 \u0003עייליה לבי בניה, הוה קא אריך ליה לבישריה\u0004 \u0005[הכניסו לבית המרחץ, והיה מטפל בבשרו].\u0006 \u0003חזי דהוה ביה פילי בגופיה\u0004 \u0005[ראה שהיו בו\u0006 בר' שמעון \u0005סדקים בגופו,\u0006 בעורו\u0005].\u0006 \u0003הוה קא בכי וקא נתרו דמעת עיניה וקמצוחא ליה\u0004 \u0005[היה בוכה ונשרו דמעות עיניו וציערו אותו],\u0006 את ר' שמעון. \u0003אמר לו\u0004 ר' פנחס לר' שמעון חמיו: \u0003אוי לי שראיתיך בכך. אמר לו\u0004 ר' שמעון: \u0003אשריך שראיתני בכך, שאילמלא לא ראיתני בכך\u0004 — \u0003לא מצאת בי כך\u0004 גדלות בתורה. שמסופר: \u0003דמעיקרא כי הוה מקשי\u0004 \u0005[בתחילה כאשר היה מקשה]\u0006 \u0003ר' שמעון בן יוחי קושיא, הוה מפרק ליה\u0004 \u0005[היה מתרץ לו]\u0006 \u0003ר' פנחס בן יאיר\u0004 עליה \u0003תריסר פירוקי\u0004 \u0005[שנים עשר תירוצים].\u0006 \u0003לסוף\u0004 (לבסוף), \u0003כי הוה מקשי\u0004 \u0005[כאשר היה מקשה]\u0006 \u0003ר' פנחס בן יאיר\u0004 תלמידו \u0003קושיא\u0004 — \u0003הוה מפרק ליה\u0004 \u0005[היה מתרץ לו]\u0006 \u0003ר' שמעון בן יוחאי עשרין וארבעה פירוקי\u0004 \u0005[תירוצים].\u0006","\u0003אמר\u0004 ר' שמעון: \u0003הואיל ואיתרחיש ניסא\u0004 \u0005[והתרחש\u0006 לי \u0005נס]\u0006 \u0003איזיל אתקין מילתא\u0004 \u0005[אלך\u0006 ו\u0005אתקן דבר]\u0006 עבור אחרים, כהכרת תודה על שגמל ה' לי חסד. \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"ויבא יעקב שלם\u0004 עיר שכם אשר בארץ כנען בבואו מפדן ארם ויחן את פני העיר\u0003\"\u0004 (בראשית לג, יח). \u0003ואמר רב,\u0004 כוונת לשון הכתוב \"ויבוא יעקב שלם\" היא: \u0003שלם בגופו, שלם בממונו, שלם בתורתו.\u0004 ומה עשה? \u0003\"ויחן את פני העיר\",\u0004 שעשה דברים של חנינה וטובה עבור העיר. \u0003אמר רב: מטבע תיקן להם\u0004 יעקב. \u0003ושמואל אמר: שווקים תיקן להם. ור' יוחנן אמר: מרחצאות תיקן להם.\u0004 מכל מקום למדנו שמי שאירע לו נס — ראוי לו שיעשה כאות תודה טובה לאנשי מקומו. \u0003אמר:\u0004 האם \u0003איכא מילתא דבעי לתקוני\u0004 \u0005[יש דבר שצריך תיקון]?\u0006 \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003איכא דוכתא דאית ביה\u0004 \u0005[יש מקום שיש\u0006 \u0003בו] ספק טומאה\u0004"],["\u0003ואית להו צערא\u0004 \u0005[ויש להם צער]\u0006 \u0003לכהנים לאקופי\u0004 \u0005[להקיפו],\u0006 שהרי כהנים אסור להם להטמא למת, ומקום זה, אף שלא היה ברור שנקבר בו מת, חששו לדבר ולא יכלו לבררו על בוריו. \u0003אמר\u0004 ר' שמעון: האם \u0003איכא איניש דידע דאיתחזק הכא\u0004 \u0005[היש אדם היודע שהיתה מוחזקת כאן]\u0006 \u0003טהרה?\u0004 כלומר, היש מישהו שזוכר מקום זה אי פעם שלא נחשב למקום טמא, אלא שהיה בו חלק לפחות שנחשב כטהור, \u0003אמר ליה ההוא סבא\u0004 \u0005[לו זקן אחד]:\u0006 \u0003כאן קיצץ בן זכאי תורמסי תרומה.\u0004 כלומר, בשוק זה זרע פעם ר' יוחנן בן זכאי, שהוא עצמו היה כהן, תורמוסים של תרומה, ובוודאי היה כאן מקום טהור. \u0003עבד איהו נמי הכי\u0004 \u0005[עשה גם הוא כן]\u0006 כיעקב טובה לעיר, ובדק את הקרקע (תוס'), \u0003כל היכא דהוה קשי\u0004 \u0005[מקום שהיה קשה]\u0006 — \u0003טהריה\u0004 \u0005[טיהרו],\u0006 שוודאי אין מת מתחתיו, \u0003וכל היכא דהוה רפי\u0004 \u0005[מקום שהיה רפה]\u0006 — \u0003צייניה\u0004 \u0005[ציינו,\u0006 סימנו\u0005],\u0006 מחשש קבורת מת. על ידי כך נעשה השוק טהור ויכלו אף הכהנים ללכת בו.","\u0003אמר ההוא סבא\u0004 \u0005[אותו זקן]\u0006 בלעג ובתמיהה: \u0003טיהר בן יוחי בית הקברות!\u0004 כעס ר' שמעון ו\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אילמלי לא היית עמנו, ואפילו היית עמנו, ולא נמנית עמנו\u0004 — \u0003יפה אתה אומר.\u0004 שיכולת לומר שלא ידעת על כוונתי, או שלא הסכמת ולא הצטרפת לדבר. \u0003עכשיו שהיית עמנו, ונמנית עמנו,\u0004 אתה גורם שיאמרו שתלמידי חכמים אינם מוכנים לשתף פעולה זה עם זה, ו\u0003יאמרו: זונות מפרכסות זו את זו,\u0004 שאף שהן מתחרות זו בזו, בכל זאת כל אחת מייפה את חברתה ועוזרת לה, \u0003תלמידי חכמים לא כל שכן?! יהב ביה עיניה ונח נפשיה\u0004 \u0005[נתן בו עיניו ונחה נפשו,\u0006 מת\u0005]\u0006 אותו זקן. \u0003נפק לשוקא חזייה\u0004 \u0005[יצא לשוק, ראהו]\u0006 את \u0003יהודה בן גרים,\u0004 שהוא היה הגורם לכל אותו מעשה. \u0003אמר\u0004 ר' שמעון: \u0003עדיין יש לזה בעולם? נתן בו עיניו ועשהו גל של עצמות.\u0004","\u0003שלשה דברים צריך אדם לומר בתוך ביתו ערב שבת עם חשכה,\u0004 ולא קודם לכן. ומפרטים: לשאול את בני ביתו, האם \u0003עשרתם\u0004 את הטבל הצריך עישור? האם \u0003ערבתם\u0004 עירובי תחומין וחצרות? ואם כן עשיתם — \u0003הדליקו את הנר\u0004 לכבוד שבת. כלל אמרו: אם הגיע הזמן בערב שבת שהוא \u0003ספק חשכה ספק אינו חשכה\u0004 — \u0003אין מעשרין את הודאי\u0004 (תבואה שוודאי לא עושרה מקודם), \u0003ואין מטבילין את הכלים\u0004 הטמאים לטהרם, \u0003ואין מדליקין את הנרות. אבל מעשרין את הדמאי\u0004 שרק ספק הוא אם לא עושר, ועישורו בפעם שניה אינו אלא מתוך חשש בלבד. \u0003ומערבין, וטומנין את החמין\u0004 לצורך שבת.","ומבררים: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים האלה]\u0006 שצריך לשאול אדם בביתו ערב שבת עם חשיכה? \u0003אמר ר' יהושע בן לוי:\u0004 ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"וידעת כי שלום אהלך ופקדת נוך ולא תחטא\"\u0004 (איוב, ה, כד), ומכאן שיפה לאדם שישאל בביתו (\"ופקדת נוך\") שלא יגיע אחר כך לידי חטא. \u0003אמר רבה בר רב הונא: אף על גב דאמור רבנן\u0004 \u0005[אף על פי שאמרו חכמים]\u0006 \u0003שלשה דברים צריך אדם לומר\u0004 בתוך ביתו ערב שבת עם חשיכה, וחובה היא לאומרם, מכל מקום \u0003צריך למימרינהו\u0004 \u0005[לאומרם]\u0006 \u0003בניחותא, כי היכי דליקבלינהו מיניה\u0004 \u0005[כדי שיקבלו אותם\u0006 בני ביתו \u0005ממנו],\u0006 שאם יאמר בלשון קשה שמא ישיבו לו דברים שאינם נכונים ויכשל בעבירה. \u0003אמר רב אשי : אנא\u0004 \u0005[אני]\u0006 \u0003לא שמיע לי הא\u0004 \u0005[שמעתי\u0006 הלכה \u0005זו]\u0006 של \u0003רבה בר רב הונא, ו\u0004אולם \u0003קיימתי\u0004 אותה \u0003בעצמי מ\u0004תוך \u0003סברא,\u0004 שכך ראה לעשות.","ושואלים: \u0003הא גופא קשיא\u0004 \u0005[זו,\u0006 המשנה, \u0005עצמה קשה],\u0006 לפי שיש בה סתירה פנימית. שכן מצד אחד \u0003אמרת\u0004 קודם ש\u0003שלשה דברים צריך אדם לומר בתוך ביתו ערב שבת עם חשכה,\u0004 ומשמע: \u0003עם חשכה,\u0004 כלומר, קודם חשיכה — \u0003אין\u0004 \u0005[כן],\u0006 אבל אם כבר \u0003ספק חשכה ספק אינו חשכה\u0004 — \u0003לא\u0004 ישאל, שאף אם ישאל — אין עוד רשות בידו לתקן את הדברים. \u0003והדר תני\u0004 \u0005[וחזר ושנה]:\u0006 \u0003ספק חשכה ספק אינו חשכה\u0004 — \u0003מערב.\u0004 הרי שיש תקנה אפילו בשעה מאוחרת יותר! ומדוע הגבילו זמן השאלה רק לשעה זו?","ובדרך אגב לפני שמביאים תירוץ לדבר מזכירים את כל שאר ההלכות שאמר בעל התירוץ במסכת שבת ו\u0003סימן\u0004 להם: \u0003בגופיא זימרא ציפרא בחבלא דמילתא.\u0004","\u0003אמר ר' אבא אמר ר' חייא בר אשי אמר רב : לא קשיא\u0004 \u0005[אין זה קשה],\u0006 ואין בכך סתירה. \u0003כאן\u0004 בתחילת המשנה שמשמע שהעירוב יכול להיעשות רק מבעוד יום — הרי זה \u0003בעירובי תחומין\u0004 שיש להם סמך בתורה ולפיכך צריך לעשותם כשוודאי יום. ו\u0003כאן\u0004 שאמרו שמותר לערב אפילו כאשר כבר ספק חשיכה — המדובר הוא \u0003בעירובי חצרות,\u0004 הקלים ביותר ואינם אלא החמרה.","אגב דברים אלה, מביאים את ההלכה ש\u0003אמר רבא\u0004 להדגיש את צד תקנת חכמים בדיני עירוב: מי ש\u0003אמרו לו שנים: צא וערב עלינו\u0004 (בשבילנו) עירוב חצרות (ר\"ח), \u0003לאחד עירב עליו מבעוד יום, ולאחד עירב עליו בין השמשות\u0004 שהוא ספק יום ספק לילה, ואירע ש\u0003זה שעירב עליו מבעוד יום נאכל עירובו בין השמשות, וזה שעירב עליו בין השמשות נאכל עירובו משחשכה,\u0004 וכלל בידינו שרגע כניסת השבת הוא הזמן הקובע לגבי תחולת העירוב, שאם הניחו את העירוב קודם, והעירוב עודנו קיים ברגע זה — קנה העירוב וכוחו יפה. ובבעיה שלפנינו באופן שהניח את העירוב בזמן הראוי — נאכל עירובו בין השמשות, וספק אם היה העירוב קיים ברגע כניסת השבת. ואלו במקרה השני — הספק הוא אם העירוב היה מונח עוד לפני כניסת השבת, כדי שבכלל יחול. ועל כך קבע רבא להלכה כי \u0003שניהם קנו\u0004 את ה\u0003עירוב.\u0004","ותמהים: \u0003מה נפשך\u0004 \u0005[מה רצונך],\u0006 שכן בכל אופן שאתה רוצה אין אתה יכול להסביר. שהרי \u0003אי\u0004 \u0005[אם]\u0006 זמן \u0003בין השמשות יממא\u0004 \u0005[יום]\u0006 \u0003הוא\u0004 — אם כן \u0003בתרא ליקני\u0004 \u0005[האחרון\u0006 \u0003יקנה]\u0004 עירובו ואילו \u0003קמא\u0004 \u0005[הראשון]\u0006 \u0003לא ליקני\u0004 \u0005[יקנה],\u0006 שהרי נאכל עירובו מבעוד יום. \u0003ואי\u0004 \u0005[ואם]\u0006 זמן \u0003בין השמשות ליליא\u0004 \u0005[לילה]\u0006 \u0003הוא,\u0004 אם כן \u0003קמא ליקני\u0004 \u0005[הראשון יקנה]\u0006 את עירובו ואילו \u0003בתרא\u0004 \u0005[האחרון]\u0006 \u0003לא ליקני\u0004 \u0005[יקנה],\u0006 שהרי לא הונח עירובו לפני השבת. ובכל אופן לא יתכן ששני העירובים גם יחד יהיה להם תוקף! על כך משיבים לשיטת רבא: \u0003בין השמשות ספקא\u0004 \u0005[ספק]\u0006 \u0003הוא,\u0004 ואין יודעים כלל אם הוא יום או לילה או שניהם יחד, \u0003ו\u0004מכיוון שספק הוא — \u0003ספקא דרבנן לקולא\u0004 \u0005[ספק שמדברי סופרים,\u0006 נוהגים בו \u0005להקל]\u0006 ומניחים שהעירוב נקנה בשני המקרים.","\u0003ו\u0004עוד \u0003אמר רבא: מפני מה אמרו\u0004 ש\u0003אין טומנין\u0004 חמין אפילו \u0003בדבר שאינו מוסיף הבל,\u0004 כלומר, בתוך דבר שאינו מוסיף לחמם עוד את האוכל שמכניסים בתוכו אלא רק שומר את חומו כמות שהוא, בערב שבת \u0003משחשכה?\u0004 — \u0003גזרה שמא ירתיח\u0004 את הקדירה בשבת. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: אי הכי\u0004 \u0005[אם כך]\u0006 שאנו חוששים שמא ירתיח, אם כן בשעת \u0003בין השמשות נמי ניגזר\u0004 \u0005[גם כן ניגזור]\u0006 ונאסור להטמין בדבר שאינו מוסיף הבל?! \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא: בשעת בין השמשות אין לחשוש, שכן אז \u0003סתם קדירות רותחות הן,\u0004 שוודאי רק ברגע זה הורידו אותן מעל האש, אבל בשעות הלילה כבר הצטננו הקדירות, ויתכן שיבא אדם להרתיחן כדי לשמור את חומן.","\u0003ו\u0004עוד \u0003אמר רבא\u0004"],["\u0003מפני מה אמרו\u0004 חכמים ש\u0003אין טומנין\u0004 לצורך שבת \u0003בדבר המוסיף הבל ואפילו מבעוד יום?\u0004 — \u0003גזירה שמא יטמין ברמץ\u0004 (אפר שבו שיירי גחלים) \u0003שיש בה גחלת,\u0004 שהרי גם הרמץ הוא דבר המוסיף הבל, ולא יבחינו אנשים בין תוספת זו לתוספת אחרת. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: ויטמין\u0004 אף ברמץ, ומה בכך? ענה לו רבא: \u0003גזירה, שמא יחתה\u0004 (ינער) \u0003בגחלים,\u0004 להבעירן בשבת, ויעבור על איסור חמור שמן התורה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 ברייתא הדנה במכלול הבעיות של שעת בין השמשות. ואמרו: \u0003בין השמשות\u0004 הוא \u0003ספק מן היום ומן הלילה\u0004 יחד, \u0003ספק כולו מן היום, ספק כולו מן הלילה.\u0004 ומשום כך \u0003מטילין אותו לחומר שני ימים,\u0004 כלומר, נוהגים בו לחומרה כבשני הימים, הקודם והבא אחריו, שאם יש חומרה באחד מהם — יש לנהוג בה בשעת בין השמשות. ועדיין הגדרת בין השמשות אינה וודאית.","ש\u0003איזהו הוא בין השמשות?\u0004 — \u0003משתשקע החמה, כל זמן שפני מזרח מאדימין\u0004 מאור השמש. \u0003הכסיף\u0004 (אבד צבעו) החלק \u0003התחתון\u0004 של הרקיע, \u0003ו\u0004עדיין \u0003לא הכסיף העליון\u0004 — זוהי שעת \u0003בין השמשות. הכסיף העליון והשוה\u0004 צבעו \u0003לתחתון\u0004 — \u0003זהו לילה,\u0004 אלו \u0003דברי ר' יהודה. ר' נחמיה אומר:\u0004 שיעור בין השמשות הוא, \u0003כדי שיהלך אדם משתשקע החמה\u0004 עוד \u0003חצי מיל. ר' יוסי אומר: בין השמשות\u0004 אינו נמשך זמן מסויים, אלא הוא \u0003כהרף עין, זה,\u0004 הלילה, \u0003נכנס, וזה,\u0004 היום, \u0003יוצא. ואי אפשר לעמוד עליו,\u0004 מפני קטנותו.","שנינו ש\u0003אמר מר\u0004 \u0005[החכם]\u0006 בברייתא שבין השמשות \u0003מטילין אותו לחומר שני ימים,\u0004 ושואלים: \u0003למאי הלכתא\u0004 \u0005[ל\u0006גבי \u0005מה,\u0006 איזו הלכה\u0005]\u0006 נאמר הדבר? \u0003אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע:\u0004 המדובר הוא \u0003לענין טומאה, כדתנן\u0004 \u0005[כפי\u0006 \u0003ששנינו\u0004 במשנה\u0005]:\u0006 זב ש\u0003ראה\u0004 זוב \u0003שני ימים,\u0004 בזה אחר זה, \u0003בין השמשות,\u0004 הרי ספק בידינו אם נחשוב זאת כאילו ראה זוב יום אחד, שאולי בין השמשות של היום הראשון שייך היה ליום שלאחריו, ובין השמשות של היום השני שייך ליום שלפניו. או שני ימים בלבד ששניהם שייכים או ליום שלפניהם או ליום שלאחריהם. או שלושה ימים, שהרי אפשר לחשוב כל שעת בין השמשות כשני ימים. וכיון שלפי התורה זב שראה זוב פעמיים טמא הוא, וכל חומרות טומאת זב עליו, ואם ראה פעם שלישית — צריך להביא קרבן בעת טהרתו, הרי זב זה שראה ספק יום ספק יומיים ספק שלושה — \u0003ספק\u0004 הוא הן \u0003לטומאה ו\u0004הן \u0003לקרבן. ראה\u0004 זוב \u0003יום אחד בין השמשות\u0004 — הרי זה \u0003ספק לטומאה,\u0004 שמא היו אלה שני ימים.","על הברייתא שהבאנו מעירים, \u0003הא\u0004 \u0005[\u0006ברייתא \u0005זו]\u0006 \u0003גופה קשיא\u0004 \u0005[קשה]\u0006 מתוכה. שהרי \u0003אמרת\u0004 קודם ש\u0003איזהו בין השמשות\u0004 — \u0003משתשקע החמה, כל זמן שפני מזרח מאדימין. הא\u0004 \u0005[הרי]\u0006 אם \u0003הכסיף התחתון,\u0004 אף על פי ש\u0003לא הכסיף העליון\u0004 — \u0003לילה הוא. והדר תנא\u0004 \u0005[וחזר ושנה]:\u0006 \u0003הכסיף התחתון ולא הכסיף העליון\u0004 — הרי זה \u0003בין השמשות.\u0004 ואם כן, כשמדייקים בדברים מצויה לכאורה סתירה פנימית בברייתא! \u0003אמר רבה\u0004 שכך \u0003אמר רב יהודה אמר שמואל:\u0004 כדי לסלק את הסתירה \u0003כרוך\u0004 צרף יחד שני משפטים \u0003ותני\u0004 \u0005[\u0006\u0005ושנה]\u0006 כך: \u0003איזהו בין השמשות\u0004 — \u0003משתשקע החמה, כל זמן שפני מזרח מאדימין. והכסיף התחתון ולא הכסיף העליון\u0004 — \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003בין השמשות\u0004 הוא, ורק אם \u0003הכסיף העליון והשוה\u0004 צבעו \u0003לתחתון\u0004 — הרי זה \u0003לילה. ורב יוסף אמר\u0004 בשם \u0003רב יהודה\u0004 ש\u0003אמר\u0004 בשם \u0003שמואל\u0004 באופן אחר: \u0003משתשקע החמה כל זמן שפני מזרח מאדימין\u0004 — \u0003יום\u0004 הוא. \u0003הכסיף התחתון ולא הכסיף העליון\u0004 — \u0003בין השמשות\u0004 הוא. \u0003הכסיף העליון והשוה\u0004 צבעו \u0003לתחתון\u0004 — \u0003לילה\u0004 הוא.","ומעירים: במחלוקת זו מהי בדיוק הגדרת בין השמשות \u0003אזדו לטעמייהו\u0004 \u0005[הלכו\u0006 רבה ורב יוסף \u0005לטעמם,\u0006 לשיטתם\u0005].\u0006 \u0003דאיתמר\u0004 \u0005[שנאמר]\u0006 שנחלקו בענין \u0003שיעור בין השמשות בכמה\u0004 משך זמנו? \u0003אמר רבה אמר רב יהודה אמר שמואל:\u0004 משך זמן הליכת \u0003שלשה חלקי מיל.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003שלשה חלקי מיל? אילימא\u0004 \u0005[אם נאמר]\u0006 כי הכוונה היא ל\u0003תלתא פלגי מילא\u0004 \u0005[שלושה חצאי מיל],\u0006 אם כן \u0003נימא\u0004 \u0005[שיאמר]\u0006 \u0003מיל ומחצה. אלא\u0004 תאמר כי הוא \u0003תלתא תילתי מילא\u0004 \u0005[שלושה שלישי מיל],\u0006 אם כן \u0003נימא\u0004 \u0005[שיאמר]\u0006 פשוט יותר — \u0003מיל. אלא\u0004 ודאי הכוונה ל\u0003תלתא ריבעי מילא\u0004 \u0005[שלושה רבעי מיל].\u0006 \u0003ורב יוסף אמר\u0004 בשם \u0003רב יהודה\u0004 ש\u0003אמר\u0004 בשם \u0003שמואל:\u0004 שיעור בין השמשות הוא \u0003שני חלקי מיל.\u0004 ושוב שואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003שני חלקי מיל? אילימא\u0004 \u0005[אם נאמר]\u0006 הכוונה ל\u0003תרי פלגי מילא\u0004 \u0005[שני חצאי מיל]\u0006 אם כן \u0003לימא\u0004 \u0005[שיאמר]\u0006 בפשטות \u0003מיל.\u0004 מיל. \u0003ואלא\u0004 תאמר שהכוונה היא ל\u0003תרי רבעי מילא\u0004 \u0005[שני רבעי מיל]\u0006 \u0003אם כן לימא\u0004 \u0005[שיאמר]\u0006 במקום זה: \u0003חצי מיל. אלא\u0004"],["\u0003תרי תילתי מילא\u0004 \u0005[שני שלישי מיל].\u0006 ומסבירים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם\u0006 למעשה\u0005]\u0006 — \u0003איכא בינייהו פלגא דדנקא\u0004 \u0005[יש ביניהם\u0006 הבדל ב\u0005חצי ששית\u0006 מיל\u0005],\u0006 הרי שיש אחידות בחלוקתם, ושיעורו של רב יוסף בבין השמשות קטן משיעורו של רבה.","ומעירים: \u0003וחילופה בחלתא\u0004 \u0005[וההיפך\u0006 בדין \u0005כוורת],\u0006 ששם השעור שקצב רב יוסף גדול הוא מן השיעור שקבע רבה. ש\u0003אמר רבה: חלתא\u0004 \u0005[כוורת]\u0006 \u0003בת\u0004 (ה\u0003מחזיקה) תרי כורי\u0004 \u0005[שני כורים]\u0006 — \u0003שרי לטלטולה\u0004 \u0005[מותר לטלטלה]\u0006 בשבת, \u0003ובת תלתא כורי\u0004 \u0005[שלושה כורים]\u0006 — \u0003אסור לטלטולה\u0004 \u0005[לטלטלה],\u0006 שגדולה היא הרבה משיעור כלי, ולא הותר לטלטל בשבת אלא כלים. \u0003ורב יוסף אמר: בת תלתא כורי\u0004 \u0005[שלושה כורים]\u0006 — \u0003נמי שרי\u0004 \u0005[גם כן מותרת]\u0006 בטלטול, ורק \u0003בת ארבעה כורי\u0004 \u0005[כורים]\u0006 — \u0003אסור\u0004 לטלטלה.","\u0003אמר אביי: בעי מיניה דמר\u0004 \u0005[שאלתי את רבי,\u0006 רבה\u0005]\u0006 \u0003בשעת מעשה,\u0004 כשהייתי צריך לדעת בפועל מה לעשות, \u0003ואפילו בת תרי כורי\u0004 \u0005[שני כורים]\u0006 \u0003לא שרא\u0004 \u0005[התיר]\u0006 \u0003לי\u0004 לטלטל. ומסבירים: \u0003כמאן\u0004 \u0005[כ\u0006דעת \u0005מי]\u0006 נהג כך רבא הלכה למעשה — \u0003כהאי\u0004 \u0005[כאותו]\u0006 ה\u0003תנא דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 דעתו במשנה\u0005]\u0006 בדיני טהרות: \u0003כוורת הקש וכוורת ה\u0004עשויה \u0003קנים ובור ספינה אלכסנדרית\u0004 שעושים כלי גדול בספינה וממלאים אותו מים מתוקים לשתייה, \u0003אף על פי ש\u0004כלים אלה \u0003יש להם שולים,\u0004 כיון ש\u0003הן מחזיקות ארבעים סאה בלח\u0004 (נוזלים) \u0003שהן כוריים ביבש\u0004 — \u0003טהורים,\u0004 אפילו נגע בהם דבר טמא, כי כלים גדולים מעבר לגבול מסויים שוב אינם נחשבים ככלים, ואינם מקבלים עוד טומאה. ועל כך סמך רבה כשאסר לטלטל אפילו כוורת בת שני כורים, שהרי לענין טומאה אינה נחשבת עוד כלי. על המשנה העיר ו\u0003אמר אביי: שמע מינה האי גודשא תילתא הוי\u0004 \u0005[למד ממנה\u0006 כי \u0005גודש זה\u0006 שגודשים דברים בכלי, הרי \u0005הוא שליש]\u0006 ממה שהכלי מכיל. שהרי במשנה נאמר שכלי המכיל ארבעים סאה בלח, מכיל שני כורים, שהם שישים סאה, ביבש. הרי שביבש שאפשר לגדוש בו מוסיפים עוד שליש.","מסופר: \u0003אביי חזייה\u0004 \u0005[ראהו]\u0006 את \u0003רבא דקא דאוי\u0004 \u0005[שהוא צופה]\u0006 בערב שבת \u0003ל\u0004צד \u0003מערב,\u0004 לדעת האם האדימו השמים ולידע בכך את זמן בין השמשות. \u0003אמר ליה\u0004 \u0005[לו]\u0006 אביי לרבא: \u0003והא תניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 שזמן בין השמשות הוא \u0003כל זמן שפני מזרח מאדימין\u0004 ומדוע מסתכל אתה למערב? \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא: \u0003מי סברת\u0004 \u0005[האם סבור אתה]\u0006 שהכוונה ל\u0003פני\u0004 ה\u0003מזרח ממש? לא,\u0004 הכוונה היא ל\u0003פנים\u0004 של הרקיע \u0003המאדימין את המזרח,\u0004 שהם ממולם, כלומר, בצד מערב. \u0003איכא דאמרי\u0004 \u0005[יש אומרים]\u0006 כי סיפור זה היה שונה ממה ששנינו. ומספרים סיפור זה בנוסחה שונה קצת. \u0003רבא חזייה\u0004 \u0005[ראהו]\u0006 את \u0003אביי דקא דאוי\u0004 \u0005[שהוא צופה]\u0006 \u0003ל\u0004צד \u0003מזרח. אמר ליה\u0004 \u0005[לו]\u0006 \u0003מי סברת\u0004 \u0005[האם סבור אתה]\u0006 כי הכוונה ל\u0003פני\u0004 ה\u0003מזרח ממש?\u0004 הכוונה היא \u0003פנים המאדימין את המזרח,\u0004 כלומר, צד מערב. \u0003וסימניך\u0004 \u0005[וסימנך]:\u0006 \u0003כוותא,\u0004 שממול לחלון רואים עד כמה נכנסה בו השמש.","על מה ששנינו בברייתא ש\u0003ר' נחמיה אומר\u0004 ששיעור בין השמשות הוא ב\u0003כדי שיהלך אדם משתשקע החמה חצי מיל. אמר ר' חנינא: הרוצה לידע\u0004 באופן מדוייק אימתי הוא \u0003שיעורו של ר' נחמיה\u0004 יעשה כן: \u0003יניח חמה בראש הכרמל,\u0004 שכאשר הוא על שפת הים עדיין רואה הוא את ראש הכרמל מואר בשמש. \u0003וירד ויטבול בים ויעלה, וזהו שיעורו של ר' נחמיה.\u0004","משום דמיון הביטוי מביאים את מה ש\u0003אמר ר' חייא:\u0004 הרוצה לראות את \u0003בארה של מרים\u0004 שהיתה עוברת עם ישראל ממקום למקום, יעשה כן: \u0003יעלה לראש הכרמל ויצפה ויראה\u0004 סלע \u0003כמין כברה\u0004 (נפה) \u0003בים, וזו היא בארה של מרים.\u0004 ו\u0003אמר רב\u0004 בענין זה: \u0003מעין המיטלטל\u0004 שעובר ממקום למקום — \u0003טהור\u0004 ודינו כמעין ממש, ולא כמים שאובים. \u0003ו\u0004איזה הוא מעין המיטלטל? \u0003זהו בארה של מרים.\u0004","\u0003אמר ר' יהודה\u0004 שכך \u0003אמר שמואל: בין השמשות\u0004 של \u0003ר' יהודה, כהנים\u0004 שנטמאו ורוצים לטבול לטהרתם מבעוד יום כדי שאחר טבילתם יהיה להם הערב שמש ויוכלו לאכול בתרומה, עדיין \u0003טובלים\u0004 הם \u0003בו,\u0004 לפי שלדעה זו בין השמשות עדיין נחשב ליום. ושואלים: \u0003למאן\u0004 \u0005[ל\u0006דעת \u0005מי,\u0006 לאיזו שיטה\u0005]\u0006 אומר אתה כך, \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 ש\u0003ל\u0004שיטת \u0003ר' יהודה\u0004 עצמו — והלא לדעתו המפורשת בין השמשות \u0003ספקא\u0004 \u0005[ספק]\u0006 \u0003הוא,\u0004 וכפי ששנינו מקודם. ואם כן הטובל בו אינו יכול לאכול בתרומה עד לאחר הערב שמש שלמחרת. \u0003אלא\u0004 הכוונה היא לזמן \u0003בין השמשות\u0004 של \u0003ר' יהודה\u0004 שה\u0003כהנים\u0004 יכולים לטבול בו לשיטת \u0003ר' יוסי,\u0004 שאותו זמן נחשב לר' יוסי כיום, ולאחריו אם כן יהיה להם הערב שמש.","ושואלים: אם כן \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005],\u0006 שהרי לפי ר' יוסי טובלים הם מבעוד יום! ומשיבים: \u0003מהו דתימא\u0004 \u0005[יכול הייתי לומר]\u0006 ש\u0003בין השמשות\u0004 לשיטת \u0003ר' יוסי מישך שייך\u0004 \u0005[שייך]\u0006 זמנו \u0003ב\u0004תוך זמן בין השמשות של \u0003ר' יהודה,\u0004 והוא בסופו, ואם כן משהסתיים זמן בין השמשות לר' יהודה אף לשיטת ר' יוסי הוא הסתיים, ולאחריו הוא לילה וכבר לא יוכל להיות באותו יום הערב שמש. על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 \u0003דשלים\u0004 \u0005[ש\u0006קודם \u0005נגמר]\u0006 \u0003בין השמשות\u0004 לשיטת \u0003ר' יהודה, והדר\u0004 \u0005[ו\u0006רק \u0005אחר\u0006 כך\u0005]\u0006 \u0003מתחיל בין השמשות ל\u0004שיטת \u0003ר' יוסי\u0004 והוא מאוחר לזה של ר' יהודה.","\u0003אמר רבה בר בר חנה\u0004 שכך \u0003אמר ר' יוחנן: הלכה כר' יהודה לענין\u0004 דיני \u0003שבת, והלכה כר' יוסי לענין תרומה.\u0004 ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 לענין \u0003הלכה כר' יהודה לענין שבת,\u0004 אפשר לומר שכמו בשאר ספיקות בשבת פוסקים \u0003לחומרא\u0004 \u0005[להחמיר],\u0006 כדין כל ספק שמן התורה. \u0003אבל לענין תרומה\u0004 — \u0003מאי היא\u0004 \u0005[מה הוא]\u0006 המקרה שבו מדובר? \u0003אילימא\u0004 \u0005[אם נאמר]\u0006 \u0003ל\u0004ענין \u0003טבילה\u0004 — והלא אף טבילה \u0003ספקא\u0004 \u0005[ספק]\u0006 שמן התורה \u0003היא,\u0004 ומדוע נקל בו יותר מבדיני שבת?"],["\u0003אלא\u0004 יש לומר שהכוונה היא \u0003לאכילת תרומה.\u0004 ש\u0003לא אכלי\u0004 \u0005[אוכלים]\u0006 ה\u0003כהנים תרומה עד דשלים\u0004 \u0005[שייגמר]\u0006 \u0003בין השמשות\u0004 שלפי שיטת \u0003ר' יוסי\u0004 שהוא מעט אחר זה של ר' יהודה.","בשיעור בין השמשות \u0003אמר רב יהודה\u0004 שכך \u0003אמר שמואל:\u0004 כשנראה בשמי הערב \u0003כוכב אחד\u0004 עדיין \u0003יום\u0004 הוא, \u0003שנים\u0004 — \u0003בין השמשות, שלשה\u0004 — \u0003לילה. תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003כוכב אחד יום שנים בין השמשות שלשה לילה, אמר ר' יוסי,\u0004 אין המדובר \u0003לא\u0004 ב\u0003כוכבים גדולים הנראין\u0004 אף \u0003ביום, ולא כוכבים קטנים שאין נראין אלא\u0004 מאוחר \u0003בלילה, אלא\u0004 בכוכבים \u0003בינונים.\u0004","\u0003אמר ר' יוסי בר' זבידא: העושה מלאכה בשני בין השמשות,\u0004 בזה שבין ערב שבת לשבת ובזה שבין שבת למוצאי שבת — \u0003חייב\u0004 להביא קרבן \u0003חטאת\u0004 על מלאכה בשבת \u0003ממה נפשך.\u0004 כי בין שנאמר שבין השמשות הוא יום או לילה — ודאי היה זה פעם אחת יום או לילה ועשה מלאכה בשבת. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא לשמעיה\u0004 \u0005[לשמשו]:\u0006 \u0003אתון דלא קים לכו בשיעורא דרבנן, אדשמשא אריש דיקלי אתלו שרגא\u0004 \u0005[אתם שאינכם בקיאים בשעורי חכמים, בעוד השמש בראשי הדקלים, הדליקו נרות\u0006 שבת\u0005].\u0006 ושאלו השמש: \u0003ביום המעונן מאי\u0004 \u0005[מה\u0006 נעשה\u0005]?\u0006 שהרי אין מבחינים אז בחמה בראש אילנות? אמר לו רבא: \u0003במתא חזי תרנגולא\u0004 \u0005[בעיר ראה\u0006 את ה\u0005תרנגולים]\u0006 שלקראת הערב מתיישבים הם על קורותיהם. ואילו \u0003בדברא\u0004 \u0005[בשדה]\u0006 הסתכל על \u0003עורבי\u0004 \u0005[העורבים].\u0006 שאף הם חוזרים לקניהם לקראת הערב \u0003אי נמי אדאני\u0004 \u0005[או גם כן\u0006 הבט על צמחי \u0005האדני]\u0006 הפונים לצד מערב בלילה, ומשמתחילים לפנות לכיוון מערב הרי שהערב מתקרב.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003שש תקיעות תוקעין\u0004 ב\u0003ערב שבת\u0004 להודיע על השבת הנכנסת. ומפרטים מה באה כל אחת מהן מלהודיע ולרמז: תקיעה \u0003ראשונה\u0004 עשויה כדי \u0003להבטיל את העם ממלאכה שבשדות.\u0004 תקיעה \u0003שניה\u0004 — \u0003להבטיל\u0004 ממלאכה את העובדים ב\u0003עיר, ו\u0004לסגור את ה\u0003חנויות. שלישית\u0004 — \u0003להדליק את הנר\u0004 לשבת, אלו \u0003דברי ר' נתן. ר' יהודה הנשיא אומר:\u0004 תקיעה \u0003שלישית\u0004 הרי היא כדי להודיע לאלו המניחים תפילין כל היום שיש להם \u0003לחלוץ\u0004 את ה\u0003תפילין,\u0004 שהרי אין מניחים תפילין בשבת. \u0003ושוהה\u0004 אחר התקיעה השלישית \u0003כדי\u0004 זמן הדרוש ל\u0003צליית דג קטן, או כדי להדביק פת בתנור,\u0004 שמא שכח מישהו וזקוק לכך לצורך שבת, \u0003ותוקע ומריע ותוקע,\u0004 כלומר, תקיעה, תרועה ותקיעה, \u0003ושובת.\u0004 שאז הגיעה שבת לכל דבר.","\u0003אמר רבן שמעון בן גמליאל: מה נעשה להם לבבליים\u0004 המשנים מן המנהג, \u0003ש\u0004הם \u0003תוקעין ומריעין ושובתין מתוך מריעין,\u0004 כלומר עם שמיעת קול התרועה. על כך שואלים: האם אכן הבבליים רק \u0003תוקעין ומריעין\u0004 ולא מוסיפים לתקוע שוב? והרי אם כן \u0003הוו להו\u0004 \u0005[יהיו]\u0006 בסך הכל רק \u0003חמשה\u0004 תקיעות, ולא שש כפי שאמרנו! \u0003אלא\u0004 יש לגרוס: \u0003שתוקעין וחוזרין ותוקעין ומריעין, ושובתין מתוך מריעין.\u0004 וזאת משום \u0003מנהג אבותיהן\u0004 אשר \u0003בידיהן.\u0004","\u0003מתני ליה\u0004 \u0005[שנה לו]\u0006 \u0003רב יהודה לרב יצחק בריה\u0004 \u0005[בנו]:\u0006 התקיעה \u0003השניה\u0004 שתוקעים בערב שבת היא כדי להודיע שיש \u0003להדליק את הנר.\u0004 ושואלים: \u0003כמאן\u0004 \u0005[כ\u0006דעת \u0005מי],\u0006 לפי איזו שיטה אמר דבר זה? שהרי אין זה \u0003לא כ\u0004דברי \u0003ר' נתן ולא כ\u0004דברי \u0003ר' יהודה הנשיא, אלא\u0004 וודאי אמר לו שהתקיעה \u0003השלישית\u0004 היא כדי להזכיר שיש \u0003להדליק את הנר,\u0004 ו\u0003כמאן\u0004 \u0005[כ\u0006דעת \u0005מי]\u0006 אמר כן — \u0003כר' נתן.\u0004","ובאותו ענין \u0003תנא דבי\u0004 \u0005[שנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל\u0004 בהרחבה: \u0003שש תקיעות תוקעין\u0004 ב\u0003ערב שבת. התחיל לתקוע תקיעה ראשונה\u0004 — \u0003נמנעו העומדים בשדה\u0004 ועובדים שם \u0003מלעדור ומלחרוש ומלעשות כל מלאכה שבשדות. ו\u0004אולם \u0003אין\u0004 הפועלים \u0003הקרובין\u0004 הסמוכים לעיר, \u0003רשאין ליכנס\u0004 לעיר \u0003עד שיבואו\u0004 ה\u0003רחוקין ויכנסו כולם כאחד.\u0004 שאם לא כן, יחשדו במאחרים שהמשיכו לעבוד לאחר התקיעה. \u0003ועדיין\u0004 בזמן זה ה\u0003חנויות\u0004 שבעיר \u0003פתוחות ותריסין\u0004 (דלתות החנויות שהיו מניחים אותן לפני החנות ומסדרים עליהן את הסחורה) \u0003מונחין\u0004 במקומם. \u0003התחיל לתקוע תקיעה שניה, נסתלקו התריסין\u0004 ממקום הנחתם \u0003וננעלו החנויות. ו\u0004אולם בבתים, \u0003עדיין\u0004 ה\u0003חמין מונחין על גבי\u0004 ה\u0003כירה\u0004 להתבשל, \u0003וקדירות מונחות על גבי כירה\u0004. \u0003התחיל לתקוע תקיעה שלישית\u0004 — \u0003סילק המסלק\u0004 את התבשיל מן הכירה, \u0003והטמין המטמין\u0004 חמין לשבת במקום שלא יפוג החום, \u0003והדליק המדליק\u0004 נרות שבת. \u0003ושוהה\u0004 התוקע \u0003כדי\u0004 זמן הדרוש ל\u0003צליית דג קטן, או כדי להדביק פת בתנור, ותוקע ומריע ותוקע ושובת.\u0004","\u0003אמר ר' יוסי בר' חנינא: שמעתי שאם\u0004 הזדקק אדם ו\u0003בא להדליק\u0004 נר שבת \u0003אחר שש תקיעות\u0004 — \u0003מדליק\u0004 ואינו חושש, שאפילו זמן התקיעה הששית עדיין אינה שבת. וראיה לדבר — \u0003שהרי נתנו חכמים שיעור לחזן\u0004 (שמש) \u0003הכנסת להוליך שופרו\u0004 שבו היה תוקע על גג גבוה באמצע העיר \u0003לביתו,\u0004 וברור אם כן שבתוך שיעור זמן זה עדיין אינו שבת. אמרו לו: \u0003אם כן\u0004 אתה סבור, הרי \u0003נתת דבריך לשיעורין,\u0004 שבכל מקום יהא שיעור אחר לכניסת השבת, לפי מרחק מקום התקיעה מבית השמש. \u0003אלא מקום צנוע\u0004 (מוסתר) \u0003יש לו לחזן הכנסת בראש גגו\u0004 בו היה תוקע, \u0003ששם מניח\u0004 את \u0003שופרו.\u0004 ומיד אחר תקיעה אחרונה נכנסת השבת, ואין שהות בינתיים, שכן לדעת הכל \u0003לפי ש\u0004ההלכה היא \u0003שאין מטלטלין\u0004 בשבת \u0003לא את השופר ולא את החצוצרות.\u0004","על ההלכה האחרונה שואלים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 שה\u0003שופר מיטלטל\u0004 בשבת, \u0003וחצוצרות אינם מיטלטלין! אמר רב יוסי : לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 שכן אפשר לומר כי \u0003כאן\u0004 שהתירו לטלטל שופר מדובר \u0003ב\u0004שופר של \u0003יחיד,\u0004 משום שיש לו שימוש אף בשבת, ו\u0003כאן\u0004 שאסרו לטלטלו — מדובר \u0003ב\u0004שופר של \u0003צבור\u0004 שאין לו שימוש בשבת ולכן הוא נחשב כמוקצה. \u0003אמר ליה אביי: וביחיד למאי חזי\u0004 \u0005[למה,\u0006 לאיזו מלאכה המותרת בשבת \u0005ראוי]\u0006 השופר? — \u0003הואיל וראוי לגמע\u0004 (להשקות) בו \u0003מים\u0004"],["\u0003לתינוק,\u0004 שפי השופר כפוף, ואפשר להכניס לתוכו מעט מים. ואם כן \u0003ב\u0004שופר של \u0003ציבור נמי חזי\u0004 \u0005[גם כן ראוי]\u0006 \u0003לגמע\u0004 בו מים \u0003לתינוק עני,\u0004 שפרנסתו מוטלת על הציבור, ואפשר אם כן להשתמש בשופר של ציבור לצרכו. \u0003ותו\u0004 \u0005[ועוד],\u0006 \u0003הא דתניא\u0004 \u0005[\u0006הלכה \u0005זו ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003כשם שמטלטלין את השופר כך מטלטלין את\u0004 ה\u0003חצוצרות,\u0004 שלא כפי ששנינו מקודם שיש חילוק בין טלטול השופר והחצוצרות. \u0003מני\u0004 \u0005[של מי היא]\u0006 הלכה זו? אלא יש לפרש ששלוש המשניות הללו הן לפי שלוש שיטות בהלכות אלה. \u0003הא\u0004 \u0005[\u0006משנה \u0005זו]\u0006 המתירה לטלטל את השופר ולא את החצוצרה שיטת \u0003ר' יהודה\u0004 היא הסבור שיש דיני מוקצה בשבת, וכלי שמלאכתו לאיסור בלבד — אסור לטלטלו וכיון שאין לחצוצרה שימוש של היתר — אין לטלטלה, ואילו השופר שהוא ראוי לשימוש תינוק — מותר בטלטול. ו\u0003הא\u0004 \u0005[\u0006משנה \u0005זו]\u0006 המתירה לטלטל גם שופר גם חצוצרות כשיטת \u0003ר' שמעון\u0004 היא, שלדעתו אין כלל מוקצה מחמת איסור בשבת. ואילו \u0003הא\u0004 \u0005[\u0006ברייתא \u0005זו]\u0006 האוסרת לטלטל גם שופר וגם חצוצרות, כשיטת \u0003ר' נחמיה\u0004 היא, הסבור שכלי שעיקר מלאכתו לאיסור — אסור להשתמש בו בשבת, אפילו לצורך היתר. ואולם, לפי הסברה זו יקשה במקצת האמור שאין מטלטלים לא את השופר ולא את החצוצרות, שהרי אם אין מטלטלים שופר, ודאי שאין מטלטלים חצוצרה!","\u0003ו\u0004אולם יש לומר כי \u0003מאי\u0004 \u0005[מהו]\u0006 ה\u0003שופר\u0004 המוזכר בברייתא זו — \u0003נמי\u0004 \u0005[גם כן]\u0006 הכוונה ל\u0003חצוצרות.\u0004 ו\u0003כ\u0004פי ש\u0003אמר רב חסדא.\u0004 ש\u0003אמר רב חסדא: הני תלת מילי אישתני שמייהו מכי\u0004 \u0005[שלושה דברים אלה השתנה שמם מכאשר]\u0006 \u0003חרב בית המקדש:\u0004 שמה שהיה נקרא \u0003\"חצוצרתא\"\u0004 \u0005[חצוצרה]\u0006 נקרא בדורות האחרונים \u0003\"שופרא\"\u0004 \u0005[שופר],\u0006 ומה שהיה נקרא \u0003\"שופרא\"\u0004 נקרא בדורות האחרונים \u0003\"חצוצרתא\".\u0004 ואותה ברייתא הוזכרה אף היא לפי סגנון זה, המחליף חצוצרה בשופר. ואגב שואלים: \u0003למאי נפקא מינה\u0004 \u0005[מה יוצא ממנה]\u0006 להלכה, מן השמועה שמסר רב חסדא אם קוראים לשופר בשמו הנכון או לא? ומשיבים: שחשוב הדבר \u0003ל\u0004דיני \u0003שופר של ראש השנה,\u0004 שבראש השנה אין תוקעים אלא בשופר (כפוף), ואם יבוא כיום אדם מן העם לשאול במה תוקעים, יש לומר לו שתוקעים בחצוצרה.","והדבר השני שנשתנה שמו הוא, שמה שנקרא \u0003\"ערבה\"\u0004 נקרא בדורות האחרונים \u0003\"צפצפה\",\u0004 ואת הקרוי \u0003\"צפצפה\"\u0004 — קוראים \u0003\"ערבה\".\u0004 ואף על דבר זה שואלים: \u0003למאי נפקא מינה\u0004 \u0005[ומה יצא ממנה]\u0006 משינוי השם הלכה למעשה? ומשיבים: לענין \u0003לולב.\u0004 שלארבעת המינים בלולב כשירה ערבה ולא הצפצפה.","והדבר השלישי שהשתנה שמו, שבעבר היו קוראים לשולחן גדול \u0003\"פתורה\"\u0004 ולשולחן קטן \u0003\"פתורתא\",\u0004 ואחר כך נהפכו הדברים של \u0003\"פתורתא\"\u0004 קוראים בדורות האחרונים \u0003\"פתורה\".\u0004 ושואלים: \u0003למאי נפקא מינה\u0004 \u0005[ומה יצא ממנה]\u0006 משינוי השם הלכה למעשה? ומשיבים: לדיני \u0003מקח וממכר.\u0004 שאם קנה אדם \u0003פתורה\u0004 שיידע שהכוונה לשולחן קטן ולא גדול.","\u0003אמר אביי: אף אנו נאמר\u0004 ונעיר על שינוי במשמעות המילים בדורנו. שמה שנקרא בעבר \u0003\"הובלילא\"\u0004 והוא בתרגום לעברית: המסס, אחת הקיבות של בהמה מעלת גירה, נקראת בדורות האחרונים: \u0003\"בי כסי\"\u0004 \u0005[בית הכוסות]\u0006 שהוא שמה של קיבה אחרת בבהמה, וכן מה שנקרא בעבר \u0003\"בי כסי\",\u0004 נקרא בדורות האחרונים \u0003\"הובלילא\". למאי נפקא מינה\u0004 \u0005[ומה יצא ממנה]\u0006 משינוי השם הלכה למעשה — \u0003ל\u0004ענין \u0003מחט שנמצאת בעובי בית הכוסות,\u0004 שבהלכות טריפות קבעו שמחט שנמצאה תחובה בעובי דופנו של בית הכוסות, אם חדרה המחט רק \u0003מצד אחד\u0004 של בית הכוסות — הבהמה \u0003כשירה. ו\u0004רק אם \u0003נמצאה תחובה באופן שנראית משני צדדים\u0004 — הבהמה \u0003טריפה. ואילו בהמסס גם מחט שנתחבה בדופנו ונשארה בצד אחד\u0004 — טריפה. ולכן יש צורך לדעת להבדיל בין המסס ובית הכוסות.","\u0003ואמר רב אשי: אף אנו נאמר\u0004 על דברים שנשתנה שמם במהלך הדורות, שהעיר שנקראה \u0003\"בבל\"\u0004 בימי המקרא קוראים לה בדורות אחרונים \u0003\"בורסיף\",\u0004 ול\u0003בורסיף\u0004 קוראים בדורות האחרונים \u0003\"בבל\".\u0004"],["\u0003למאי נפקא מינה\u0004 \u0005[ומה יצא ממנה]\u0006 משינוי השם הלכה למעשה — הרי זה \u0003ל\u0004ענין \u0003גיטי נשים,\u0004 שבגיטין יש להקפיד במיוחד שלא לשנות את שם המקום בו נכתב הגט. וראוי אם כן לדעת ששמה של בבל נשתנה בדורות מאוחרים.","","\u0003כירה שהסיקוה\u0004 מערב שבת \u0003בקש,\u0004 או \u0003בגבבא\u0004 (שיירים הנאספים בשדה), שהם דברים הנשרפים מהר — \u0003נותנים עליה\u0004 קדירת \u0003תבשיל\u0004 בשבת, שהרי ודאי כבתה האש בכירה זו עוד מבעוד יום. אבל אם הסיקו את הכירה \u0003בגפת\u0004 (הכוספה, החומר הנשאר משומשומים, זיתים וכיוצא בזה, לאחר שסחטו מהם את השמן) או \u0003בעצים\u0004 — \u0003לא יתן\u0004 עליהם קדירה \u0003עד שיגרוף\u0004 את הגחלים מן הכירה מבעוד יום, או \u0003עד שיתן את האפר\u0004 ויכסה בו את הגחלים, שלא תתלבה האש בשבת. \u0003בית שמאי אומרים:\u0004 אף אחר שגרפוה מן הגחלים מותר להניח עליה רק \u0003חמין\u0004 (מים חמים), שאינם צריכים בישול נוסף ודי להם בחומם, \u0003אבל לא תבשיל,\u0004 שמאחר ובו בדרך כלל נוח לבעל הבית בבישול נוסף, יש לחשוש שמא יבוא ללבות את האש באמצעות חתיית הגחלים\u0003. ובית הלל אומרים: חמין ו\u0004גם \u0003תבשיל. בית שמאי אומרים: נוטלין\u0004 את הקדירה מכירה זו בשבת, \u0003אבל לא מחזירין\u0004 אותה ביום השבת אל הכירה. \u0003ובית הלל אומרים: אף מחזירין.\u0004","\u0003איבעיא להו\u0004 \u0005[נשאלה להם,\u0006 ללומדים\u0005]\u0006 שאלה זו בפירוש המשנה: \u0003האי\u0004 \u0005[\u0006ביטוי \u0005זה\u0006\u0005]\u0006 \u0003\"לא יתן\"\u0004 הכתוב במשנה, האם משמעות \u0003לא יחזיר\u0004 את הקדירה שהורידו אותה מעל האש ורוצים להחזירה בשבת \u0003הוא, אבל לשהות\u0004 (להשהות) קדירה מערב שבת אף ביום השבת — \u0003משהין, אף על פי ש\u0004כירה זו \u0003אינו גרוף\u0004 מגחלים \u0003ואינו קטום\u0004 (שלא שמו עליה אפר = קטמא בארמית). \u0003ו\u0004לפי זה \u0003מני\u0004 \u0005[של מי היא,\u0006 משנה זו\u0005]\u0006 — כשיטת \u0003חנניה היא. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003חנניה אומר: כל\u0004 מאכל \u0003שהוא\u0004 מבושל כבר בעיקרו \u0003כמאכל בן דרוסאי\u0004 שלא היה מבשל מאכליו אלא במדה ההכרחית — \u0003מותר לשהותו על גבי כירה\u0004 בשבת, \u0003אף על פי\u0004 שכירה זו \u0003אינו גרוף ואינו קטום. או דילמא\u0004 \u0005[שמא\u0006\u0005]\u0006 מה ששנינו במשנה \"לא יתן\" — שלא \u0003לשהות\u0004 על האש מערב שבת \u0003תנן\u0004 \u0005[שנינו],\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 הכירה \u0003גרוף וקטום\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 — \u0003לא\u0004 ישאיר את הקדירה, \u0003וכל שכן\u0004 שאין \u0003להחזיר\u0004 אותה על גבי הכירה בשבת. כדי לפתור בעיה זו מציעים: \u0003תא שמע\u0004 \u0005[בא\u0006 ו\u0005שמע\u0006 פתרון\u0005]\u0006 לדבר \u0003מדקתני תרי בבי במתניתין\u0004 \u0005[ממה ששנינו שתי פסקות במשנתנו\u0006\u0005],\u0006 אחת, \u0003בית שמאי אומרים: חמין אבל לא תבשיל. ובית הלל אומרים חמין ותבשיל.\u0004 והשניה, \u0003בית שמאי אומרים: נוטלין אבל לא מחזירין, ובית הלל אומרים: אף מחזירין.\u0004 ומעתה \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אומר אתה]\u0006 שמה שנאמר במשנה ענין לתת, \u0003לשהות תנן\u0004 \u0005[שנינו],\u0006 שלזאת כיוונה המשנה בדבריה, אם כן \u0003הכי קתני\u0004 \u0005[כך שנה,\u0006 כך יש להבין את המשנה\u0005]:\u0006 \u0003כירה שהסיקוה בקש או בגבבא\u0004 — \u0003משהין עליה תבשיל,\u0004 ואם הסיקוה \u0003בגפת או בעצים\u0004 — \u0003לא ישהא\u0004 (ישהה) את התבשיל עליה \u0003עד שיגרוף\u0004 את הגחלים ממנה מבעוד יום, \u0003או עד שיתן\u0004 עליהם \u0003אפר. ומה הן משהין?\u0004 — \u0003בית שמאי אומרים: חמין, אבל לא תבשיל. ובית הלל אומרים:\u0004 יכולים להשהות עליה גם \u0003חמין ו\u0004גם \u0003תבשיל. וכי היכי דפליגי\u0004 \u0005[וכפי ש\u0006הם \u0005חלוקים]\u0006 \u0003ב\u0004ענין ההיתר \u0003לשהות\u0004 את הקדירה על הכירה, \u0003פליגי נמי\u0004 \u0005[כך גם כן\u0006 הם \u0005חלוקים]\u0006 אם מותר \u0003להחזיר\u0004 אותה אליה, \u0003שבית שמאי אומרים: נוטלין\u0004 את הקדירה מן הכירה בשבת, \u0003אבל לא מחזירין\u0004 אותה אליה כלל, \u0003ובית הלל אומרים: אף מחזירין.\u0004","","\u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 כי \u0003להחזיר תנן\u0004 \u0005[שנינו במשנה\u0006\u0005],\u0006 שזאת היתה כוונת המשנה, אם כן לפי זה יוצא כי \u0003הכי קתני\u0004 \u0005[כך שנה\u0006\u0005]:\u0006 \u0003כירה שהסיקוה בקש או בגבבא\u0004 — \u0003מחזירין עליה תבשיל.\u0004 ואם הסיקוה \u0003בגפת או בעצים\u0004 — \u0003לא יחזיר\u0004 אליה את התבשיל \u0003עד שיגרוף\u0004 ממנה מבעוד יום את הגחלים \u0003או עד שיתן אפר\u0004 עליהם. \u0003ומה הם מחזירין?\u0004 — \u0003בית שמאי אומרים: חמין, אבל לא תבשיל. ובית הלל אומרים: חמין ותבשיל. בית שמאי אומרים: נוטלין אבל לא מחזירין. ובית הלל אומרים: אף מחזירין.\u0004 ואולם אם בפסקה הראשונה, עסקנו בשאלה מהם הדברים שמחזירים, \u0003הא תו\u0004 \u0005[זה עוד],\u0006 המחלוקת בפיסקה השניה \u0003למה לי\u0004 לשנותה? והרי כבר אמרנו אותה בלשון אחרת, בפיסקה הראשונה. שהרי \"נוטלין אבל לא מחזירין\" הריהו בדיוק עצם דברי בית שמאי שאין מחזירים את התבשיל לכירה. ואם כן נראה שהמשנה מובנת רק לפי ההסבר הראשון, שבו יש משמעות שונה לכל פסקה!"],["את ההוכחה הזאת דוחים: \u0003לעולם אימא\u0004 \u0005[\u0006יכול \u0005אני לומר]\u0006 \u0003לך\u0004 כי \u0003להחזיר תנן,\u0004 \u0005[שנינו\u0006\u0005],\u0006 \u0003ו\u0004אולם \u0003חסורי מיחסרא והכי קתני\u0004 \u0005[חסרה\u0006 המשנה \u0005וכך יש\u0006 להשלים \u0005ולשנותה\u0006\u0005]:\u0006 \u0003כירה שהסיקוה בקש או בגבבא\u0004 — \u0003מחזירין עליה\u0004 קדירת \u0003תבשיל,\u0004 ואולם אם הסיקוה \u0003בגפת או בעצים\u0004 — \u0003לא יחזיר\u0004 אליה את הקדירה \u0003עד שיגרוף\u0004 ממנה מבעוד יום את הגחלים \u0003או עד שיתן\u0004 עליהם \u0003את האפר. אבל לשהות\u0004 (להשהות) את הקדירה על האש בשבת — \u0003משהין אף על פי שאינו גרוף ואינו קטום.\u0004 ועל ידי תוספת זו נבין את המשך המחלוקת באופן זה: \u0003ומה הן משהין?\u0004 — \u0003בית שמאי אומרים: חמין, אבל לא תבשיל. ובית הלל אומרים: חמין ותבשיל.\u0004 ועוד: \u0003והך\u0004 \u0005[ואותה]\u0006 ה\u0003חזרה דאמרי\u0004 \u0005[שאמרתי]\u0006 \u0003לך\u0004 בתחילת המשנה, \u0003לאו\u0004 \u0005[לא]\u0006 \u0003דברי הכל היא, אלא\u0004 אף היא \u0003מחלוקת בית שמאי ובית הלל, שבית שמאי אומרים: נוטלין ולא מחזירין. ובית הלל אומרים: אף מחזירין.\u0004 ואם כן בעייתנו בדבר פירוש המשנה לא הגיעה לידי פתרון.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון אחר לבעיה זו ממה ששנינו ש\u0003אמר ר' חלבו\u0004 ש\u0003אמר רב חמא בר גוריא\u0004 שכך \u0003אמר רב: לא שנו\u0004 בענין ההיתר בכירה, \u0003אלא\u0004 להניח את הקדירה \u0003על גבה\u0004 של הכירה, \u0003אבל לתוכה\u0004 — \u0003אסור.\u0004 ומעתה \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אומר אתה]\u0006 כי \u0003להחזיר תנן\u0004 \u0005[שנינו]\u0006 — \u0003היינו דשני\u0004 \u0005[זהו ששונה]\u0006 \u0003בין\u0004 דין \u0003תוכה לעל גבה.\u0004 כי אם מחזיר בשבת בתוך כירה שיש בה אולי גחלים בוערות — יש בכך חשש של חילול שבת, ומשום כך הותר רק להניח את התבשיל על גבי הכירה. \u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 כי \u0003לשהות תנן\u0004 \u0005[שנינו]\u0006 שזו היתה כוונת המשנה, אם כן \u0003מה לי תוכה מה לי על גבה?\u0004 שהרי סוף סוף אינו עושה דבר ברמץ שבכירה! הוכחה זו דוחים: \u0003מי סברת\u0004 \u0005[האם סובר אתה]\u0006 כי \u0003ר' חלבו ארישא קאי\u0004 \u0005[על ראש\u0006 המשנה הוא \u0005עומד,\u0006 מתייחס\u0005]?\u0006 לא, אלא \u0003ר' חלבו אסיפא קאי\u0004 \u0005[על הסוף\u0006 שלה הוא \u0005עומד,\u0006 מתייחס\u0005],\u0006 לאותו קטע שבו נאמר \u0003\"ובית הלל אומרים אף מחזירין\". ו\u0004על כך \u0003אמר ר' חלבו\u0004 שכך \u0003אמר ר' חמא בר\u0004 גוריא שכך \u0003אמר רב: לא שנו\u0004 שמחזירים \u0003אלא על גבה, אבל תוכה\u0004 — \u0003אסור.\u0004 ואם כן אף בכך אין תשובה לשאלה.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לשאלה זו ממה ששנינו בתוספתא: \u0003שתי כירות המתאימות\u0004 (צמודות זו לזו ולהן קיר משותף), והיתה \u0003אחת\u0004 מהן \u0003גרופה וקטומה, ואחת שאינה גרופה ואינה קטומה,\u0004 הרי הדין לענין השהיית קדירה בשבת על גביהן הוא: \u0003משהין על גבי\u0004 ה\u0003גרופה וקטומה ואין משהין על שאינה גרופה ואינה קטומה. ו\u0004לגופו של דבר \u0003מה הן משהין?\u0004 — \u0003בית שמאי אומרים: ולא כלום.\u0004 שהם חולקים על עיקר הדין הכתוב למעלה. \u0003ובית הלל אומרים:\u0004 משהין \u0003חמין, אבל לא תבשיל.\u0004 ואולם אם \u0003עקר\u0004 את התבשיל מעל גבי הכירה — ל\u0003דברי הכל לא יחזיר\u0004 אותו על גביה, אלו \u0003דברי ר' מאיר,\u0004 שלפי המסורת שבידו בכך נחלקו בית שמאי ובית הלל. ואילו \u0003ר' יהודה אומר\u0004 שמחלוקת זו שונה היתה. \u0003בית שמאי אומרים:\u0004 משהים עליה \u0003חמין, אבל לא תבשיל. ובית הלל אומרים: חמין ותבשיל.\u0004 ועוד, \u0003בית שמאי אומרים: נוטלין\u0004 את הקדירה מן הכירה בשבת, \u0003אבל לא מחזירין\u0004 אליה. \u0003ובית הלל אומרים: אף מחזירין.\u0004","ואם כן \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אומר אתה]\u0006 כי לענין \u0003לשהות תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]\u0006 אם כן \u0003מתניתין מני\u0004 \u0005[משנתנו\u0006 כדעת \u0005מי היא\u0006\u0005]\u0006 — הרי לפי ההשוואה כשיטת \u0003ר' יהודה היא. אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 כי לענין \u0003להחזיר תנן\u0004 \u0005[שנינו],\u0006 אם כן \u0003מתניתין מני\u0004 \u0005[משנתנו\u0006 כדעת \u0005מי היא\u0006\u0005]?\u0006 האם \u0003לא\u0004 כדברי \u0003ר' יהודה ולא\u0004 כדברי \u0003ר' מאיר.\u0004 שכן \u0003אי\u0004 \u0005[אם\u0006\u0005]\u0006 תאמר שהמשנה כ\u0003ר' מאיר\u0004 — \u0003קשיא\u0004 \u0005[קשה]\u0006 \u0003לבית שמאי בחדא\u0004 \u0005[ב\u0006קושי \u0005אחד\u0006\u0005],\u0006 שהרי במשנתנו התירו בית שמאי להשתמש בכירה בשבת בדרך מסויימת, ולדעת ר' מאיר בברייתא אוסרים הם שימוש זה לחלוטין. \u0003ולבית הלל\u0004 יהיה קשה \u0003בתרתי\u0004 \u0005[בשתי\u0006 קושיות\u0005],\u0006 שלפי הבנתנו במשנה מתירים בית הלל גם חמין וגם תבשיל שלא כדעתם בברייתא, וכן פירשנו במשנה שהתירו בית הלל אף להחזיר שלא כדברי ר' מאיר. ו\u0003אי\u0004 \u0005[אם\u0006\u0005]\u0006 תפרש שמשנתנו כדעת \u0003ר' יהודה\u0004 בברייתא, אם כן \u0003קשיא\u0004 \u0005[קשה\u0006\u0005]\u0006 מ\u0003גרופה וקטומה,\u0004 שבמשנה התירו בית הלל ובית שמאי לפחות להשהות בכירה שאינה גרופה וקטומה, ולר' יהודה בברייתא נראה שכירה שאינה גרופה ואינה קטומה אין משתמשים בה כלל, וכיון שדרך פירוש זו למשנה מביאה לידי סתירות, מוטב איפוא לפרש בשיטה האחרת, שלפיה תהיה המשנה כשיטה אחת.","טענה זו דוחים: \u0003לעולם אימא\u0004 \u0005[אומר]\u0006 \u0003לך\u0004 כי לענין \u0003להחזיר תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005],\u0006 \u0003ו\u0004ה\u0003תנא דידן סבר לה\u0004 \u0005[שלנו,\u0006 במשנה \u0005סבור]\u0006 \u0003כר' יהודה בחדא ופליג עליה בחדא\u0004 \u0005[ב\u0006נקודה \u0005אחת וחולק עליו באחת];\u0006 \u0003סבר\u0004 \u0005[סבור]\u0006 הוא \u0003כר' יהודה בחדא\u0004 \u0005[באחת\u0006\u0005]\u0006 — \u0003ב\u0004ענין \u0003חמין ותבשיל, ו\u0004כן ביחס להבדל מה \u0003נוטלין\u0004 מן הכירה \u0003ו\u0004מה אף \u0003מחזירין. ופליג עליה בחדא\u0004 \u0005[וחלק עליו באחת\u0006\u0005]\u0006 — ש\u0003אילו\u0004 ה\u0003תנא דידן סבר\u0004 \u0005[שלנו\u0006 במשנה \u0005סבור\u0006\u0005]\u0006 כי מותר \u0003לשהות\u0004 בכירה \u0003ואף על פי שאינו גרוף וקטום, ו\u0004אילו \u0003ר' יהודה סבר\u0004 כי \u0003ב\u0004ענין ההיתר \u0003לשהות נמי\u0004 \u0005[גם כן\u0006\u0005]\u0006 אם היתה הכירה \u0003גרוף וקטום\u0004 — \u0003אין\u0004 \u0005[כן\u0006\u0005]\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003לא\u0004 היתה גרופה וקטומה — \u0003לא.\u0004","\u0003איבעיא להו\u0004 \u0005[נשאלה להם,\u0006 לתלמידים\u0005]\u0006 בעיה זו: כירה שאינה גרופה ואינה קטומה \u0003מהו\u0004 הדין לענין ההיתר \u0003לסמוך בה\u0004 תבשיל שיתחמם מדפנות הכירה? וצדדי השאלה: האם נאמר שרק ב\u0003תוכה ו\u0004על \u0003גבה אסור,\u0004 אבל \u0003לסמוך בה\u0004 — \u0003שפיר דמי\u0004 \u0005[יפה,\u0006 ראוי \u0005הוא\u0006\u0005],\u0006 \u0003או דילמא לא שנא\u0004 \u0005[שמא אין\u0006 זה \u0005שונה\u0006\u0005],\u0006 ובכל מקרה אסור.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לבעיה זו ממה ששנינו בברייתא: \u0003שתי כירות המתאימות, אחת גרופה וקטומה ואחת שאינה גרופה וקטומה, משהין\u0004 את התבשיל בשבת \u0003על גבי\u0004 הכירה ה\u0003גרופה וקטומה.\u0004 והרי שמותר לסמוך קדירה לכירה שלא נגרפה \u0003ואף על גב דקא סליק ליה הבלא מאידך\u0004 \u0005[ואף על פי שעולה בה הבל מן\u0006 הכירה \u0005האחרת\u0006\u0005]!\u0006 ודוחים: \u0003דילמא שאני התם\u0004 \u0005[שמא שונה שם]\u0006 בשתי כירות מתאימות ש\u0003כיון דמידליא\u0004 \u0005[ש\u0006הקדירה \u0005מודלית,\u0006 מוגבהת\u0005]\u0006 \u0003שליט\u0004 \u0005[שולט]\u0006 \u0003בה אוירא\u0004 \u0005[האויר]\u0006 ומצנן אותה, ואין זה כסמיכה של ממש לכירה.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון אחר לבעיה זו ממה ששנינו ש\u0003אמר רב ספרא\u0004 שכך \u0003אמר רב חייא:\u0004 כירה ש\u0003קטמה\u0004 (כיסה אותה באפר) בערב שבת \u0003ונתלבתה\u0004 אחר כך בשבת, \u0003סומכין לה ומקיימין עליה\u0004 תבשיל המצוי עליה, \u0003ונוטלין\u0004 אותו \u0003ממנה ו\u0004אף \u0003מחזירין\u0004 אותו \u0003לה.\u0004 ומכאן \u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 כי לענין \u0003לסמוך נמי\u0004 \u0005[גם כן]\u0006 אם \u0003קטמה\u0004 — \u0003אין,\u0004 ואולם אם \u0003לא קטמה\u0004 — \u0003לא,\u0004 שהרי דובר בכירה קטומה מבעוד יום כדינה. אף הוכחה זו נדחית: \u0003ולטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005]\u0006 \u0003\"נוטלין ממנה\" דקתני\u0004 \u0005[ששנינו\u0006\u0005]\u0006 האם גם שם תאמר שאם \u0003קטמה\u0004 — \u0003אין\u0004 \u0005[כן\u0006\u0005]\u0006 ואם \u0003לא קטמה\u0004 — \u0003לא?!\u0004 והרי לכל הדעות מותר להוריד קדירה מכירה, אף שאינה גרופה וקטומה! \u0003אלא\u0004 יש להבין כי \u0003תנא\u0004 \u0005[שנה]\u0006 היתר \u0003נוטלין משום\u0004 היתר \u0003מחזירין,\u0004 וכן \u0003הכא נמי תנא\u0004 \u0005[כאן גם כן שנה\u0006\u0005]\u0006 היתר \u0003סומכין משום\u0004 היתר \u0003מקיימין,\u0004 ואין להסיק מכאן שאין לסמוך בדרך אחרת.","על טענה זו תמהים: \u0003הכי השתא\u0004 \u0005[כיצד אתה משווה]?!\u0006 \u0003התם\u0004 \u0005[שם\u0006\u0005]\u0006 \u0003נוטלין ומחזירין בחד מקום\u0004 \u0005[במקום אחד]\u0006 \u0003הוא,\u0004 ומשום כך \u0003תנא\u0004 \u0005[שנה\u0006\u0005]\u0006 \u0003נוטלין משום מחזירין,\u0004 שהרי יש דמיון בין הדברים. \u0003אלא הכא\u0004 \u0005[כאן]\u0006 — \u0003סומכין בחד מקום\u0004 \u0005[במקום אחד]\u0006 \u0003הוא ומקיימין בחד מקום\u0004 \u0005[במקום אחד]\u0006 \u0003הוא,\u0004 ואם לא רצה התנא להדגיש את הדבר לא היה אגב הזכרת \"מקיימים\" גם אומר שמותר להיות סומכים. ואולם מכל מקום ראיה גמורה אין כאן והבעייה לא נפתרה.","ושואלים: \u0003מאי הוי עלה\u0004 \u0005[מה היה עליה,\u0006 על בעיה זו\u0005]?\u0006 \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה ששנינו בתוספתא: \u0003כירה שהסיקוה בגפת\u0004 או \u0003בעצים סומכין לה\u0004 קדירת תבשיל, \u0003ו\u0004אולם \u0003אין מקיימין\u0004 קדירה בתוכה \u0003אלא אם כן\u0004 הכירה \u0003גרופה וקטומה. גחלים שעממו או שנתן עליה נעורת של פשתן\u0004 דקה ולא נתלבתה האש — \u0003הרי היא כקטומה\u0004 ואינו צריך להוסיף עוד אפר עליה. ומכל מקום למדנו מכאן שמותר לסמוך תבשיל ליד כירה, אף שאינה גרופה וקטומה.","\u0003אמר ר' יצחק בר נחמני\u0004 שכך \u0003אמר ר' אושעיא:\u0004 כירה ש\u0003קטמה והובערה\u0004 בשבת \u0003משהין עליה חמין ש\u0004כבר \u0003הוחמו כל צורכן ותבשיל ש\u0004כבר \u0003בישל\u0004 (נתבשל) \u0003כל צורכו,\u0004 שמאחר שאין צורך להוסיף ולבשל את אלה, אין איפוא חשש שמא יבוא לחתות בגחלים וללבות את האש."],["\u0003שמע מינה מצטמק ויפה לו\u0004 (שיהא זה לו לתועלת וישתבח טעמו) בכל זאת \u0003מותר\u0004 להשהותו כיון שכבר נתבשל כל צורכו, ואין חוששים שמא יבוא לחתות בגחלים וללבות את האש, שלא חילק ר' אושעיא בין תבשיל לתבשיל בהיתרו זה! את המסקנה הזאת דוחים: \u0003שאני הכא\u0004 \u0005[שונה כאן\u0006\u0005]\u0006 ש\u0003קטמה\u0004 לכירה זו, שכיסה את הגחלים באפר, ורק כיון שקטמה התירו להשהות כל תבשיל. ומקשים: \u0003אי הכי מאי למימרא\u0004 \u0005[ואם כך מה\u0006 היה טעם \u0005לומר\u0006 הלכה זו\u0005]?!\u0006 שהרי אם קטמה אין עוד חשש בה! ומשיבים: המקרה שקטמה ובשבת \u0003הובערה איצטריכא ליה\u0004 \u0005[הוצרך לו]\u0006 להדגשה יתירה, שכן \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 כי \u0003כיון\u0004 ש\u0003הובערה הדרא לה למילתא קמייתא\u0004 \u0005[חזרה לדברה,\u0006 לדינה \u0005הראשון\u0006\u0005],\u0006 על כן \u0003קמשמע לן\u0004 \u0005[השמיע לנו\u0006\u0005]\u0006 שאינו כן.","\u0003אמר רבה בר בר חנה\u0004 שכך \u0003אמר ר' יוחנן:\u0004 כירה שגרפה ו\u0003קטמה\u0004 מערב שבת \u0003והובערה\u0004 לאחר מכן בשבת, \u0003משהין עליה חמין ש\u0004כבר \u0003הוחמו כל צורכן ותבשיל ש\u0004כבר \u0003בישל כל צורכו, ואפילו\u0004 היו אלה \u0003גחלים של רותם\u0004 שחומן רב ובעירתן ממושכת. ואם כן \u0003שמע מינה\u0004 \u0005[למד ממנה\u0006\u0005]\u0006 שאף באופן ש\u0003מצטמק\u0004 התבשיל בהיותו מונח על גבי הכירה \u0003ויפה לו\u0004 — \u0003מותר.\u0004 ודוחים: \u0003שאני הכא\u0004 \u0005[שונה כאן]\u0006 במקרה זה ש\u0003קטמה\u0004 ולכן הותר להשהות עליה. ושואלים: \u0003אי הכי מאי למימרא\u0004 \u0005[אם כך מה\u0006 היה טעם \u0005לאומרה]?!\u0006 ומשיבים: המקרה ש\u0003הובערה\u0004 לאחר הקטימה \u0003אצטריכא ליה\u0004 \u0005[הוצרך לו]\u0006 להשמיע בו חידוש. ומקשים על הסבר זה: הלא \u0003היינו הך\u0004 \u0005[זהו זה],\u0006 כלומר, הרי זהה הלכה זו להלכה הקודמת, ומה ראה ר' יוחנן לחזור על דבר שנאמר כבר? ומשיבים בכל זאת יש בדבריו חידוש, כי \u0003גחלים של רותם אצטריכא ליה\u0004 \u0005[הוצרכה לו\u0006 להשמיע\u0005]\u0006 שאף בגחלים חמות אלה מותר.","\u0003אמר רב ששת\u0004 שכך \u0003אמר ר' יוחנן: כירה שהסיקוה\u0004 לכירה \u0003בגפת\u0004 או \u0003בעצים משהין עליה חמין אף שלא הוחמו\u0004 עדיין \u0003כל צורכן ו\u0004כן \u0003תבשיל\u0004 אף \u0003שלא בישל\u0004 (נתבשל) עדיין \u0003כל צורכו.\u0004 ואולם אם \u0003עקר\u0004 את התבשיל מהכירה — \u0003לא יחזיר\u0004 אותו אליה \u0003עד שיגרוף\u0004 ממנה את הגחלים מבעוד יום \u0003או עד שיתן\u0004 עליה \u0003אפר.\u0004 וסיבת הלכה זו כי \u0003קסבר\u0004 \u0005[הוא סבור]\u0006 כי \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 לענין \u0003להחזיר תנן\u0004 \u0005[שנויה\u0006\u0005],\u0006 \u0003אבל\u0004 לענין \u0003לשהות\u0004 על גבי הכירה אם הונחה הקדירה עליה מבעוד יום — \u0003משהין אף על פי שאינו גרוף ואינו קטום.\u0004","\u0003אמר רבא: תרווייהו תננהי\u0004 \u0005[\u0006את \u0005שניהם\u0006 שני פרטי הדינים של רב ששת \u0005שנינו\u0006\u0005],\u0006 ולא היה צורך להודיענו דבר המפורש כבר במשנה. את ההיתר \u0003לשהות תנינא\u0004 \u0005[שנינו\u0006\u0005]:\u0006 \u0003אין נותנין את הפת בתוך התנור עם חשיכה ולא\u0004 מניחין \u0003חררה\u0004 (עוגה שטוחה) \u0003על גבי גחלים אלא כדי\u0004 שיהא זמן עד השבת \u0003שיקרמו פניה\u0004 (שיעלה קרום של בצק אפוי על הלחם או החררה). ואולם \u0003הא\u0004 \u0005[הרי]\u0006 אם כבר \u0003קרמו פניה\u0004 לפני השבת — \u0003שרי\u0004 \u0005[מותר\u0006\u0005]\u0006 להשהותה אף בתנור שלא נגרף ולא נקטם. וכן \u0003להחזיר נמי תנינא\u0004 \u0005[גם כן שנינו\u0006\u0005]\u0006 במשנתנו, ש\u0003בית הלל אומרים: אף מחזירין ו\u0004ברור כי \u0003עד כאן לא\u0004 שמענו כי \u0003קשרו\u0004 \u0005[התירו\u0006\u0005]\u0006 \u0003בית הלל\u0004 להחזיר \u0003אלא ב\u0004כירה \u0003גרופה וקטומה, אבל בשאינה גרופה וקטומה לא\u0004 התירו. ואם כן לא היה צורך בדברי רב ששת! \u0003ו\u0004משיבים: \u0003רב ששת נמי דיוקא דמתניתין קא משמע לן\u0004 \u0005[גם כן את הדיוק של המשנה השמיע לנו\u0006\u0005]\u0006 ולא התכוין לחדש הלכות אלא להסביר שכך יש להסיק מן המשנה.","\u0003אמר רב שמואל בר יהודה\u0004 שכך \u0003אמר ר' יוחנן: כירה שהסיקוה בגפת\u0004 או \u0003בעצים משהין עליה תבשיל ש\u0004כבר \u0003בישל כל צורכו ו\u0004כן \u0003חמין ש\u0004כבר \u0003הוחמו כל צורכן\u0004 מערב \u0003שבת, ואפילו\u0004 היה התבשיל ממין כזה שכאשר הוא מונח זמן ממושך על גבי האש הריהו \u0003מצטמק ויפה לו,\u0004 מכל מקום אין חוששים שמא יחתה בגחלים. ומסופר כי \u0003אמר ליה ההוא מדרבנן\u0004 \u0005[לו אחד החכמים]\u0006 \u0003לרב שמואל בר יהודה: הא\u0004 \u0005[הרי]\u0006 \u0003רב ושמואל דאמרי תרווייהו\u0004 \u0005[שאמרו שניהם\u0006\u0005]\u0006 שכאשר התבשיל מונח על גבי כירה והריהו \u0003מצטמק ויפה לו\u0004 ש\u0003אסור\u0004 להשהותו על גבי הכירה בשבת, וזהו אם כן היפך דבריך!","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 רב שמואל בר יהודה: \u0003אטו לית אנא ידע\u0004 \u0005[וכי אין אני יודע\u0006\u0005]\u0006 ש\u0003אמר רב יוסף\u0004 שכך \u0003אמר רב יהודה\u0004 שכך \u0003אמר שמואל\u0004 שכאשר משהים התבשיל את התבשיל זמן ממושך על גבי האש הריהו \u0003מצטמק ויפה לו\u0004 — \u0003אסור\u0004 להשהותו? \u0003כי קאמינא\u0004 \u0005[כאשר אמרתי]\u0006 \u0003לך\u0004 שמותר להשהותו, הרי \u0003ל\u0004שיטת \u0003ר' יוחנן קאמינא\u0004 \u0005[אמרתי\u0006\u0005].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב עוקבא ממישן לרב אשי: אתון דמקרביתו\u0004 \u0005[אתם שהנכם קרובים]\u0006 \u0003ל\u0004מקומם של \u0003רב ושמואל\u0004 — \u0003עבידו\u0004 \u0005[עשו]\u0006 \u0003כ\u0004שיטת \u0003רב ושמואל, אנן נעביד\u0004 \u0005[אנחנו נעשה]\u0006 \u0003כ\u0004שיטת \u0003ר' יוחנן.\u0004","ולגופו של דבר \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרב יוסף: מהו\u0004 הדין לענין \u0003לשהות? אמר ליה\u0004 \u0005[לו]\u0006 רב יוסף: \u0003הא\u0004 \u0005[הרי]\u0006 \u0003רב יהודה משהו ליה ואכיל\u0004 \u0005[\u0006היו \u0005משהים לו ו\u0006היה \u0005אוכל\u0006\u0005],\u0006 ומכאן שמותר לעשות זאת. \u0003אמר ליה\u0004 \u0005[לו]\u0006 אביי: \u0003בר מיניה\u0004 \u0005[חוץ ממנו]\u0006 מ\u0003רב יהודה,\u0004 אל תוכיח ממנו, ש\u0003כיון\u0004 ש\u0003מסוכן הוא\u0004 שהוא חולה וזקוק לאוכל חם — \u0003אפילו בשבת נמי שרי למעבד ליה\u0004 \u0005[גם כן מותר לעשות לו]\u0006 כך. ואולם \u0003לי ולך\u0004 כלשאר בני אדם \u0003מאי\u0004 \u0005[מה\u0006 הדין\u0005]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יוסף לאביי: \u0003בסורא משהו\u0004 \u0005[משהים\u0006\u0005],\u0006 \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003רב נחמן בר יצחק\u0004 איש סורא \u0003מרי דעובדא הוה, ומשהו ליה, ואכיל\u0004 \u0005[בעל מעשים היה\u0006 ומדקדק במצוות, \u0005והיו משהים לו, ואוכל\u0006\u0005].\u0006 \u0003אמר רב אשי: קאימנא קמיה\u0004 \u0005[עמדתי לפניו]\u0006 לפני \u0003רב הונא ושהין ליה כסא דהרסנא\u0004 \u0005[וראיתי ששהו לו\u0006 על גבי הקדירה בשבת \u0005דגים מטוגנים בשמן]\u0006 \u0003ואכל\u0004 אותם בשבת, \u0003ולא ידענא\u0004 \u0005[ואיני יודע]\u0006 טעמו \u0003אי\u0004 \u0005[אם]\u0006 \u0003משום דקסבר\u0004 \u0005[שהוא סבור\u0006\u0005]\u0006 כי כאשר משהים את התבשיל \u0003זמן ממושך על גבי האש והריהו מצטמק ויפה לו\u0004 — \u0003מותר\u0004 להשהותו, \u0003אי\u0004 \u0005[אם]\u0006 \u0003משום\u0004 ש\u0003כיון דאית ביה מיחא\u0004 \u0005[שיש בו\u0006 בתבשיל זה \u0005קמח]\u0006 הרי \u0003מצטמק ורע לו הוא,\u0004 ולדעת הכל מותר להשהות את המצטמק ורע לו.","\u0003אמר רב נחמן:\u0004 כאשר התבשיל המונח על גבי הכירה \u0003מצטמק ויפה לו\u0004 — \u0003אסור\u0004 להשהות, \u0003מצטמק ורע לו\u0004 — \u0003מותר. כללא דמלתא\u0004 \u0005[כללו של דבר]:\u0006 \u0003כל\u0004 תבשיל \u0003דאית ביה מיחא\u0004 \u0005[שיש בו קמח]\u0006 — הריהו \u0003מצטמק ורע לו, לבר\u0004 \u0005[חוץ]\u0006 \u0003מתבשיל דליפתא\u0004 \u0005[של לפת]\u0006 \u0003דאף על גב דאית ביה מיחא\u0004 \u0005[שאף על פי שיש בו קמח]\u0006 — \u0003מצטמק ויפה לו הוא. והני מילי דאית ביה בשרא\u0004 \u0005[ודברים אלה\u0006 אמורים דווקא באופן \u0005שיש בו בשר],\u0006 \u0003אבל\u0004 כאשר \u0003לית ביה בשרא\u0004 \u0005[אין בו בשר]\u0006 — \u0003מצטמק ורע לו הוא. וכי אית ביה בשרא נמי לא אמרן\u0004 \u0005[וכאשר יש בו בשר גם כן לא אמרנו]\u0006 שמצטמק ויפה לו הוא \u0003אלא\u0004 כשהוא \u0003לא קבעי לה\u0004 \u0005[צריך\u0006 הוא \u0005אותו]\u0006 \u0003לאורחין\u0004 (אורחים), \u0003אבל\u0004 כאשר \u0003קבעי לה\u0004 \u0005[הוא צריך אותו]\u0006 \u0003לאורחין\u0004 — הריהו \u0003מצטמק ורע לו.\u0004 שאין זה נאה לתת לפני האורחים תבשיל מצומק שאין צורתו יפה. ועוד: \u0003לפדא דייסא ותמרי\u0004 \u0005[מאכל תאנים, דייסא ותמרים\u0006\u0005]\u0006 ההשהייה גורמת לכך ש\u0003מצטמק ורע להן.\u0004","\u0003בעו מיניה\u0004 \u0005[שאלו\u0006 \u0005ממנו]\u0006 \u0003מר' חייא בר אבא\u0004 שאלה זו:"]]};
